/**
 * A chest the player has opened: where it stands, its LIVE contents array, and the call that marks
 * its column dirty. The array is shared with the world's own record by reference — one array, one
 * truth, so a panel that shows 40 stone and a save that holds 40 stone cannot come apart.
 */
export interface OpenChest { x: number; y: number; z: number; slots: Slots; touch: () => void }

/**
 * A bench the player has opened. Mirrors `OpenChest`: position plus a bound writer, never a copy of
 * the job — the panel derives everything else from `workshop.ts` and the wall clock, so there is no
 * second version of the truth to drift.
 */
interface OpenStation {
  x: number; y: number; z: number
  /** Which station this block is — decides the rate and the recipe list. */
  kind: StationId
  job: StationJob | undefined
  commit: (shop: Workshop) => void
}

/**
 * Which grid a slot click means. The bag and an open chest are two grids inside ONE panel, so a
 * lifted stack has to name where it came from — an index alone was enough while there was only the
 * bag, and stops being enough the moment a second grid is on screen.
 */
type SlotRef = { g: 'bag' | 'chest'; i: number }

/**
 * A lifted slot, plus HOW it was lifted. A right-click lift means "half of this", and that intent
 * has to survive until the placing click, because the place is where the amount is finally decided.
 *
 * ★ NOTHING LEAVES THE GRID AT LIFT TIME, not even a half. The items sit in their slot until the
 * second click moves them, so closing the panel, refreshing, or crashing mid-split loses exactly
 * nothing — there is no floating carried stack to strand. That is the same reason drag is
 * click-then-click rather than HTML5 drag-and-drop, one level in.
 */
type Lift = SlotRef & { mode: LiftMode }

/**
 * What a lift is going to do when it lands, named rather than inferred. `whole` swaps or merges the
 * stack, `half` places half of it, `one` deals a single item and stays lifted.
 *
 * ★ It is a MODE, not a `half: boolean`, because the third verb arrived (the right-drag sprinkle)
 * and a boolean would have had to answer "is a sprinkle half?" — a question with no true answer, so
 * whichever way it was answered the badge and the highlight would have lied about one of the two.
 */
type LiftMode = 'whole' | 'half' | 'one'

const SEED = 1337
const H = DEFAULT_COLUMN.worldHeight
// Load-ring radius lives in settings now (viewRadius, O panel) — the World loops read it live.
const REACH = 6            // how far you can mine or place, in voxels
const key = (cx: number, cz: number) => `${cx},${cz}`
/** Non-air materials light still passes through — light.ts's "air, water and foliage" contract.
 *  (Water is handled by id in the opaque callback; foliage is enumerated here.) */
const LIGHT_PASSES = new Set<number>([
  WOOD.GOLDWOOD_LEAVES, WOOD.SHIMMEROAK_LEAVES, WOOD.STARWILLOW_LEAVES, WOOD.DAWNWOOD_LEAVES,
])

// ── ★ SPAWN MOVES TO MOONWELL GLADE (2026-08-08) ──────────────────────────────────────────────
// Read off the zone anchor rather than hardcoded, so spawn can never drift out of sync with the
// glade if its anchor ever moves. `save.ts`'s header rules that a save grows with what you BUILD,
// not with where you have walked — player POSITION is deliberately never persisted, so there is no
// returning-keeper position to preserve here. That is what satisfies "only new characters spawn in
// the glade": position-wise, there is no other kind of character. If per-keeper position saving is
// ever added, it must gate this and read the saved spot instead — do not remove this comment
// without adding that gate.
const GLADE = ZONE_ANCHORS.find(z => z.id === 'moonwell-glade')!
const SPAWN_X = GLADE.x
const SPAWN_Z = GLADE.z

// Greg stands a few blocks off spawn so a freshly-born keeper does not spawn inside him.
// GREG_X/GREG_Z are the voxel COLUMN he stands in (columnHeight wants integers); GREG_CX/GREG_CZ
// are that column's centre, which is where the mesh and the aim box both actually read —
// same +0.5 centring the rest of the file uses (spawn, hollow spawns, drop-vs-block math).
const GREG_X = SPAWN_X + 3
const GREG_Z = SPAWN_Z + 1
const GREG_CX = GREG_X + 0.5
const GREG_CZ = GREG_Z + 0.5
const GREG_Y = columnHeight(GREG_X, GREG_Z, SEED) + 1
/** How far down the ray you can reach him. Was a radius; now a distance to the box's near face. */
const GREG_TALK_RANGE = 3
/** Greg's body in WORLD space — `greg.ts`'s own part dimensions, lifted to where he stands. */
const GREG_BOX = bodyBox(GREG_CX, GREG_CZ, GREG_Y + GREG_BOUNDS.y0, GREG_Y + GREG_BOUNDS.y1, GREG_BOUNDS.halfW)

/** Every log a blade can fell — the 'cut' step reads the whole set, not one species; Greg never
 *  said which tree.
 *  ⚠ Must stay exactly the set `isLogMat` (trees.ts) describes. Kept as a literal Set only because
 *  the quest step wants `.has`; if a fifth species is ever ruled, both change or neither does. */
const LOG_MATERIALS = new Set<number>([
  WOOD.GOLDWOOD_LOG, WOOD.SHIMMEROAK_LOG, WOOD.STARWILLOW_LOG, WOOD.DAWNWOOD_LOG,
])

/** Column keys the gate's whole footprint touches — checked before the first build so a 5-wide arch
 *  straddling a SECTION seam does not silently drop whichever half lands in an unloaded neighbour. */
const GATE_COLS: string[] = (() => {
  const half = 2
  const pts: [number, number][] = GATE_SPANS_X
    ? [[GATE_X - half, GATE_Z], [GATE_X + half, GATE_Z]]
    : [[GATE_X, GATE_Z - half], [GATE_X, GATE_Z + half]]
  return [...new Set(pts.map(([x, z]) => key(Math.floor(x / SECTION), Math.floor(z / SECTION))))]
})()

interface Slot { itemId: string; count: number }

/**
 * ★ TOOLS LEFT THE HOTBAR AND BECAME SOCKETS (Alex, 2026-08-07, late — overturns the same-day
 * "hotbar carries the tools" ruling above the mining block): *there is no manual tool selection —
 * the block auto-picks the tool.* Scrolling to "the tool you need" was a step nobody wanted to take
 * mid-swing, and it fought the block-picks-the-tool model this port started with.
 *
 * The hotbar is ITEMS ONLY now — 8 FIXED slots, numbered 1-8, always rendered whether occupied or
 * not. The four gathering families (still canon order: forestry, prospecting, rinning, farming)
 * render as read-only ROUND SOCKETS in a quarter-arc off the hotbar's right end (Alex's whiteboard,
 * 2026-08-07 — the rectangular gauge cards this section shipped with hours earlier were rejected as
 * "three steps backwards") — level, equipped tier, XP-ring, driven by `activeTool` (see the mining
 * block) rather than by anything the player selects.
 */
const TOOL_FAMILIES = ['forestry', 'prospecting', 'rinning', 'farming'] as const
type HotbarEntry = { itemId: string; count: number }

/**
 * ── ★ VOXEL ITEMS STACK (2026-08-11) ────────────────────────────────────────────────────────────
 * `engine/inventory.getMaxStack` reads the 2D game's ITEMS/FURNITURE tables and returns **1** for
 * anything it does not recognise — and it recognises none of this world's block items. Measured:
 * `addItems(inv, 'block_topsoil', 64)` filled all 24 slots and returned 40 LEFTOVER, and every
 * caller here discarded that return. So an inventory filled at 24 items and everything mined after
 * that was silently destroyed. The count-derived hotbar hid it perfectly by showing a running total.
 *
 * Fixed HERE rather than by adding block ids to the 2D tables: those tables belong to another game
 * whose balance is not ours, and a voxel world's answer to "how many blocks in a slot" is a
 * property of THIS world. `give` is the only way items enter the bag now, so the stack size cannot
 * be forgotten at a call site.
 */
export const VOXEL_STACK = 99

/**
 * ── ★ STACK SIZE IS A BALANCE LEVER, NOT A CONSTANT (2026-08-11, Alex asked) ────────────────────
 * The first cut stacked EVERYTHING to 99, which is fine for dirt and wrong for the rest: how many
 * of a thing fit in a slot is the game saying how precious it is, and a bag that carries 99 of
 * anything says nothing is. So the ladder below is deliberately short and readable:
 *
 *   · 99 — ground you dig by the hundred: soil, stone, sand, grass, planks, slabs.
 *   · 16 — things you MAKE and place one at a time. A lantern or a pot is a decision, and
 *          carrying sixteen already means never walking home for one.
 *   ·  4 — a Mana Seed. It pays out a SPIRIT (canon: the seed chooses you), so it is the single
 *          most valuable item in the world. Stacking it like dirt would say otherwise in the one
 *          place a player actually looks. Four is "a good haul", not "a resource".
 *
 * Unlisted ids fall to 99 on purpose: a new BLOCK is the common case, and the failure mode of a
 * too-generous default is a mild balance miss, while a too-strict one is a bag that fills up for
 * reasons nobody can see. Precious things are the exception and exceptions get written down.
 */
const STACK_OVERRIDE: Record<string, number> = {
  mana_seed: 4,
  clay_pot: 16,
  mana_lantern: 16,
  crafting_table: 16,
  chest: 16,
}

export const maxStackOf = (itemId: string): number => STACK_OVERRIDE[itemId] ?? VOXEL_STACK

/**
 * Add to the bag with this world's stack size. Returns what did NOT fit.
 *
 * ★ THE ONLY WAY ITEMS ENTER THE BAG, and it deliberately does NOT go through
 * `engine/inventory.addItems` any more (2026-08-11, the chests pass). That function carries the 2D
 * game's rules — its stack table answers 1 for every block here, and its furniture rule refuses to
 * put furniture in a hotbar band that means something else in this world. `chest` is already an id
 * in the 2D FURNITURE table, so a crafted chest silently inherited that rule while `roomFor` below
 * did not, which made a walked-over chest vanish. See `addToGrid`'s header for the whole autopsy.
 */
function give(inv: Inventory, itemId: string, count: number): number {
  return addToGrid(inv.slots, itemId, count, maxStackOf)
}

/** How many more of `itemId` the bag could take right now. Drives the pickup gate in `tickDrops`. */
function roomFor(inv: Inventory, itemId: string): number {
  const max = maxStackOf(itemId)
  let room = 0
  for (const s of inv.slots) {
    if (!s) room += max
    else if (s.itemId === itemId && s.count < max) room += max - s.count
  }
  return room
}

/**
 * What to CALL an item on screen.
 *
 * Prefers the registry's block name ('Goldwood Planks') over the id ('goldwood_plank'), because the
 * registry is where a designer already writes the player-facing name and a second list of pretty
 * names is a second thing to forget. Falls back to de-snaking the id so a purely-crafted item with
 * no block behind it — a shard, a seed — still reads as words rather than code.
 */
/**
 * The visual for one item, at one size.
 *
 * ★ ONE COMPONENT FOR BOTH SURFACES. The hotbar and the satchel had independently-written swatch
 * markup, which is two places for an item to look like two different things — the same shape as the
 * sprite pipeline's three frame maps. `itemIcon` derives the picture from the block's own texture;
 * the colour chip is the honest fallback for items with no block behind them (a seed, a shard),
 * left plain on purpose so it reads as "no art yet" rather than as finished.
 */
function ItemChip({ itemId, size }: { itemId: string; size: number }) {
  const icon = itemIcon(itemId)
  if (icon) return <img src={icon} alt="" width={size} height={size} className="[image-rendering:pixelated]" draggable={false} />
  const mat = materialForItem(itemId)
  const swatch = mat !== undefined ? `#${(MATERIAL_COLOR[mat] ?? 0x888888).toString(16).padStart(6, '0')}` : undefined
  return <span className="rounded-sm border border-black/40" style={{ width: size, height: size, background: swatch ?? 'rgba(255,255,255,0.25)' }} />
}

export function itemLabel(itemId: string): string {
  const m = materialForItem(itemId)
  const named = m !== undefined ? blockDef(m)?.name : undefined
  return named ?? itemId.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
}

// ── ★ THE DEV CONSOLE (T) — commands over every aspect of the game (2026-08-08, Alex) ─────────
// One registry, one runner. A command is a row here and a capability on `ConsoleCtx`; the day a
// system exists (weather, seasons, spirits), its command is a five-line append — the console is
// the standing INTERFACE, the registry is what grows. Cheat-grade verbs (give, tp) are owner-gated;
// view-grade verbs (time — the pin is per-tab, it never touches the shared wall clock) are not.
interface ConsoleCtx {
  isOwner: boolean
  setRadius: (r: number) => void
  radius: () => number
  give: (id: string, n: number) => string
  tp: (x: number, z: number) => string
  /** Player position, for `~` relative coordinates (MC's convention, ported with the chat). */
  pos: () => { x: number; z: number }
  /**
   * The garden, as the console can see and touch it. `list` is VIEW-GRADE — a keeper reading their
   * own roster is not a cheat, and it is the one thing that explains a refused spar prompt. The
   * other three write to the SHARED save (`ather:save:shimmer`, the same spirits the 2D game and
   * play3d own), so they are owner-only: a lent test party landing in a real keeper's garden would
   * be a cheat that also overwrites the save it cheated into.
   */
  party: {
    list: () => string
    lend: (count: number, level: number) => string
    heal: () => string
    clear: () => string
  }
  /** The withdrawal ledger, so `/mist` can name who is standing in a patch rather than only where
   *  it lies. View-grade: it reports what walking there would show you anyway, one scale further. */
  mistLedger: () => MistLedger
  /**
   * ★ THE RUNES A KEEPER HOLDS. Bare `/rune` is VIEW-GRADE — reading your own hand is not a cheat,
   * and it is the one thing that explains why a cast key does nothing. GRANTING is cheat-grade and
   * checked inside, exactly as `/goto`'s compass-vs-teleport split does it.
   *
   * ⚠ THIS IS A TEST HARNESS, NOT THE ACQUISITION SYSTEM. Canon ruled acquisition on 2026-08-03:
   * a rune is trained off the birth rune along its lane (element row / state column), never bought;
   * a Knowledge Scroll teaches a MOVE, never a rune, and the Passage under Rune Hold is where that
   * trade happens. None of that is built. This command exists so the cast layer is testable before
   * it is, and it must NOT become the way a player gets a second rune.
   */
  rune: (arg?: string) => string
}
const NAMED_HOURS: Record<string, number> = { midnight: 0, dawn: 6.5, noon: 12, dusk: 18.75, night: 21 }
/** `~` / `~-5` → relative to `cur`; anything else parses as absolute. NaN propagates for the caller. */
const parseCoord = (tok: string, cur: number): number =>
  tok.startsWith('~') ? cur + (tok.length > 1 ? Number(tok.slice(1)) : 0) : Number(tok)
interface ConsoleCmd {
  name: string; usage: string; help: string; owner?: boolean
  run: (a: string[], c: ConsoleCtx) => string
  /** Tab-completion values for argument N (0-based), MC's suggestion strip. Filtered by prefix. */
  suggest?: (argIdx: number, c: ConsoleCtx) => string[]
}
const CONSOLE_CMDS: ConsoleCmd[] = [
  { name: 'help', usage: 'help', help: 'list commands', run: (_a, c) =>
      CONSOLE_CMDS.filter(k => !k.owner || c.isOwner).map(k => `/${k.usage} — ${k.help}`).join('\n') },
  { name: 'time', usage: 'time <0-24 | dawn|noon|dusk|night|midnight | free>', help: 'pin the clock (this tab only) or hand it back',
    run: (a) => {
      const w = (a[0] ?? '').toLowerCase()
      if (!w) return `it is ${getDisplayTime(dayProgress())}${isTimePinned() ? ' (pinned)' : ''}`
      if (w === 'free' || w === 'live') { setTimePin(null); return 'clock handed back to the world' }
      const h = w in NAMED_HOURS ? NAMED_HOURS[w] : Number(w)
      if (!Number.isFinite(h)) return `not an hour: ${w}`
      setTimePin(h)
      return `pinned at ${getDisplayTime(dayProgress())} — 'time free' to release`
    },
    suggest: () => [...Object.keys(NAMED_HOURS), 'free'] },
  // ★ OWNER-GATED because it is a balance dial, not a view. `time` is view-grade (it pins one tab's
  // clock and touches nothing shared); this changes how the game PLAYS, which is the line this
  // registry already draws between cheat-grade and view-grade verbs.
  { name: 'mine', usage: 'mine [rate]  (1 = normal, 2 = twice as slow)', help: 'dial how long blocks take to break', owner: true,
    run: (a) => {
      if (!a[0]) return `break rate ${getBreakRate()}x — 'mine 2' for twice as slow, 'mine 1' for normal`
      const r = Number(a[0])
      if (!Number.isFinite(r) || r <= 0) return `not a rate: ${a[0]}`
      setBreakRate(r)
      return `blocks now take ${getBreakRate()}x as long — session only, tell Jin the number to bake in`
    },
    suggest: () => ['1', '1.5', '2', '3'] },
  { name: 'radius', usage: 'radius [4-12]', help: 'view/load ring, in columns of 16',
    run: (a, c) => {
      if (!a[0]) return `radius is ${c.radius()} (${c.radius() * 16} blocks)`
      const r = Math.round(Number(a[0]))
      if (!Number.isFinite(r) || r < VIEW_RADIUS_MIN || r > VIEW_RADIUS_MAX) return `radius takes ${VIEW_RADIUS_MIN}..${VIEW_RADIUS_MAX}`
      c.setRadius(r)
      return `radius ${r} (${r * 16} blocks)`
    },
    suggest: () => ['4', '6', '8', '10', '12'] },
  // ★ /rune (2026-08-12, Alex: "I went to test but as a new player I have none").
  // Bare /rune is the keeper's own hand — what you hold, what it opens, what is bound. That half is
  // VIEW-GRADE and gates nothing: a player whose keys do nothing deserves to be told WHY, and until
  // the Passage exists the panel is the only other place that says it. Granting is cheat-grade and
  // checked inside `c.rune`, so the readout survives for everyone.
  { name: 'rune', usage: 'rune [id]  (bare: your hand · id: develop/drop it)', help: 'the runes you hold and the moves they open',
    run: (a, c) => c.rune(a[0]),
    suggest: (i, c) => i === 0 && c.isOwner ? RUNES.map(r => r.id).sort() : [] },
  { name: 'give', usage: 'give <item> [count]', help: 'conjure items into the bag', owner: true,
    run: (a, c) => a[0] ? c.give(a[0], Math.max(1, Math.round(Number(a[1]) || 1))) : 'give what?',
    suggest: (i) => i === 0 ? [...KNOWN_ITEMS].sort() : ['1', '4', '16', '64'] },
  { name: 'tp', usage: 'tp <x> <z>  (~ = here, ~-20 = 20 west)', help: 'teleport to ground level', owner: true,
    run: (a, c) => {
      if (!a[0] || !a[1]) return 'tp needs two coordinates'
      const p = c.pos()
      const x = parseCoord(a[0], p.x), z = parseCoord(a[1], p.z)
      if (!Number.isFinite(x) || !Number.isFinite(z)) return `not coordinates: ${a[0]} ${a[1]}`
      return c.tp(Math.floor(x), Math.floor(z))
    },
    suggest: () => ['~'] },
  // ★ /goto (2026-08-08, Alex: "I wasn't able to locate the springs.. its a big map lol").
  // Bare /goto is the compass: every ruled place with distance and bearing from where you stand.
  // That half is VIEW-GRADE (this file's own rule) and gates nothing — the zones are islands in a
  // lot of wild country, and a player who cannot find them has a worse problem than a player who
  // knows where they are. Only the TELEPORT is cheat-grade, checked inside so the compass survives.
  { name: 'goto', usage: 'goto [zone]', help: 'bare: bearings to every ruled place · named: teleport there',
    run: (a, c) => {
      const q = (a[0] ?? '').toLowerCase()
      const p = c.pos()
      if (!q) return ZONE_ANCHORS.map(z => `${z.id.padEnd(16)} ${bearing(z.x - p.x, z.z - p.z)}`).join('\n')
      const z = ZONE_ANCHORS.find(zn => zn.id === q) ?? ZONE_ANCHORS.find(zn => zn.id.startsWith(q))
      if (!z) return `no such place: ${q} — bare /goto lists them`
      if (!c.isOwner) return `${z.id}: ${bearing(z.x - p.x, z.z - p.z)} — teleport is keeper-of-the-realm only`
      return c.tp(z.x, z.z)
    },
    suggest: () => ZONE_ANCHORS.map(z => z.id) },
  // ★ /mist (2026-08-09) — the same lesson /goto was built for, one scale down. A patch is ~52
  // blocks across in a region 2000 across, and there are three of them: found by walking is found
  // by accident. The compass half is VIEW-GRADE for the same reason /goto's is (knowing a place
  // exists is not a cheat); only the teleport is gated.
  { name: 'mist', usage: 'mist [go]', help: 'bare: bearings to nearby mist patches · go: teleport to the nearest',
    run: (a, c) => {
      const p = c.pos()
      const found = mistPatchesNear(p.x, p.z, SEED, MIST_FIND_REACH)
        .sort((m, n) => Math.hypot(m.x - p.x, m.z - p.z) - Math.hypot(n.x - p.x, n.z - p.z))
      if (!found.length) return `no mist patch within ${MIST_FIND_REACH} blocks — they gather inside the ruled regions (/goto)`
      if ((a[0] ?? '').toLowerCase() === 'go') {
        if (!c.isOwner) return `nearest: ${bearing(found[0].x - p.x, found[0].z - p.z)} — teleport is keeper-of-the-realm only`
        return c.tp(found[0].x, found[0].z)
      }
      // ★ Names who answers and at what level, because a patch's strength is a property of its
      // region now and a band nobody can read is a band that reads as an ambush. Same view-grade
      // line the prompt draws in the world, at compass range: choosing which mist to walk to IS
      // the difficulty choice, so the compass has to carry the number.
      const ledger = c.mistLedger()
      const now = Date.now()
      return found.slice(0, 5).map(m => {
        const r = residentAt(m, zoneAt(m.x, m.z, SEED).zone?.id, ledger, now)
        const who = r
          ? `${r.name} lv ${r.level}${r.second ? ` + ${r.second.name} lv ${r.second.level}` : ''}`
          : quietMinutes(ledger, m, now) > 0 ? `quiet ${quietMinutes(ledger, m, now)}m` : 'no answer'
        return `mist patch      ${bearing(m.x - p.x, m.z - p.z)}      ${who}`
      }).join('\n')
    },
    suggest: () => ['go'] },
  // ★ /party (2026-08-09) — the mist spar refuses to start without spirits, by design and by canon
  // (Greg's seed sleeps a while yet), which means testing the spar on a fresh world is impossible
  // without first playing the 2D game to a party. That is a fine rule for a player and a wall for
  // whoever is dialling the feature. Bare `/party` is the roster; the rest is the workbench, and it
  // writes to the same save every surface shares, so it is keeper-of-the-realm only.
  { name: 'party', usage: 'party [lend [n] [level] | heal | clear]', help: 'bare: your spirits · lend/heal/clear: the spar workbench',
    run: (a, c) => {
      const verb = (a[0] ?? '').toLowerCase()
      if (!verb) return c.party.list()
      if (!c.isOwner) return 'the garden answers only its keeper — bare /party reads your roster'
      if (verb === 'heal') return c.party.heal()
      if (verb === 'clear') return c.party.clear()
      if (verb === 'lend') {
        const n = Math.min(4, Math.max(1, Math.round(Number(a[1]) || 4)))
        const lv = Math.min(50, Math.max(1, Math.round(Number(a[2]) || 10)))
        return c.party.lend(n, lv)
      }
      return `party takes lend, heal or clear — not ${verb}`
    },
    suggest: (i) => i === 0 ? ['lend', 'heal', 'clear'] : i === 1 ? ['1', '2', '3', '4'] : ['5', '10', '20', '30'] },
  { name: 'weather', usage: 'weather', help: 'someday', run: () =>
      'no weather in the Ather yet — the day it exists, its command lands here' },
]

/** How far /mist looks. Bounded because the scan validates every candidate cell it touches (a pad
 *  scan plus a dell ring each), and an unbounded compass would stall the console on a keystroke. */
const MIST_FIND_REACH = 1200

/** Prompt tint per element — brightened off ELEMENT_COLORS, which are body colours and read muddy
 *  as small text over gold fog. Same four elements, legible weight. */
const MIST_PROMPT: Record<'mana' | 'storm' | 'earth' | 'water', string> = {
  mana: '#d9b3e8', storm: '#9fb8f0', earth: '#e0c08a', water: '#8fd8d0',
}

/** Distance + 8-way compass toward (dx, dz). MC's convention: −Z is north, +X is east. */
function bearing(dx: number, dz: number): string {
  const d = Math.hypot(dx, dz)
  if (d < 60) return 'you are here'
  const dirs = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']
  const a = Math.atan2(dx, -dz)                       // 0 = north, clockwise
  const k = ((Math.round(a / (Math.PI / 4)) % 8) + 8) % 8
  return `${Math.round(d)} blocks ${dirs[k]}`
}
function runConsoleLine(line: string, ctx: ConsoleCtx): { text: string; err?: boolean } {
  const parts = line.trim().split(/\s+/)
  const name = (parts[0] ?? '').toLowerCase().replace(/^\//, '')
  if (!name) return { text: '' }
  const cmd = CONSOLE_CMDS.find(k => k.name === name)
  if (!cmd) return { text: `unknown command: ${name} — try /help`, err: true }
  if (cmd.owner && !ctx.isOwner) return { text: `/${name} is keeper-of-the-realm only`, err: true }
  return { text: cmd.run(parts.slice(1), ctx) }
}

/**
 * MC's suggestion strip, sized to ours: given the draft line, what completions apply to the token
 * under the cursor (always the LAST token — no mid-line cursor support, deliberately), and how to
 * apply one. Command names complete after `/`; arguments complete from the command's `suggest`.
 */
function suggestionsFor(line: string, ctx: ConsoleCtx): { options: string[]; apply: (opt: string) => string } {
  const none = { options: [], apply: () => line }
  if (!line.startsWith('/')) return none
  const body = line.slice(1)
  const toks = body.split(/\s+/)
  const completingNew = /\s$/.test(body) || body === ''
  const partial = completingNew ? '' : toks[toks.length - 1]
  const tokIdx = completingNew ? toks.filter(Boolean).length : toks.length - 1
  const stem = completingNew ? body : body.slice(0, body.length - partial.length)
  const build = (opt: string) => `/${stem}${opt} `
  if (tokIdx === 0) {
    const names = CONSOLE_CMDS.filter(k => !k.owner || ctx.isOwner).map(k => k.name)
    return { options: names.filter(n => n.startsWith(partial.toLowerCase())), apply: build }
  }
  const cmd = CONSOLE_CMDS.find(k => k.name === toks[0].toLowerCase())
  if (!cmd?.suggest || (cmd.owner && !ctx.isOwner)) return none
  const opts = cmd.suggest(tokIdx - 1, ctx).filter(o => o.startsWith(partial))
  return { options: opts.slice(0, 8), apply: build }
}
/** Item ids the console may conjure — everything a block drops or a recipe produces. */
const KNOWN_ITEMS: ReadonlySet<string> = new Set([
  ...BLOCKS.flatMap(b => b.drops.map(d => d.itemId)),
  ...RECIPE_OUTPUTS,
])

/**
 * One window of the frame meter. `worst` is the point of it: an average hides exactly the hitch a
 * player feels, and the remesh queue draining as you walk into new ground is a hitch, not a rate.
 */
export interface PerfSample {
  fps: number
  /** Mean frame time, ms. THE number to compare across an A/B — ms subtracts, fps does not. */
  ms: number
  /** Longest single frame in the window, ms. */
  worst: number
}

export default function VoxelWorld() {
  const [stats, setStats] = useState('generating…')
  /**
   * ── ★ THE FRAME METER (2026-08-13 night) ──────────────────────────────────────────────────────
   * Its own state, not a slice of the `stats` string, because the two answer to different clocks:
   * `stats` is rebuilt every 10th frame and can be clobbered, while this has to keep a steady
   * cadence to be readable while the number it reports is moving. Null until the first window
   * closes, so the meter never shows a fabricated 0.
   */
  const [perf, setPerf] = useState<PerfSample | null>(null)
  /**
   * ── ★ THE SAY CHANNEL — what the WORLD tells the PLAYER (2026-08-12) ────────────────────────
   * `stats` is the plumbing readout and the frame loop OVERWRITES IT EVERY 10 FRAMES with the
   * biome/column/geo line. Everything player-facing was being written to it too — a cast refusal,
   * "the seed is in the soil", "a young Wisp chose you!", "bag full" — so each one lived ~150ms in
   * 11px grey debug text and read as nothing happening at all.
   *
   * That is what made a fresh keeper's cast keys look BROKEN rather than empty: `cast-dispatch`
   * refuses honestly ("No tactical bound — your book has none for your runes") and the host threw
   * the sentence away before it could be read. The pure layer was right and the host lost it.
   *
   * So: two channels. `stats` stays plumbing and may be clobbered at will; `say` is addressed to
   * the player and holds until it expires. A message nobody can read is the same as no message.
   */
  const [toast, setToast] = useState<{ text: string; at: number } | null>(null)
  /** Bumped when the rune inventory changes, so the world re-resolves the loadout without a reload.
   *  A counter rather than the inventory itself: the world reads storage, this only says "again". */
  const [runeTick, setRuneTick] = useState(0)
  const say = useCallback((text: string) => setToast({ text, at: Date.now() }), [])
  useEffect(() => {
    if (!toast) return
    const t = setTimeout(() => setToast(c => (c && c.at === toast.at ? null : c)), 4200)
    return () => clearTimeout(t)
  }, [toast])
  const [pos, setPos] = useState('')
  // ── ★ THE MAP (2026-08-13) ────────────────────────────────────────────────────────────────────
  // The keeper's live spot, kept as a ref rather than state: the frame loop writes it 60×/sec and a
  // setState there would re-render the whole HUD on every frame.
  const mapPos = useRef<{ x: number; z: number } | null>(null)
  /** Canvas rotation for the map marker — `screenHeading`, not a world yaw. See map-heading.ts. */
  const mapHeading = useRef(0)
  const [showMap, setShowMap] = useState(false)
  /**
   * What the keeper has walked. See `discovery.ts` for why unwalked ground is CLOUD and not a grey
   * overlay — in the Ather it is the literal substance of the place.
   *
   * ★ SAMPLED ON ITS OWN 250ms CLOCK, NOT IN THE FRAME LOOP. A fog cell is 16 blocks across and a
   * walker crosses one every couple of seconds, so 60Hz would ask the same question hundreds of
   * times per answer. `see()` returns 0 when nothing opened, so the common tick costs one distance
   * check and nothing else — and the SAVE is debounced off ground opening rather than off the
   * clock, so a keeper standing still never writes.
   */
  const seenRef = useRef<Seen | null>(null)
  const [seenTick, setSeenTick] = useState(0)
  const seenDirty = useRef(false)
  useEffect(() => {
    seenRef.current = loadSeen('voxel', MAP_W * CELL, MAP_H * CELL)
    setSeenTick(n => n + 1)
    let saveT = 0
    const id = setInterval(() => {
      const p = mapPos.current, seen = seenRef.current
      if (!p || !seen) return
      const { lx, lz } = toLocal(p.x, p.z)
      if (see(seen, lx, lz) > 0) { seenDirty.current = true; setSeenTick(n => n + 1) }
      if (seenDirty.current && ++saveT >= 8) { saveT = 0; seenDirty.current = false; saveSeen('voxel', seen) }
    }, 250)
    return () => {
      clearInterval(id)
      if (seenDirty.current && seenRef.current) saveSeen('voxel', seenRef.current)
    }
  }, [])
  const [hotbar, setHotbar] = useState<(HotbarEntry | null)[]>([])
  // Stowed vs drawn. F toggles. See the DRAW LOCK note on the keydown handler.
  const [drawn, setDrawn] = useState(false)
  const [weaponIdx, setWeaponIdx] = useState(0)
  const [ammoUi, setAmmoUi] = useState(WEAPONS[0].clip)
  const [sel, setSel] = useState(0)
  /**
   * ── ★ SAY WHAT YOU ARE HOLDING (2026-08-11, Alex) ──────────────────────────────────────────
   * The hotbar showed a colour swatch and a count and never once named the thing. `out` drives a
   * fade rather than an unmount so the label does not pop out of existence mid-transition.
   *
   * ⚠ KEYED ON THE ITEM, NOT THE HOTBAR ARRAY. `refreshHotbar` rebuilds that array on every
   * inventory change, so depending on it would re-announce the held item on every single block
   * mined — a nameplate that flashes constantly while you work reads as a bug, not a help.
   */
  const [held, setHeld] = useState<{ text: string; out: boolean } | null>(null)
  const heldItem = hotbar[sel]?.itemId
  useEffect(() => {
    if (!heldItem) { setHeld(null); return }
    setHeld({ text: itemLabel(heldItem), out: false })
    const fade = setTimeout(() => setHeld(h => (h ? { ...h, out: true } : h)), 1100)
    const gone = setTimeout(() => setHeld(null), 1700)
    return () => { clearTimeout(fade); clearTimeout(gone) }
  }, [sel, heldItem])
  const [tier, setTier] = useState(1)
  // ★ BUILD MODE. Blocks build the shell (mine/place, already there); pieces dress it. Tab switches
  // which verb the mouse means, so the two halves never fight over a click.
  const [build, setBuild] = useState(false)
  const [pieceIdx, setPieceIdx] = useState(0)
  const [rot, setRot] = useState<Rotation>(0)
  const [look, setLook] = useState<{ name: string; progress: number; refused: boolean } | null>(null)
  const [settings, setSettings] = useState<VoxelSettings>(() => loadSettings())
  const [showSettings, setShowSettings] = useState(false)
  const update = useCallback((patch: Partial<VoxelSettings>) => {
    setSettings(prev => { const next = { ...prev, ...patch }; saveSettings(next); return next })
  }, [])
  const worker = useRef<Worker | null>(null)
  const incoming = useRef<{ cx: number; cz: number; voxels: Uint16Array; oIdx?: Uint32Array; oMat?: Uint16Array }[]>([])
  const inflight = useRef(0)

  useEffect(() => {
    let w: Worker
    try { w = new Worker(VOXEL_WORKER_URL) }
    catch (e) { setStats(`worker failed to start: ${String(e)} — main thread`); return }
    // Handler BEFORE post: assigning onmessage after postMessage races the first reply, and reads
    // as "the worker never answered".
    w.onmessage = (e) => {
      const m = e.data
      if (m.type === 'column') incoming.current.push({ cx: m.cx, cz: m.cz, voxels: m.voxels, oIdx: m.oIdx, oMat: m.oMat })
      else if (m.type === 'done') inflight.current = Math.max(0, inflight.current - 1)
    }
    w.onerror = (ev) => { setStats(`worker error: ${ev.message} — falling back to main thread`); worker.current = null }
    w.postMessage({ type: 'init', seed: SEED })
    worker.current = w
    return () => { w.terminate(); worker.current = null }
  }, [])

  // ★ THE SPIKE IS CANON, NOT INVENTED. `engine/tools.ts` rules blades→forestry,
  // spikes→prospecting, rinsticks→rinning, with a basic Greg-given tool that never breaks. So
  // "what do I mine rock with" already had an answer and nothing here needed naming.
  // Kept as refs so `World` reads them per-frame without re-rendering, but they are now DERIVED
  // from the equipped tool rather than set by a debug key.
  const toolTier = useRef(1)
  const toolSkill = useRef<BlockSkill>('prospecting')
  const inv = useRef<Inventory>(createInventory())
  // ★ Greg's basic tools, exactly as the tile game hands them out — `ensureBasicTools` fills any
  // missing skill with its never-breaking starter (worn_spike, worn_blade, worn_rinstick). The
  // debug tier lever is gone: tier now comes from what you are actually holding.
  const tools = useRef<EquippedTools>(ensureBasicTools({}))
  const skills = useRef<SkillSet>(createSkillSet())
  const [skillHud, setSkillHud] = useState<{ id: string; level: number; xp: number; next: number } | null>(null)
  // ★ THE TUTORIAL. `tutorial` is a ref (mutated in place, like `inv`/`tools`) so World can read the
  // current stage every frame with no re-render; `tutorialTick` is the counter that forces a HUD
  // re-render on the rare frames the stage actually changes — same split `craftTick` uses one level
  // up for the inventory ref.
  const tutorial = useRef<TutorialState>(loadTutorial(SEED))
  const [, setTutorialTick] = useState(0)
  const [dialogueOpen, setDialogueOpen] = useState(false)
  const [nearGreg, setNearGreg] = useState(false)
  // ── The mist spar (2026-08-09) ──────────────────────────────────────────────────────────────
  // The presence you are standing in front of, the withdrawal ledger, and the fight in progress.
  const [nearMist, setNearMist] = useState<Resident | null>(null)
  const mistLedger = useRef<MistLedger>({})
  const [spar, setSpar] = useState<{ allies: Spirit[]; enemies: Spirit[]; patch: MistPatch; name: string } | null>(null)
  /**
   * ★ THE PARTY IS NOT WORLD-LOCAL, and that is canon rather than convenience. `game/shimmer-
   * geography.md` › *Where a keeper's spirits live* rules that a keeper's spirits live in their
   * garden and go on living there whether or not you are standing next to them — three rings, none
   * of them storage. So the voxel world reads the SAME party the 2D game and play3d share
   * (`ather:save:shimmer`) rather than minting a second roster: a keeper has one set of spirits,
   * and which surface they are looking at the garden through does not change who is theirs.
   */
  const party = useRef<Spirit[]>([])
  /**
   * ── ★ THE KEEPER'S VITALS (2026-08-12, Alex ruled them into this world) ──────────────────────
   * "100hp and another 100 barrier shields (the barrier birth rune affords an extra 25 to their
   * base)." Health and shields each count 100 — 200 effective, Apex-style.
   *
   * The rules live in `engine/vitals.ts` and are SHARED with play3d rather than written twice, for
   * the reason every extraction on this seam exists: two worlds disagreeing about what a hit does
   * is a bug nobody can trace, because both look right in isolation.
   *
   * ⚠ CAPS COME FROM THE BIRTH AFFINITY, NEVER FROM A RUNE ID. Alex stated the +25 for Barrier, but
   * `birth-affinity.ts` already applies it to a FAMILY off the canon essence table — `defense`
   * (+25 shield) covers Barrier AND Stone, `vitality` (+25 HP) covers Life. Reading the rune id here
   * would silently drop the other two the day anyone looked.
   */
  const vitals = useRef<Vitals>(freshVitals(birthAffinity(loadRuneInventory().birth)))
  /**
   * ── ★ MANA — the cost side of casting, and it needed no new design ──────────────────────────
   * `engine/mana.ts` already derives pool and regen from `skills.mana.level`, which this world
   * ALREADY levels, and canon already says what mana is for (`shimmer-skilling.md`: all gathering
   * is mana-powered). So turning casting on costs one ref and a regen tick, not an economy.
   *
   * ⚠ GATHERING STAYS FREE THIS PASS. `engine/crafting.ts` was deliberately refused by this world
   * because it charges mana on everything (see the PORT STEP 2 note at the top of this file), and
   * making the cozy loop cost mana in the same commit that makes casting cost mana would blur which
   * change did what. Casting spends; harvesting does not, yet.
   */
  const mana = useRef({ cur: 0, max: 0, regen: 1 })
  useEffect(() => {
    const aff = birthAffinity(loadRuneInventory().birth)
    const lvl = skills.current.mana.level
    mana.current.max = getMaxPool(lvl) + aff.manaBonus
    mana.current.regen = getRegenRate(lvl)
    mana.current.cur = mana.current.max
  }, [])
  /** Planting times by world position. The ONE thing the pot's material cannot hold (see pot.ts). */
  const potClock = useRef<PotClock>({})
  const [hasParty, setHasParty] = useState(false)
  /** The practice ledger from the spar you just walked out of — one line per spirit, then it goes. */
  const [sparLedger, setSparLedger] = useState<string[] | null>(null)

  /**
   * Persist the party back to the SHARED save. Merge-write, always: this world knows nothing about
   * the fields the 2D game and play3d keep in that slot (flags, wallet, index, plot) and must never
   * drop them by writing a whole object. One helper because there are now two writers — the spar's
   * wounds and the console's workbench — and a second hand-rolled merge is how one of them
   * eventually forgets the spread.
   */
  const writeParty = useCallback(() => {
    setHasParty(party.current.length > 0)
    try {
      const raw = localStorage.getItem('ather:save:shimmer')
      const prev = raw ? JSON.parse(raw) as Record<string, unknown> : {}
      localStorage.setItem('ather:save:shimmer', JSON.stringify({ ...prev, spirits: spiritsToSave(party.current) }))
    } catch { /* private mode: the change still holds for this session, it just does not persist */ }
  }, [])

  /**
   * The console's view of the garden. `lend` draws EVENLY SPACED species out of the launched list
   * rather than the first N: the four it hands you then cover all four elements, which is the whole
   * point of a test party — a roster of one element cannot surface an elemental-matchup bug.
   * Lent spirits are `base` element and unbonded, i.e. exactly what a fresh keeper would hold, so
   * what you feel while dialling the spar is what a new player will feel.
   */
  const POT_KEY = `voxel3d:pots:${SEED}`
  const savePotClock = useCallback(() => {
    try { localStorage.setItem(POT_KEY, JSON.stringify(potClock.current)) } catch { /* full disk */ }
  }, [POT_KEY])
  useEffect(() => {
    try { potClock.current = JSON.parse(localStorage.getItem(POT_KEY) ?? '{}') } catch { potClock.current = {} }
  }, [POT_KEY])

  /** What the world needs of the pot: the clock, a way to persist it, and where a spirit goes. */
  const potOps = useMemo(() => ({
    clock: () => potClock.current,
    save: savePotClock,
    gain: (s: Spirit) => { party.current = [...party.current, s]; writeParty() },
  }), [savePotClock, writeParty])

  const partyOps = useMemo(() => ({
    list: () => {
      if (!party.current.length) return 'no spirits in your garden — /party lend to borrow a few'
      return party.current.map(s => {
        const hp = Math.round((s.hpFrac ?? 1) * 100)
        return `${speciesDisplayName(s.species).padEnd(12)} lv ${String(s.level).padStart(2)}  ${hp}% hp${hp === 0 ? '  (down)' : ''}`
      }).join('\n')
    },
    lend: (count: number, level: number) => {
      const step = LAUNCHED_SPECIES.length / count
      party.current = Array.from({ length: count }, (_, i) => {
        const sp = LAUNCHED_SPECIES[Math.min(LAUNCHED_SPECIES.length - 1, Math.floor(i * step))]
        const s = createSpirit(sp, speciesDisplayName(sp), 0, 0)
        s.level = level
        return s
      })
      writeParty()
      return `lent ${count} spirits at level ${level} — ${party.current.map(s => s.name).join(', ')}`
    },
    heal: () => {
      if (!party.current.length) return 'nothing to mend'
      for (const s of party.current) s.hpFrac = 1
      writeParty()
      return `mended ${party.current.length} spirits`
    },
    clear: () => {
      const n = party.current.length
      party.current = []
      writeParty()
      return n ? `sent ${n} spirits home — the mist will say you have none` : 'the garden was already empty'
    },
  }), [writeParty])

  // ★ THE GAUGE SIGNAL. Which family is mining RIGHT NOW, for the tool gauges to light up — set
  // from inside the mining block only on change (see the ref there), never per-frame.
  const [activeTool, setActiveTool] = useState<string | null>(null)
  const [levelUp, setLevelUp] = useState<string | null>(null)
  const [crafted, setCrafted] = useState<string | null>(null)
  // Owner status, for the legacy play3d door in the HUD only. ather.games has no cloud auth — it
  // comes from the httpOnly `ather_owner` cookie via /api/owner (set at /owner?key=OWNER_KEY).
  // Same pattern as Shimmer3D. It gates a LINK, not the route: /shimmer/play3d enforces its own
  // gate in proxy.ts, because a hidden link is not a permission.
  const [isOwner, setIsOwner] = useState(false)
  useEffect(() => {
    let alive = true
    fetch('/api/owner', { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : { owner: false }))
      .then((d) => { if (alive && d.owner) setIsOwner(true) })
      .catch(() => {})
    return () => { alive = false }
  }, [])
  // Toasts clear themselves. A level-up banner that never leaves stops being a level-up banner.
  useEffect(() => { if (!levelUp) return; const t = setTimeout(() => setLevelUp(null), 2600); return () => clearTimeout(t) }, [levelUp])
  useEffect(() => { if (!crafted) return; const t = setTimeout(() => setCrafted(null), 2600); return () => clearTimeout(t) }, [crafted])
  // Longer than the other toasts: this one is a list of names and numbers, not a word.
  useEffect(() => { if (!sparLedger) return; const t = setTimeout(() => setSparLedger(null), 6000); return () => clearTimeout(t) }, [sparLedger])

  /**
   * ── ★ THE BAR IS THE FIRST 8 SLOTS, NOT A SUMMARY OF THE BAG (2026-08-11, Alex) ──────────────
   * It used to sum every slot into a per-item total and slice the top 8, which meant SLOT 3 WAS
   * NOT A PLACE — the bar re-sorted itself as you picked things up, so what sat under your finger
   * changed while you worked and nothing could be arranged. Reading real slot positions is what
   * makes a hotbar a hotbar; it is also the prerequisite for the satchel, since both are then
   * windows onto one grid rather than two ideas about what you are carrying.
   *
   * ⚠ Positional, so empties are NULL and stay null — a gap in the bar is a gap on purpose.
   * `give`/`addToGrid` fills the lowest free slot first, so picked-up items land in the bar before
   * the satchel, which is the behaviour a player expects without being told.
   */
  /**
   * Move or merge one slot onto another, in the bag or across into an open chest.
   *
   * ★ MERGE BEFORE SWAP, and respect the item's own stack ceiling — dropping 60 stone onto 60 more
   * must leave 99 and 21, not silently destroy 21 or build a stack no other code path could have
   * made. `maxStackOf` is the same ladder `give` uses, so a stack assembled by hand can never
   * exceed one assembled by walking over drops.
   *
   * ★ ONE function for both grids: a bag→chest move and a bag→bag move differ in nothing, and
   * written twice they drift the first time one is fixed. `moveBetween` is the only implementation
   * (chest.ts); `moveStack` is that same call with one array passed twice.
   */
  const moveRef = useCallback((from: SlotRef, to: SlotRef) => {
    const chest = openChestRef.current
    if ((from.g === 'chest' || to.g === 'chest') && !chest) return
    const grid = (r: SlotRef) => (r.g === 'bag' ? inv.current.slots : chest!.slots)
    moveBetween(grid(from), from.i, grid(to), to.i, maxStackOf)
    if (from.g === 'chest' || to.g === 'chest') chest!.touch()
    refreshHotbarRef.current?.()
  }, [])

  /**
   * Shift-click: send a whole stack to the other container.
   *
   * ★ THIS IS WHAT MAKES A CHEST WORTH HAVING. Emptying a bag one lift-and-place at a time is
   * twenty-four pairs of clicks, and a container that costs that much to fill is one nobody fills.
   * Merges into existing stacks before taking an empty slot, exactly like a pickup does — so
   * putting things away by hand and having them land there by walking behave the same.
   */
  /**
   * The split: move HALF the lifted stack (left-click after a right-click lift) or ONE of it (a
   * right-click while anything is lifted). Both are `moveCount`; only the amount differs.
   *
   * ★ THE AMOUNT IS READ AT PLACE TIME, NOT FROZEN AT LIFT. The grid is a live array — a drop walked
   * over while the panel is open grows the stack under the lift — and a number frozen a click ago
   * would take "half of what it used to be", which is a quiet theft nobody would ever trace. Half of
   * what the panel is currently SHOWING is the only amount a player can check.
   *
   * ★ THE LIFT CLEARS ONLY WHEN THE SOURCE RUNS DRY. Placing ones is meant to be repeated, so the
   * lift survives the click; a refusal (0 moved, e.g. onto a different item) also survives it, which
   * is what makes the refusal visible — the slot stays lit instead of the click evaporating. This
   * component owns `dragFrom`, so the lifecycle lives here rather than being inferred by the panel.
   */
  const splitRef = useCallback((from: SlotRef, to: SlotRef, mode: 'half' | 'one') => {
    const chest = openChestRef.current
    if ((from.g === 'chest' || to.g === 'chest') && !chest) return
    const grid = (r: SlotRef) => (r.g === 'bag' ? inv.current.slots : chest!.slots)
    const src = grid(from)
    const stack = src[from.i]
    if (!stack) { setDragFrom(null); return }
    const want = mode === 'one' ? 1 : halfOf(stack.count)
    const moved = moveCount(src, from.i, grid(to), to.i, want, maxStackOf)
    if (moved > 0) {
      if (from.g === 'chest' || to.g === 'chest') chest!.touch()
      refreshHotbarRef.current?.()
    }
    // A half-place is one whole action and ends the lift; placing ones is meant to repeat, so it
    // ends only when there is nothing left under it.
    if (mode === 'half' || !src[from.i]) setDragFrom(null)
  }, [])

  const quickRef = useCallback((r: SlotRef) => {
    const chest = openChestRef.current
    if (!chest) return
    const from = r.g === 'bag' ? inv.current.slots : chest.slots
    const to = r.g === 'bag' ? chest.slots : inv.current.slots
    if (!quickMove(from, r.i, to, maxStackOf)) return
    chest.touch()
    refreshHotbarRef.current?.()
  }, [])
  const refreshHotbarRef = useRef<(() => void) | null>(null)

  const refreshHotbar = useCallback(() => {
    setHotbar(Array.from({ length: 8 }, (_, i) => {
      const s = inv.current.slots[i]
      return s ? { itemId: s.itemId, count: s.count } : null
    }))
  }, [])
  refreshHotbarRef.current = refreshHotbar

  // ── The crafting surface ────────────────────────────────────────────────────────────────────
  // `craftTick` exists because the inventory is a REF, not state — crafting mutates it in place and
  // React has no way to know. Bumping a counter is what re-renders the panel with new counts. The
  // alternative (inventory in state) would re-render the whole world on every mined block.
  /**
   * ── ★ THE SATCHEL (2026-08-11) ────────────────────────────────────────────────────────────────
   * One window onto the SAME 24-slot grid the hotbar reads: slots 0-7 are the bar, 8-23 the
   * satchel. Not a second container — that is the whole reason the hotbar had to become positional
   * first, and it is why dragging between the two halves is just a slot swap rather than a
   * transfer with rules of its own.
   */
  const [bagOpen, setBagOpen] = useState(false)
  /** The slot being dragged, or null. Names its GRID as well as its index — see `SlotRef`/`Lift`. */
  const [dragFrom, setDragFrom] = useState<Lift | null>(null)
  /**
   * ── ★ THE CHEST IS THE SAME PANEL WITH A SECOND GRID ON TOP (2026-08-11) ─────────────────────
   * Not its own screen: the bag half of a chest screen and the satchel ARE the same 24 slots, and
   * two components drawing them is two places for a stack to look like two different things — the
   * shape the hotbar/satchel swatches already had once. `openChest.slots` is the world's own live
   * array, so what the panel shows and what the column saves cannot come apart.
   *
   * Mirrored into a ref because `moveRef`/`quickRef` are stable callbacks the panel calls on every
   * click; reading state through the closure would need them rebuilt on every open.
   */
  const [openChest, setOpenChest] = useState<OpenChest | null>(null)
  /** The bench whose job panel is up, or null. Position + a bound writer; see `OpenStation`. */
  const [openStation, setOpenStation] = useState<OpenStation | null>(null)
  const openChestRef = useRef<OpenChest | null>(null)
  openChestRef.current = openChest
  const [craftOpen, setCraftOpen] = useState(false)
  const [craftTick, setCraftTick] = useState(0)
  // Near a PLACED crafting table (World scans and reports, same shape as nearGreg). This is the
  // value that turns recipes.ts's `Station` field from documentation into a gate.
  const [nearTable, setNearTable] = useState(false)
  const station: Station = nearTable ? 'crafting_table' : 'hand'

  // ── the chat console (T / Enter / '/') — MC's chat-is-the-surface model ──────────────────────
  // Chat messages and command output land in ONE log: recent lines float on the HUD and fade
  // (MC shows ~3s; ours linger a touch longer), the full scrollback lives behind T. A line
  // starting with '/' is a command; anything else is chat — single-player today, but the shape
  // is multiplayer's, so the party build inherits a working chat for free.
  const [consoleOpen, setConsoleOpen] = useState(false)
  const [consoleSeed, setConsoleSeed] = useState('')   // "/" when opened via the slash key
  const [chatLog, setChatLog] = useState<{ id: number; text: string; kind: 'you' | 'out' | 'err'; at: number }[]>([])
  const chatId = useRef(0)
  const pushChat = useCallback((text: string, kind: 'you' | 'out' | 'err') => {
    const id = ++chatId.current
    setChatLog(l => [...l.slice(-99), { id, text, kind, at: Date.now() }])
  }, [])
  /** World fills this with the verbs only it can perform (teleport needs the walker + the clock
   *  of loaded columns). Null until the world mounts; commands degrade to a message, never throw. */
  const worldCmd = useRef<{ tp: (x: number, z: number) => string; pos: () => { x: number; z: number } } | null>(null)
  const consoleCtx = useMemo<ConsoleCtx>(() => ({
    isOwner,
    radius: () => settings.viewRadius,
    setRadius: (r) => update({ viewRadius: r }),
    give: (id, count) => {
      if (!KNOWN_ITEMS.has(id)) return `no such item: ${id}`
      give(inv.current!, id, count)
      refreshHotbar(); setCraftTick(t => t + 1)
      return `gave ${count}× ${id.replace(/_/g, ' ')}`
    },
    tp: (x, z) => worldCmd.current ? worldCmd.current.tp(x, z) : 'the world is still waking',
    pos: () => worldCmd.current ? worldCmd.current.pos() : { x: 0, z: 0 },
    party: partyOps,
    mistLedger: () => mistLedger.current,
    rune: (arg) => {
      const inv = loadRuneInventory()
      // The readout, and the reason the bare form is view-grade: it names the gap instead of
      // leaving four dead keys. `bound` counts SLOTS FILLED, not moves owned — a keeper can know a
      // move the loadout cannot seat (wrong slot kind), and that difference is the whole confusion.
      const report = (held: string[], lead: string) => {
        const names = held.map(id => RUNES.find(r => r.id === id)?.name ?? id)
        const moves = knownMoves(held)
        const bound = loadLoadout(held, keeperBook(held)).filter(Boolean).length
        const tail = moves.length === 0
          ? 'no move answers to it yet — the Schools have not written one'
          : `${moves.length} move${moves.length === 1 ? '' : 's'} known · ${bound}/4 cast slot${bound === 1 ? '' : 's'} bound`
        return `${lead}${names.join(', ') || 'nothing'} — ${tail}`
      }
      if (!arg) return report(inv.owned, inv.owned.length === 1 ? 'born of ' : 'you hold ')
      if (!isOwner) return 'a rune is trained, not typed — bare /rune reads your hand'
      const id = arg.toLowerCase()
      if (!RUNES.some(r => r.id === id)) return `no such rune: ${arg}`
      const held = inv.owned.includes(id)
      const next = held ? revokeRune(inv, id) : grantRune(inv, id)
      if (next === inv) return 'the birth rune cannot be dropped — you cannot un-be born'
      saveRuneInventory(next)
      setRuneTick(t => t + 1)
      return report(next.owned, `⟳ dev · ${held ? 'dropped' : 'developed'} ${RUNES.find(r => r.id === id)!.name} · `)
    },
  }), [isOwner, settings.viewRadius, update, refreshHotbar, partyOps])
  const submitLine = useCallback((raw: string) => {
    const line = raw.trim()
    if (!line) return
    if (line.startsWith('/')) {
      pushChat(`› ${line}`, 'you')
      const r = runConsoleLine(line, consoleCtx)
      if (r.text) pushChat(r.text, r.err ? 'err' : 'out')
    } else {
      // Plain chat. `keeper` until identity exists — the multiplayer build swaps the name in.
      pushChat(`<keeper> ${line}`, 'you')
    }
  }, [consoleCtx, pushChat])
  const have = useCallback((itemId: string) => countItem(inv.current!, itemId), [])

  // ── THE MOUSE HANDOFF (play3d's contract, ported verbatim) ──────────────────────────────────
  // Overlays own the cursor; play owns the look. Every cursor surface (craft, settings, Greg's
  // dialogue) releases the pointer on open and hands it BACK on close — the player never has to
  // Esc + re-click at a seam. Whether to re-lock is remembered from OPEN time rather than assumed:
  // a player who was already cursor-free must not have their mouse seized just because they closed
  // a menu. The handoff gives back exactly what it borrowed.
  const canvasElRef = useRef<HTMLCanvasElement | null>(null)
  const lockOnCloseRef = useRef(false)
  // Ref mirror of "any cursor surface is up" for the canvas click handler, which is attached once
  // in onCreated (the canvas does not exist at first-commit effect time) and so cannot close over
  // fresh state.
  const cursorUIOpenRef = useRef(false)
  const openCursorUI = useCallback(() => {
    lockOnCloseRef.current = !!document.pointerLockElement
    document.exitPointerLock?.()
  }, [])
  const closeCursorUI = useCallback(() => {
    const relock = lockOnCloseRef.current
    lockOnCloseRef.current = false
    if (!relock) return
    // The close is itself a user gesture (keypress or button click), which is what the browser
    // requires to grant pointer lock. The rare cooldown rejection (closing within ~1.25s of an
    // Esc-forced unlock) is swallowed — a canvas click is always the fallback.
    const c = canvasElRef.current
    if (c) { try { const r = c.requestPointerLock?.() as unknown as Promise<void> | undefined; r?.catch?.(() => {}) } catch { /* re-lock cooldown */ } }
  }, [])
  /**
   * One way out of the inventory surface, whichever way you came in.
   *
   * ⚠ The chest MUST be cleared here. It holds a live reference into the world's chest record; a
   * panel left mounted against a chest the player has walked away from (or broken) would keep
   * writing into an array nothing loads any more, and the items would be gone with no error.
   */
  const closeBag = useCallback(() => {
    setBagOpen(false); setOpenChest(null); setDragFrom(null); closeCursorUI()
  }, [closeCursorUI])
  /**
   * ── ★ ONE ANSWER TO "IS A MENU UP?" (2026-08-11, Alex: "the controls are still having the player
   * crouch and stuff") ──────────────────────────────────────────────────────────────────────────
   * Three separate places needed this and each carried its own idea of it: the canvas re-lock gate
   * had a list here, the verb handler inferred it from whichever flags its own `if` happened to
   * name, and the world's raw key/mouse listeners did not know menus existed AT ALL. So with the bag
   * open, Shift still crouched the player and — worse, because it leaves damage — a mousedown on a
   * slot set `mouse.left` and the frame loop mined the block behind the panel.
   *
   * ★ A list like this drifts the moment a surface is added, and it drifts SILENTLY: the new panel
   * simply does not suppress the world, which looks like a physics bug and not a missing entry. One
   * const, read by all three, so a forgotten surface is one mistake instead of three.
   *
   * ⚠ `openChest` belongs in here, or right-clicking a chest captures the cursor while the canvas
   * still thinks it owns the click — the pointer re-locks on the first slot you press. `consoleOpen`
   * belongs too and was missing: clicking the canvas while typing a command seized the mouse back
   * mid-sentence.
   */
  const cursorUIOpen = craftOpen || bagOpen || !!openChest || dialogueOpen || showSettings || !!spar || consoleOpen
  useEffect(() => { cursorUIOpenRef.current = cursorUIOpen }, [cursorUIOpen])

  // ── the shared party + the withdrawal ledger, read once at mount ────────────────────────────
  // Both are localStorage and therefore synchronous; done in an effect anyway so SSR never touches
  // them. A missing save is not an error — it is a keeper who has not been given a spirit yet, and
  // the mist prompt says exactly that rather than failing.
  useEffect(() => {
    mistLedger.current = loadMistLedger(SEED)
    try {
      const raw = localStorage.getItem('ather:save:shimmer')
      const data = raw ? JSON.parse(raw) as { spirits?: unknown[] } : null
      if (data?.spirits?.length) {
        party.current = spiritsFromSave(data.spirits as never)
        setHasParty(party.current.length > 0)
      }
    } catch { /* unreadable save = no party; the prompt handles it */ }
  }, [])

  /**
   * Begin a spar with the presence in front of you.
   *
   * ★ THE ENEMY'S LEVEL COMES FROM THE GROUND, NOT FROM YOU. This used to build the resident at the
   * party's own average, which is the player-relative model `engine/encounters.ts` deleted on
   * 2026-07-23 — see mist-difficulty.ts for the full argument. Every number below is already
   * decided by `residentAt`, so the fight that mounts is the exact fight the prompt described.
   */
  const startSpar = useCallback((r: Resident) => {
    const roster = party.current.filter(s => (s.hpFrac ?? 1) > 0).slice(0, 4)
    if (!roster.length) return
    const manifest = (f: ResidentForm) => {
      const wild = createSpirit(f.species, f.name, 0, 0)
      wild.level = f.level
      wild.element = f.element
      wild.seeds = Array.from({ length: 6 }, () => Math.floor(Math.random() * 32))
      return wild
    }
    const enemies = [manifest(r), ...(r.second ? [manifest(r.second)] : [])]
    openCursorUI()
    setSpar({ allies: roster, enemies, patch: r.patch, name: r.name })
  }, [openCursorUI])

  /**
   * ★ THE SPAR TAKES NOTHING — canon, and the reason there is no capture branch here to find.
   * Spirits manifest via Mana Seeds and are never caught; they retreat, they do not faint. So every
   * outcome does the same two things: persist what the fight cost the party, and record that the
   * other spirit withdrew into the mist. Win, loss and flight alike — the spirit left in all three
   * cases and only the reason differs, and recording only on a win would leave a beaten keeper
   * able to re-challenge instantly.
   */
  const endSpar = useCallback((outcome: 'win' | 'lose' | 'fled', result: BattleResult) => {
    const s = spar
    setSpar(null)
    closeCursorUI()
    if (!s) return
    for (const r of result.allies) {
      const spirit = s.allies[r.index]
      if (spirit) applyFightResult(spirit, r.hp, r.maxHp)
    }
    // ★ WHAT A SPAR PAYS (see spar-reward.ts) — XP and bond to the spirits that took the field, and
    // nothing else in either direction. Paid BEFORE the write below so the levels it grants ride the
    // same merge-write the wounds do; a payout persisted separately is a payout that can be lost.
    setSparLedger(sparLedgerLines(applySparPayout(s.allies, s.enemies, outcome)))
    // Wounds and what the spar taught outlive the fight, so both go back to the SHARED save — the
    // same party the 2D game and play3d read. Merge-write; see writeParty.
    writeParty()
    mistLedger.current = recordWithdrawal(mistLedger.current, s.patch, Date.now())
    saveMistLedger(SEED, mistLedger.current)
    setNearMist(null)
  }, [spar, closeCursorUI])

  /** Advance the tutorial only if it is currently AT `expected` — an out-of-order action (say,
   *  crafting planks before ever talking to Greg) is silently a no-op rather than skipping a step,
   *  same discipline `recordEdit` uses for a no-op edit: the state only changes when the fact
   *  actually changed it. */
  const advanceTutorial = useCallback((expected: TutorialStage, next: TutorialStage) => {
    const t = tutorial.current
    if (t.stage !== expected) return
    t.stage = next
    saveTutorial(SEED, t)
    setTutorialTick(v => v + 1)
  }, [])

  /**
   * E on Greg closes the dialogue that just opened. The two stages that ACT on close (greet's gift,
   * report's gate-opening talk) are handled here rather than on open — showing the line for the
   * stage you were in when you pressed E, then acting once you dismiss it, is what makes "the
   * current tutorial line" and "advancing quest state on close" both true at the same time.
   */
  const closeDialogue = useCallback(() => {
    setDialogueOpen(false)
    closeCursorUI()
    const t = tutorial.current
    if (t.stage === 'greet') {
      give(inv.current!, 'raw_mana_shard', 1)
      // The starter bag, delivered incrementally — canon (shimmer-quests-mainmap.md quest 1) has
      // Greg gift "crafting table, pot, grimoire, tools"; the table is the piece that exists.
      // The hand-craft recipe in voxel/recipes.ts stays as the REPLACEMENT path, per its header.
      give(inv.current!, 'crafting_table', 1)
      refreshHotbar()
      t.stage = 'cut'
      saveTutorial(SEED, t)
      setTutorialTick(v => v + 1)
    } else if (t.stage === 'report') {
      // The gate's own open/close write happens in World, reading this same ref — see the gate
      // block in the render loop. This only flips the stage the ref (and the save) hold.
      t.stage = 'done'
      saveTutorial(SEED, t)
      setTutorialTick(v => v + 1)
    }
  }, [refreshHotbar, closeCursorUI])

  /** Refine/build a recipe. The core hands back a plan; the host applies it. */
  const doCraft = useCallback((id: string) => {
    const plan = craftPlan(id)
    if (!plan || !canCraftRecipe(id, have, station)) return
    // Take everything BEFORE giving, and only give if every take succeeded — a partial spend that
    // still yields the output is a duplication bug, which is the one economy bug you cannot undo.
    if (!plan.take.every(t => countItem(inv.current!, t.itemId) >= t.count)) return
    for (const t of plan.take) removeItems(inv.current!, t.itemId, t.count)
    give(inv.current!, plan.give.itemId, plan.give.count)
    setCrafted(`${plan.give.count}× ${plan.give.itemId.replace(/_/g, ' ')}`)
    setCraftTick(t => t + 1)
    refreshHotbar()
    // ★ Tutorial 'planks'/'lantern' steps read the CRAFT OUTPUT, not the recipe id — any of the
    // three plank recipes satisfies 'planks' (Greg said "a tree", not which one).
    if (plan.give.itemId.endsWith('_plank')) advanceTutorial('planks', 'lantern')
    if (plan.give.itemId === 'mana_lantern') advanceTutorial('lantern', 'light')
  }, [have, refreshHotbar, advanceTutorial, station])

  /** Craft a tool and equip it. Tools keep their own table; this is the one surface that shows it.
   *  ★ TOOLS ARE BENCH WORK. You can snap a log into planks with your hands; you cannot shape a
   *  blade on your knee. Same split play3d always had (tools were station crafts there), and it is
   *  what makes the two craft lists DIFFERENT — the bench offers more than the pocket menu. */
  const doCraftTool = useCallback((id: string) => {
    if (station !== 'crafting_table') return   // spend-path enforcement; the UI grey is only a display
    const def = TOOL_DEFS[id]
    if (!def || !canCraftTool(id, inv.current!)) return
    const made = craftTool(id, inv.current!)
    if (!made) return
    tools.current![def.skillId] = made
    setCrafted(def.name)
    setCraftTick(t => t + 1)
    refreshHotbar()
  }, [refreshHotbar, station])

  /** The two tutorial facts World cannot resolve itself because they are mid-mining/mid-placement
   *  events, not craft calls — 'planks'/'lantern' are handled inline in `doCraft` above instead. */
  const onQuestEvent = useCallback((event: 'cut' | 'light') => {
    if (event === 'cut') advanceTutorial('cut', 'planks')
    else advanceTutorial('light', 'report')
  }, [advanceTutorial])

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // Typing beats verbs: keystrokes aimed at ANY text field (the console line, a settings
      // slider) must never run game verbs underneath what you're writing.
      if ((e.target as HTMLElement | null)?.tagName === 'INPUT') return
      // T / Enter / '/' — the chat console (MC's three doors, verbatim: '/' arrives pre-slashed).
      // Above the draw lock on purpose: a console you cannot open while your weapon is out is a
      // console you cannot use to debug the weapon.
      if (!consoleOpen && !dialogueOpen && !craftOpen && !bagOpen && !showSettings) {
        if (e.code === 'KeyT' || e.code === 'Enter') { e.preventDefault(); openCursorUI(); setConsoleSeed(''); setConsoleOpen(true); return }
        if (e.key === '/') { e.preventDefault(); openCursorUI(); setConsoleSeed('/'); setConsoleOpen(true); return }
      }
      const n = Number(e.key)
      /**
       * ── ★ THE SURFACE KEYS RUN FIRST, AND THEY RUN EVEN WITH A SURFACE UP ────────────────────
       * They are how you get OUT. Everything below them is a world verb, and a world verb under an
       * open menu is a key whose effect the player cannot see happen — which is how you end up
       * drawing a weapon or flipping into build mode from inside the bag and only finding out when
       * you close it. Ordered this way rather than gated in place because the close paths and the
       * world verbs want opposite answers to the same question.
       *
       * The draw lock still wraps them: with a weapon out neither hand is free, menus included.
       */
      if (e.code === 'Escape') {
        // Escape only reaches us when the pointer is already free (the browser eats it to exit the
        // lock first) — so close the surfaces AND settle the handoff ledger. closeCursorUI's relock
        // will be refused by the browser's post-Esc cooldown and swallowed; that is the one seam
        // where a canvas click is still needed, same as play3d.
        if (craftOpen) { setCraftOpen(false); closeCursorUI() }
        if (bagOpen || openChest) closeBag()
        if (dialogueOpen) closeDialogue()
        if (consoleOpen) { setConsoleOpen(false); closeCursorUI() }
        return
      }
      if (!drawn) {
        // Esc exits pointer lock anyway, so O is the settings key — it must not fight the browser.
        if (e.code === 'KeyO') {
          if (showSettings) { setShowSettings(false); closeCursorUI() }
          else { openCursorUI(); setShowSettings(true) }
          return
        }
        // C opens the crafting surface. It used to auto-craft the next affordable tool with no UI at
        // all, which hid the fact that the whole forestry ladder was uncraftable — you pressed C,
        // nothing happened, and nothing told you why. A list that shows what you CANNOT afford yet
        // is the difference between a broken key and a goal.
        if (e.code === 'KeyC') {
          if (craftOpen) { setCraftOpen(false); closeCursorUI() }
          else { openCursorUI(); setCraftOpen(true) }
          return
        }
        // I opens the satchel — same open/close-on-the-same-key shape as C and E, so the three
        // cursor surfaces behave identically. Escape dismisses them all as well.
        // M opens the map and closes it — the same one-key shape as I and C, and it is a CURSOR
        // surface (you read a map standing still), so it takes the pointer like the others do.
        if (e.code === 'KeyM') {
          if (showMap) { setShowMap(false); closeCursorUI() }
          else if (!cursorUIOpen) { openCursorUI(); setShowMap(true) }
          return
        }
        if (e.code === 'KeyI') {
          if (bagOpen || openChest) closeBag()
          else { openCursorUI(); setBagOpen(true) }
          return
        }
        // E talks to Greg when the crosshair is ON him, and closes the box that opens from it — the same key
        // both opens and dismisses, matching how C works for the crafting surface just above.
        if (e.code === 'KeyE') {
          if (dialogueOpen) closeDialogue()   // hands the cursor back itself
          else if (cursorUIOpen) { /* a surface is up and E is not its door — do nothing */ }
          else if (nearGreg) { openCursorUI(); setDialogueOpen(true) }
          // E is the interact key everywhere else too: at the bench it opens the craft surface —
          // the MC muscle memory — with Greg taking priority when you're near both. C still works.
          else if (nearTable) { openCursorUI(); setCraftOpen(true) }
          // A presence in the mist answers E last: Greg and the bench are both things you walked to
          // deliberately inside a settled place, and a patch never overlaps either. Ordered anyway
          // so the priority is stated rather than incidental.
          else if (nearMist && hasParty) startSpar(nearMist)
          return
        }
      }
      // ★ Past this line every key changes the WORLD, so a surface being up stops all of them.
      if (cursorUIOpen) return
      // ── ★ THE DRAW LOCK (Alex, 2026-08-07) ────────────────────────────────────────────────
      // "when the player has a weapon stowed the hotbar kicks in and when they draw their weapon
      // the hotbar and tools lock up." F is the toggle, matching play3d's holster key so the two
      // walkers do not disagree about what F means.
      //
      // The lock is a MODE, not a disable: it blocks the verbs (mine, place, switch slot, build)
      // rather than hiding the row, so you can still see what you were holding and what you will
      // be holding again the moment you stow. A hotbar that vanished would make drawing feel like
      // losing your inventory.
      //
      // ⚠ The weapon itself is NOT here yet. Guns live inside Shimmer3D (a 3-entry WEAPONS table
      // plus the FiringRange rig) and porting them is its own step — this ships the mode and the
      // lock, which is the half that decides how the hotbar behaves. Alex ruled guns DO cross into
      // the Ather (2026-08-07), overturning the 07-22 aegis; that ruling still needs authoring into
      // world/lucernyx.md — see CANON_GAPS.md.
      if (e.code === 'KeyF') { setDrawn(d => !d); return }
      // Q swaps the model, and ONLY while drawn — with the weapon stowed Q would be a key that
      // silently changes something you cannot see, which is how a player learns not to trust a HUD.
      if (e.code === 'KeyQ' && drawn) { setWeaponIdx(i => { const n = (i + 1) % WEAPONS.length; setAmmoUi(WEAPONS[n].clip); return n }); return }
      if (drawn) return   // every verb below is locked while the weapon is out
      if (n >= 1 && n <= 8) { if (build) setPieceIdx(Math.min(PIECES.length - 1, n - 1)); else setSel(n - 1) }
      if (e.code === 'Tab') { e.preventDefault(); setBuild(v => !v) }
      if (e.code === 'KeyR') setRot(r => ((r + 1) % 4) as Rotation)
      if (e.code === 'BracketLeft' || e.code === 'BracketRight') { /* spike tier, handled below */ }
      // Tool tier is a debug lever so the tier GATE can be felt in ten seconds: a tier-1 spike
      // REFUSES pure core, and that should be provable without crafting your way up first.
      // ★ THE TIER LEVER IS GONE. Tier comes from the equipped tool now, and a better tool is
      // CRAFTED from what you mined — which is the loop this port exists to close. The C / I / E / O
      // surface keys and Escape live ABOVE the world-verb gate now (see the block up there): they
      // are the doors, and a door that only works when nothing is open is not a door.
    }
    // Scroll to change slot — the reason tools are IN the row rather than on their own keys.
    // In BUILD mode the same wheel walks the piece catalogue (2026-08-08 — it used to dead-end
    // there, which stranded every piece past the number keys' muscle memory). Drawn still eats
    // the wheel: a weapon out means neither hand is free.
    const onWheel = (e: WheelEvent) => {
      // Same gate as the world verbs: scrolling a menu must not walk the hotbar underneath it, and
      // a bag long enough to scroll is exactly when you would notice.
      if (drawn || cursorUIOpen) return
      const dir = e.deltaY > 0 ? 1 : -1
      if (build) setPieceIdx(v => (v + dir + PIECES.length) % PIECES.length)
      else setSel(v => (v + dir + 8) % 8)
    }
    window.addEventListener('keydown', onKey)
    window.addEventListener('wheel', onWheel, { passive: true })
    return () => { window.removeEventListener('keydown', onKey); window.removeEventListener('wheel', onWheel) }
  }, [build, drawn, dialogueOpen, nearGreg, nearTable, craftOpen, showSettings, consoleOpen, closeDialogue, openCursorUI, closeCursorUI, nearMist, hasParty, startSpar, bagOpen, openChest, closeBag, cursorUIOpen, showMap])

  return (
    <div className="fixed inset-0 bg-[#0b0d14]">
      <Canvas camera={{ fov: 75, near: 0.1, far: 600 }} shadows={false}
              onCreated={({ gl }) => {
                canvasElRef.current = gl.domElement
                // OUR click-to-lock, canvas only. drei's PointerLockControls default binds its
                // click handler on DOCUMENT, so every click — including craft-menu buttons —
                // seized the mouse back mid-menu. That handler is disarmed below (selector that
                // matches nothing); this one is the replacement, gated on the handoff.
                gl.domElement.addEventListener('click', () => {
                  if (cursorUIOpenRef.current) return
                  try { const r = gl.domElement.requestPointerLock?.() as unknown as Promise<void> | undefined; r?.catch?.(() => {}) } catch { /* cooldown */ }
                })
              }}>
        {/* Sky, fog and all scene lights live in the rig now — the clock drives them. The old
            static five-liner IS the rig's DAY palette, so noon looks identical. */}
        {/* Canopy gloom (2026-08-08, the last zone-dressing item): the rig samples this to dim
            under dense canopy. Same forestness mask the PLANTER reads (sibling law) — the Thicket
            saturates it to ~0.97 through zone membership, so no zone check is needed here and any
            deep wild forest earns a lesser gloom by the same rule. */}
        {/* Mist patches (2026-08-09): the rig reads the SAME field the particles, the flora bloom
            and the encounter trigger read, so the fog can never close in somewhere the mist is not.
            One memoised cell lookup — cheap enough to sample per frame, which a 52-block feature
            needs (see mist.ts). */}
        <VoxelDayNight
          gloomAt={(x, z) => {
            const f = forestness(SEED, x / 16, z / 16)
            const t = (f - 0.62) / (0.95 - 0.62)
            const c = t < 0 ? 0 : t > 1 ? 1 : t
            return c * c * (3 - 2 * c)
          }}
          mistAt={(x, z) => mistAt(x, z, SEED)}
        />
        <World
          inv={inv} toolTier={toolTier} toolSkill={toolSkill} vitals={vitals} mana={mana}
          /* A tool in hand is not a block in hand — RMB must not place while you hold a spade.
             `drawn` blanks it too: a weapon out means neither hand is free. */
          selItem={(() => { const e = hotbar[sel]; return !drawn && e ? e.itemId : null })()}
          selSlot={sel}
          weaponDrawn={drawn}
          weaponIdx={weaponIdx}
          onAmmo={setAmmoUi}
          onStats={setStats} onPerf={setPerf} onSay={say} runeTick={runeTick}
          onPos={(p, yaw) => {
            mapPos.current = { x: p.x, z: p.z }
            mapHeading.current = yaw
            setPos(`x ${p.x.toFixed(0)}  y ${p.y.toFixed(0)}  z ${p.z.toFixed(0)}`)
          }}
          onLook={setLook} onInvChange={refreshHotbar}
          worker={worker} incoming={incoming} inflight={inflight} settings={settings}
          build={build} pieceIdx={pieceIdx} rot={rot}
          tools={tools} skills={skills} onSkill={setSkillHud} onLevel={setLevelUp} onTool={setActiveTool}
          tutorial={tutorial} onQuestEvent={onQuestEvent} onNearGreg={setNearGreg}
          mistLedger={mistLedger} onNearMist={setNearMist} sparring={!!spar}
          onNearTable={setNearTable} cmdOut={worldCmd} pot={potOps}
          onOpenChest={(c) => { openCursorUI(); setOpenChest(c) }}
          onOpenStation={(st) => { openCursorUI(); setOpenStation(st) }}
          uiOpen={cursorUIOpenRef}
        />
        {/* selector: deliberately matches NOTHING. Without it drei binds click-to-lock on the whole
            DOCUMENT (and that binding ignores `enabled`), which re-locked the pointer on every
            craft-menu click. Locking is owned by the canvas listener in onCreated + the handoff.
            ⚠ No `enabled` gate here — it disconnects the controls' pointerlockchange listener, and
            the handoff's re-lock on menu-close lands BEFORE React re-enables them, so isLocked
            stayed false and the camera froze with the pointer captured. Stray canvas clicks while
            a menu is up are already refused by the onCreated click handler. */}
        <PointerLockControls selector="#voxel3d-no-autolock" />
      </Canvas>
      <Hud stats={stats} perf={settings.showFps ? perf : null} toast={toast} pos={pos} look={look} hotbar={hotbar} sel={sel} tier={tier} held={held}
           build={build} pieceIdx={pieceIdx} rot={rot} inv={inv}
           skill={skillHud} levelUp={levelUp} crafted={crafted} tools={tools} skills={skills}
           activeTool={activeTool}
           isOwner={isOwner} drawn={drawn} weaponIdx={weaponIdx} ammoUi={ammoUi}
           tutorialStage={tutorial.current.stage} nearGreg={nearGreg} dialogueOpen={dialogueOpen}
           nearTable={nearTable} craftOpen={craftOpen} nearMist={nearMist} hasParty={hasParty}
           sparLedger={sparLedger} vitals={vitals} />
      {showSettings && <SettingsPanel s={settings} update={update} onClose={() => { setShowSettings(false); closeCursorUI() }} />}
      {craftOpen && (
        <CraftPanel have={have} tools={tools} tick={craftTick} station={station}
                    onCraft={doCraft} onCraftTool={doCraftTool} onClose={() => { setCraftOpen(false); closeCursorUI() }} />
      )}
      {openStation && (
        <StationPanel st={openStation} have={have} inv={inv}
                      onChange={() => { setCraftTick(v => v + 1); refreshHotbar() }}
                      onSay={say}
                      onClose={() => { setOpenStation(null); closeCursorUI() }} />
      )}
      {(bagOpen || openChest) && (
        <BagPanel inv={inv} chest={openChest} tick={craftTick} sel={sel}
                  dragFrom={dragFrom} setDragFrom={setDragFrom}
                  onMove={(f, t) => { moveRef(f, t); setCraftTick(v => v + 1) }}
                  onSplit={(f, t, m) => { splitRef(f, t, m); setCraftTick(v => v + 1) }}
                  onQuick={(r) => { quickRef(r); setCraftTick(v => v + 1) }}
                  onClose={closeBag} tools={tools} skills={skills} party={party} />
      )}
      {/* The map — minimap always up, M expands it. Hidden while another cursor surface owns the
          screen, so it never sits on top of the bag or the craft grid. */}
      {!cursorUIOpen && !showMap && (
        <VoxelMiniMap seed={SEED} seenRef={seenRef} posRef={mapPos} headingRef={mapHeading}
          onExpand={() => { openCursorUI(); setShowMap(true) }} />
      )}
      {showMap && (
        <VoxelMap seed={SEED} seenRef={seenRef} seenTick={seenTick} posRef={mapPos} headingRef={mapHeading}
          onClose={() => { setShowMap(false); closeCursorUI() }} />
      )}

      {dialogueOpen && <GregDialogue stage={tutorial.current.stage} onClose={closeDialogue} />}

      {/* ★ THE SPAR. The SAME real-time arena every other fight runs (`engine/arena.ts` via
          ArenaBattle) — the spirit fights on its own instinct and the Keeper coaches. That is not a
          reuse convenience: canon rules it (2026-08-09), because a turn-based move menu would put
          the Keeper back in command of the spirit, which is the collar wearing practice clothes,
          inside the one feature whose whole justification is practice.
          No `collaredIndices` and `enemyTier` left at its wild default: nothing here is leashed and
          nothing here is a champion — it is a wild spirit answering its own ground. */}
      {spar && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 50, background: '#0a0a12' }}>
          <ArenaBattle
            allies={spar.allies}
            enemies={spar.enemies}
            title={`A ${spar.name} answers the mist`}
            onEnd={endSpar}
            continueLabel="BACK TO THE GARDEN"
          />
        </div>
      )}
      <ChatConsole open={consoleOpen} seed={consoleSeed} log={chatLog} ctx={consoleCtx}
                   onSubmit={submitLine} onClose={() => { setConsoleOpen(false); closeCursorUI() }} />
    </div>
  )
}

/**
 * The clock — top-right round DIAL (Alex's whiteboard, 2026-08-07). Self-contained state on a 1s
 * interval so the tick re-renders THIS chip and nothing else — the sky reads the clock per-frame
 * off in the Canvas; the HUD only needs minutes.
 *
 * A sun/moon marker rides the rim at the angle of `dayProgress()`: 0 (midnight) sits at the bottom,
 * 0.5 (noon) sits at the top, sweeping clockwise through the right side for the first half-day (an
 * eyeballed direction, not canon — Alex can flip it). The time renders small, centered. The phase
 * name + `PINNED` flag (the same content the old inline chip showed — see day-cycle.ts for why a
 * pinned tab must never read as a broken cycle) move to the small rectangle directly below the
 * dial, matching the board.
 */
function Clock() {
  const [now, setNow] = useState(() => dayProgress())
  useEffect(() => {
    const t = setInterval(() => setNow(dayProgress()), 1000)
    return () => clearInterval(t)
  }, [])
  const phase = getPhase(now)
  // ✦ not ☾ at night: the Ather has NO MOON (Alex ruling 2026-08-08, CANON_GAPS has the open
  // "what silvers the night" question). A crescent on the HUD would assert a body the sky refuses.
  const glyph = phase === 'night' ? '✦' : phase === 'day' ? '☀' : phase === 'dawn' ? '🌅' : '🌇'
  const DIAL = 60             // dial diameter, px
  const R = DIAL / 2 - 9      // marker orbit radius — kept inside the rim
  const theta = now * 2 * Math.PI
  const markerTop = DIAL / 2 + R * Math.cos(theta) - 7   // -7 centers the ~14px glyph
  const markerLeft = DIAL / 2 + R * Math.sin(theta) - 7
  return (
    <div className="absolute top-3 right-3 flex flex-col items-center pointer-events-none">
      <div className="relative rounded-full border border-white/20 bg-black/45" style={{ width: DIAL, height: DIAL }}>
        <span className="absolute text-[13px] leading-none" style={{ top: markerTop, left: markerLeft }}>{glyph}</span>
        <div className="absolute inset-0 flex items-center justify-center text-[10px] font-mono tabular-nums text-white/85">
          {getDisplayTime(now)}
        </div>
      </div>
      <div className="mt-1 px-1.5 py-0.5 rounded border border-white/15 bg-black/45 text-[9px] font-mono text-white/60 whitespace-nowrap">
        {phase}
        {isTimePinned() && <span className="ml-1.5 text-amber-300/90">PINNED</span>}
      </div>
    </div>
  )
}

/**
 * The keeper's two bars — shield over health, Apex-style, because that is the order they empty in.
 *
 * ★ POLLED, NOT RE-RENDERED. `vitals` is a ref the frame loop writes every time something lands, and
 * routing that through React state would re-render the whole HUD on every tick of a drain. Same
 * pattern the ammo readout and the clock already use here: read on an interval, write the DOM width
 * directly, and leave the component tree alone. 10 Hz is well under a frame and well over the eye.
 */
function ResourceBars({ vitals }: { vitals: React.RefObject<Vitals> }) {
  const hpEl = useRef<HTMLDivElement>(null)
  const shEl = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const id = setInterval(() => {
      const v = vitals.current
      if (!v) return
      if (hpEl.current) hpEl.current.style.width = `${Math.max(0, (v.hp / (v.hpMax || 1)) * 100)}%`
      if (shEl.current) shEl.current.style.width = `${Math.max(0, (v.shield / (v.shieldMax || 1)) * 100)}%`
    }, 100)
    return () => clearInterval(id)
  }, [vitals])
  return (
    // ★ A PLATE, NOT BARE BARS. The first cut drew these straight onto the canvas and the health bar
    // was EMERALD — a green bar on a green world, which vanished into the grass in the very first
    // screenshot. The style guide's rule is not decoration: text and readouts never sit raw on a
    // scene, because the scene is the one thing whose colour you do not control. Dark plate, and
    // health goes warm so the two bars can never be confused with each other or with the ground.
    <div className="absolute bottom-4 left-4 w-44 rounded bg-black/45 p-1.5 ring-1 ring-white/10
                    flex flex-col gap-1 pointer-events-none font-mono">
      {/* Shield above health, in the order a fight actually spends them. */}
      <div className="h-[6px] rounded-sm bg-black/60 overflow-hidden">
        <div ref={shEl} className="h-full bg-sky-300 transition-[width] duration-100" style={{ width: '100%' }} />
      </div>
      <div className="h-[6px] rounded-sm bg-black/60 overflow-hidden">
        <div ref={hpEl} className="h-full bg-rose-400 transition-[width] duration-100" style={{ width: '100%' }} />
      </div>
    </div>
  )
}

function Hud({ stats, perf, toast, pos, look, hotbar, sel, tier, held, build, pieceIdx, rot, inv, skill, levelUp, crafted, tools, skills, activeTool, isOwner, drawn, weaponIdx, ammoUi, tutorialStage, nearGreg, dialogueOpen, nearTable, craftOpen, nearMist, hasParty, sparLedger, vitals }: {
  stats: string; pos: string
  /** The say line — player-addressed, held ~4s. See the SAY CHANNEL note on VoxelWorld. */
  toast: { text: string; at: number } | null
  look: { name: string; progress: number; refused: boolean } | null
  hotbar: (HotbarEntry | null)[]; sel: number; tier: number
  held: { text: string; out: boolean } | null
  build: boolean; pieceIdx: number; rot: Rotation
  /** Latest frame-meter window, or null when the meter is off — the gate lives at the CALL site so
   *  this component never has to know a setting exists. */
  perf: PerfSample | null
  inv: React.RefObject<Inventory>
  skill: { id: string; level: number; xp: number; next: number } | null
  levelUp: string | null
  crafted: string | null
  tools: React.RefObject<EquippedTools>
  /** Full skill set (all 6, level+xp), for the tool gauges — `skill` above is only the last-trained
   *  one and can't drive four gauges at once. */
  skills: React.RefObject<SkillSet>
  /** Which family is mining right now, from the mining block's onTool signal. Drives gauge glow. */
  activeTool: string | null
  isOwner: boolean
  drawn: boolean
  weaponIdx: number
  ammoUi: number
  /** The tutorial's current objective — drives the HUD chip below. */
  tutorialStage: TutorialStage
  /** The crosshair is on Greg, in reach, unoccluded — World's per-frame aim test. Drives "E — talk".
   *  The prompt appearing IS the highlight: there is no outline on him, so this is how a player
   *  learns the verb is armed. Which is why it must never show for someone he is not looking at. */
  nearGreg: boolean
  dialogueOpen: boolean
  /** The presence in spar range, or null — names itself in the prompt before you commit. */
  nearMist: Resident | null
  hasParty: boolean
  sparLedger: string[] | null
  /** The keeper's health + shields. A ref: the bars poll it, nothing re-renders. */
  vitals: React.RefObject<Vitals>
  /** Within reach of a placed crafting table — drives the "E — craft" prompt. */
  nearTable: boolean
  craftOpen: boolean
}) {
  return (
    <>
      <div className="absolute top-3 left-3 text-[11px] font-mono text-white/80 bg-black/45 rounded px-2.5 py-1.5 leading-relaxed pointer-events-none">
        {/* Not a test bed since 2026-08-07 — the room wall and /shimmer both land here now, so this
            is Shimmer. The label said TEST BED while it was reachable only by URL. */}
        <div className="text-white/95 font-semibold tracking-wide">SHIMMER</div>
        {/* A way OUT. This world had no exit and no entrance — you could only arrive by typing the
            URL and only leave with the back button. The parent block is pointer-events-none so the
            canvas keeps the mouse; these opt back in.
            The play3d link is the LEGACY door and is owner-only, the exact inverse of yesterday
            (play3d's ☰ menu held the owner-only door to here). play3d still holds the systems being
            ported across, so it stays reachable — just not to anyone who wandered in. */}
        <div className="flex gap-2 text-white/45 pointer-events-auto">
          <a href="/room?wall=0" className="hover:text-white/85 underline decoration-white/20">⌂ room</a>
          {isOwner && <a href="/shimmer/play3d" className="hover:text-white/85 underline decoration-white/20">❈ play3d (legacy)</a>}
        </div>
        <div>{pos}</div>
        {/* ── ★ THE FRAME METER ────────────────────────────────────────────────────────────────
            Above the plumbing line and brighter than it, because while you are measuring this is
            the only number on screen you are actually reading.
            · `ms` sits beside `fps` because ms is what SUBTRACTS across an A/B — 60→30fps and
              30→20fps are the same 16.7ms of added work, and only one of those pairs looks equal.
            · `worst` is the whole reason this beats an average: the remesh queue draining as you
              walk into new ground is a HITCH, and a mean frame time is exactly the statistic that
              hides one.
            · `tabular-nums` so the digits do not dance while you watch them. */}
        {perf && (
          <div data-perf className="font-mono tabular-nums text-white/90">
            {perf.fps} fps · {perf.ms.toFixed(1)} ms
            <span className={perf.worst > 33 ? 'text-amber-300/90' : 'text-white/45'}>
              {' '}· worst {perf.worst.toFixed(0)} ms
            </span>
          </div>
        )}
        {/* `data-stats` is the handle `scripts/world-shot.mts` scrapes — the HUD line is the only
            place the renderer's live counters surface, and a headless perf run needs to read them
            without the class name (a styling detail) being load-bearing. */}
        <div data-stats className="text-white/55">{stats}</div>
        {/* Shift is slide now, not sprint — run is automatic (play3d locomotion, port step 5). */}
        <div className="mt-1 text-white/45">click to look · WASD · space jump · shift slide · hold space climb · V fly</div>
        {build
          ? <div className="text-amber-200/80">BUILD · RMB place · LMB deconstruct · R rotate · 1-8 piece · Tab exit</div>
          : <div className="text-white/45">hold LMB mine · RMB place · scroll/1-8 slot · Q drop (shift = stack) · F draw · C craft · Tab build · T chat, / commands</div>}
        {/* ★ The tools are Greg's, from engine/tools.ts, unchanged. Tier is what you HOLD now. */}
        <div className="text-white/40 mt-1">
          {(['forestry', 'prospecting'] as const).map(sk => {
            const t = getEquippedTool(tools.current!, sk)
            const d = t ? getToolDef(t) : undefined
            return <span key={sk} className="mr-3">{sk.slice(0, 4)}: {d?.name ?? '—'}</span>
          })}
        </div>
      </div>

      <Clock />

      {/* ★ THE SAY LINE. Sits above the hotbar, centre-low — where the eye already is during play,
          not in the debug corner it used to die in. Plated, because this file's own UI law says text
          never sits raw on a scene, and a refusal read over bright canopy is the case that matters.
          `pointer-events-none` throughout: it must never eat a click meant for the world. */}
      {toast && (
        <div className="pointer-events-none absolute inset-x-0 bottom-[19%] z-30 flex justify-center px-4">
          <div key={toast.at}
               className="max-w-[34rem] rounded border border-white/15 bg-black/70 px-3.5 py-2 text-center
                          text-[13px] leading-snug text-amber-100/90 shadow-lg backdrop-blur-[2px]
                          motion-safe:animate-[fadeSlideIn_140ms_ease-out]">
            {toast.text}
          </div>
        </div>
      )}

      {/* The tutorial objective chip — caps label dim, value bright, same rule the tool row above
          and the hotbar counts already follow. Hidden once the gate is open: there is no more
          objective to chase. */}
      {tutorialStage !== 'done' && (
        <div className="absolute top-3 left-1/2 -translate-x-1/2 text-[10px] font-mono bg-black/45 rounded px-2.5 py-1 pointer-events-none">
          <span className="text-white/40 uppercase tracking-[.16em]">objective </span>
          <span className="text-amber-200/90">{OBJECTIVE_LABEL[tutorialStage]}</span>
        </div>
      )}

      {/* "E — talk" — shown while the crosshair is on Greg. Hidden while the box he opens is already up.
          The bench borrows the same prompt slot ("E — craft"); Greg wins when both are near,
          mirroring the KeyE handler's priority. */}
      {nearGreg && !dialogueOpen && (
        <div className="absolute left-1/2 top-[63%] -translate-x-1/2 text-center pointer-events-none">
          <div className="text-[11px] font-mono tracking-wide text-white/85">E — talk</div>
        </div>
      )}
      {!nearGreg && nearTable && !craftOpen && (
        <div className="absolute left-1/2 top-[63%] -translate-x-1/2 text-center pointer-events-none">
          <div className="text-[11px] font-mono tracking-wide text-white/85">E — craft</div>
        </div>
      )}
      {/* ★ The presence names itself before you commit — the whole consent design. You are told
          WHICH spirit answered this ground and can walk away. A keeper with no spirits is told the
          truth rather than being given a dead key: canon's own order is that Greg's seed sleeps a
          while yet, so watching is the only thing to do here and the line says so.
          ★ THE LEVEL IS PART OF THAT SENTENCE, not decoration. A patch's strength is a property of
          the region now (mist-difficulty.ts), so mist you cannot yet take exists on purpose — and
          an absolute band is only readable if it is actually READ to you. Printing it is what makes
          "come back when you are stronger" a choice instead of an ambush; it is also the whole
          reason the pair needs no party-size floor. */}
      {!nearGreg && !nearTable && nearMist && (
        <div className="absolute left-1/2 top-[63%] -translate-x-1/2 text-center pointer-events-none">
          <div className="text-[13px] font-mono tracking-[.18em] uppercase" style={{ color: MIST_PROMPT[nearMist.element] }}>
            {nearMist.name} <span className="text-white/70 tabular-nums">lv {nearMist.level}</span>
          </div>
          {nearMist.second && (
            <div className="text-[12px] font-mono tracking-[.16em] uppercase" style={{ color: MIST_PROMPT[nearMist.second.element] }}>
              {nearMist.second.name} <span className="text-white/70 tabular-nums">lv {nearMist.second.level}</span>
            </div>
          )}
          <div className="mt-1 text-[11px] font-mono tracking-wide text-white/85">
            {hasParty ? 'E — spar' : 'it waits for a spirit you do not have yet'}
          </div>
        </div>
      )}

      {/* Skill progress — only while it is moving, so it is information rather than furniture. */}
      {skill && (
        <div className="absolute bottom-24 left-1/2 -translate-x-1/2 w-56 pointer-events-none">
          <div className="flex justify-between text-[10px] font-mono text-white/70 mb-0.5">
            <span className="uppercase tracking-wider">{skill.id}</span>
            <span className="tabular-nums">lv {skill.level}</span>
          </div>
          <div className="h-1 bg-black/55 rounded overflow-hidden">
            <div className="h-full bg-emerald-300" style={{ width: `${Math.min(100, (skill.xp / Math.max(1, skill.next)) * 100)}%` }} />
          </div>
        </div>
      )}

      {levelUp && (
        <div className="absolute top-1/3 left-1/2 -translate-x-1/2 text-center pointer-events-none">
          <div className="text-emerald-300 font-mono text-sm tracking-widest uppercase">{levelUp}</div>
        </div>
      )}
      {crafted && (
        <div className="absolute top-[38%] left-1/2 -translate-x-1/2 text-center pointer-events-none">
          <div className="text-amber-200 font-mono text-xs tracking-wider">crafted {crafted}</div>
        </div>
      )}
      {/* The practice ledger. A HUD line rather than a reward modal on purpose: play3d's spoils
          reveal earns its screen because a hold pays marks and gates the story, while a spar pays
          only what practice pays. A second wall after the arena's own end screen would make the
          walk back into the mist feel like leaving a menu. Reads as what it is — a note. */}
      {sparLedger && (
        <div className="absolute top-[30%] left-1/2 -translate-x-1/2 text-center pointer-events-none">
          <div className="text-[10px] font-mono uppercase tracking-[.22em] text-white/50">the spar taught</div>
          {sparLedger.map((line, i) => (
            <div key={i} className="mt-1 text-[12px] font-mono tracking-wide tabular-nums text-emerald-200/90">{line}</div>
          ))}
        </div>
      )}
      <div className="hidden">
      </div>

      {look && (
        <div className="absolute left-1/2 top-[56%] -translate-x-1/2 text-center pointer-events-none">
          <div className={`text-[11px] font-mono tracking-wide ${look.refused ? 'text-red-300' : 'text-white/85'}`}>
            {look.name}{look.refused && ' — spike too weak'}
          </div>
          {look.progress > 0 && (
            <div className="mt-1 w-28 h-1 bg-black/50 rounded overflow-hidden mx-auto">
              <div className="h-full bg-amber-300" style={{ width: `${Math.min(100, look.progress * 100)}%` }} />
            </div>
          )}
        </div>
      )}

      <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-1 h-1 rounded-full bg-white/80 pointer-events-none" />

      {/* ★ The build palette REPLACES the hotbar rather than sitting beside it. One bar, whose meaning
          follows the mode, so there is never a question about which row a number key is talking to. */}
      {build && (
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-1.5 pointer-events-none">
          {PIECES.map((pc, i) => {
            const affordable = pc.cost.every(c => countItem(inv.current!, c.itemId) >= c.count)
            return (
              <div key={pc.id} className={`w-20 h-14 rounded border-2 px-1 flex flex-col items-center justify-center text-[9px] font-mono
                ${i === pieceIdx ? 'border-amber-300 bg-black/70' : 'border-white/20 bg-black/45'}`}>
                <div className={i === pieceIdx ? 'text-amber-200' : 'text-white/70'}>{pc.name}</div>
                <div className={affordable ? 'text-white/45' : 'text-red-300/80'}>
                  {pc.cost.map(c => `${c.count}×${c.itemId.replace(/^block_|_plank$/g, '')}`).join(' ')}
                </div>
              </div>
            )
          })}
        </div>
      )}
      {build && (
        <div className="absolute bottom-[4.6rem] left-1/2 -translate-x-1/2 text-[10px] font-mono text-white/50 pointer-events-none">
          {/* Pieces face where you look; this is the R key's manual quarter-turn on top of that. */}
          {rot === 0 ? 'facing you · R to turn' : `R turn +${rot * 90}°`}
        </div>
      )}

      {/* Item art is DERIVED from each block's own texture (`tex/item-icon.ts`) — an icon can never
          show something the block is not, and a new block gets one the moment it gets a texture.
          ★ The hotbar is 8 FIXED slots, ITEMS ONLY (2026-08-07) — always all 8, occupied or not, so
          number keys 1-8 always mean the same physical position. The four tool families live in the
          round arc off its right end (`ToolArc`, below), not in this row.
          ★ DRAWN dims the whole row rather than hiding it: you keep seeing what you will be holding
          again when you stow, so drawing reads as "hands full", not "inventory gone".
          The inner div is `relative` so `ToolArc` can anchor itself to this bar's right edge with
          `left-full`, regardless of how much of the row is actually occupied. */}
      {!build && <div className={`absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none transition-opacity ${drawn ? 'opacity-35' : 'opacity-100'}`}>
        {/* The name of what you are holding, over the bar. Always rendered so the row never shifts
            when it appears; a baked shadow because HUD text must never sit raw on the scene. */}
        <div className={`mb-1.5 h-5 text-center text-[13px] font-medium tracking-[0.08em] text-amber-100
          [text-shadow:0_1px_3px_rgba(0,0,0,0.9)] transition-opacity duration-500
          ${held && !held.out ? 'opacity-100' : 'opacity-0'}`}>
          {held?.text ?? ''}
        </div>
        <div className="relative inline-flex items-end gap-1.5">
          {Array.from({ length: 8 }, (_, i) => {
            const e = hotbar[i]
            const selected = i === sel && !drawn
            return (
              <div key={i} className={`w-12 h-12 rounded border-2 flex flex-col items-center justify-center text-[9px] font-mono
                ${selected ? 'border-amber-300 bg-black/60' : 'border-white/20 bg-black/40'}`}>
                {e ? (
                  <>
                    <ItemChip itemId={e.itemId} size={24} />
                    <div className="text-white/80 mt-0.5 tabular-nums">{e.count}</div>
                  </>
                ) : <span className="text-white/25">{i + 1}</span>}
              </div>
            )
          })}
          <ToolArc activeTool={activeTool} tools={tools} skills={skills} />
        </div>
      </div>}
      {/* The one piece of state the dimmed row cannot show by itself. */}
      {drawn && !build && (
        <div className="absolute bottom-[4.75rem] left-1/2 -translate-x-1/2 flex items-baseline gap-3 font-mono pointer-events-none">
          <span className="text-[11px] tracking-[.2em] uppercase text-amber-200/85">{WEAPONS[weaponIdx].name}</span>
          {/* tabular-nums so the count does not jitter the layout as it ticks down */}
          <span className="text-[13px] tabular-nums text-white/90">{ammoUi}<span className="text-white/35">/{WEAPONS[weaponIdx].clip}</span></span>
          <span className="text-[9px] tracking-[.18em] uppercase text-white/35">RMB aim · Q swap · F stow</span>
        </div>
      )}
      {!build && <div className="absolute bottom-[4.6rem] left-1/2 -translate-x-1/2 text-[10px] font-mono text-white/50 pointer-events-none">
        spike tier {tier}
      </div>}
      {!build && <ResourceBars vitals={vitals} />}
    </>
  )
}


/**
 * ── ★ THE BAG — one window onto the grid the hotbar already reads, plus whatever it is open ON ──
 * Slots 0-7 ARE the hotbar, drawn here as the bottom row and set apart by a rule rather than by
 * being a different widget. That is the whole point: dragging a stack from the satchel to the bar
 * is a slot swap, not a transfer between two containers with their own rules, and what you arrange
 * here is exactly what your fingers find on 1-8.
 *
 * ★ A CHEST IS THIS PANEL WITH A SECOND GRID ON TOP, not a screen of its own (2026-08-11). The bag
 * half of a chest screen and the satchel are the same 24 slots, so a separate chest component would
 * be two places for one stack to look like two different things — the shape the hotbar and satchel
 * swatches already had once, and the reason `ItemChip` exists.
 *
 * Drag is CLICK-then-CLICK, not HTML5 drag-and-drop: the pointer has just been released from lock,
 * dragend never fires reliably over a WebGL canvas, and a half-finished HTML5 drag leaves a stack
 * in limbo. Click to lift, click to place, click the same slot to cancel — three states a player
 * can always see, and no way to lose an item between them. SHIFT-click sends a whole stack straight
 * across to the other container, because emptying a bag one pair of clicks at a time is a chest
 * nobody fills.
 */
/**
 * How far the hand has to travel before a press stops being a click and becomes a drag. Small enough
 * that a deliberate drag never reads as a click, large enough that the tremor in a click never reads
 * as a drag — and a click that silently became a one-item drag would be a stack quietly losing an
 * item, which is the failure mode this whole panel is written against.
 */
const DRAG_SLOP = 5

/** One place each for what a lift LOOKS like, so a fourth mode cannot be added and left invisible. */
const LIFT_LOOK: Record<LiftMode, string> = {
  whole: 'border-amber-300 bg-amber-300/20',
  half: 'border-sky-300 bg-sky-300/20',
  one: 'border-emerald-300 bg-emerald-300/20',
}
const LIFT_BADGE: Record<LiftMode, string> = {
  whole: 'bg-amber-300', half: 'bg-sky-300', one: 'bg-emerald-300',
}

/**
 * The RUNES tab — your runes, and what each one opens.
 *
 * ── THE BOOK IS DERIVED, NEVER KEPT ───────────────────────────────────────────────────────────
 * `keeper-moves.ts` already builds the whole index by inverting each move's rune requirement, so
 * this component owns no lists of its own and cannot drift from the registry. Three states, which
 * are the three a keeper actually cares about (#309):
 *   KNOWN     — you hold every rune it needs. Yours now.
 *   REACHABLE — one rune away, along your rune's own element/state lanes. The path forward.
 *   LOCKED    — everything else. Shown as a count, not a list; a wall of unreachable names is
 *               noise, and the number alone still says "there is more".
 *
 * ★ SCATTER'S EMPTY LIST IS CANON, NOT A GAP. `runes.data.ts` states it: the Schools do not teach
 * Scatter, scholars do not recognise it, and a Scatter-born keeper has no trainable keeper move at
 * all. So an empty book here must read as a *fact about the world*, never as "content coming soon" —
 * Benji carries this rune, and the emptiness is the point of him.
 */
function RunesTab() {
  // localStorage read, so it happens once per mount rather than per render.
  const [inv] = useState(() => loadRuneInventory())
  const owned = inv.owned
  const known = knownMoves(owned)
  const learnable = learnableMoves(owned)
  const lockedCount = Math.max(0, Object.values(MOVES_BY_RUNE).flat()
    .filter((m, i, a) => a.findIndex(x => x.id === m.id) === i).length - known.length - learnable.length)

  if (owned.length === 0) {
    return <TabEmpty>You have no rune yet. A keeper is born with one — the birth screen sets it.</TabEmpty>
  }

  const row = (label: string, moves: typeof known, tone: string) => moves.length > 0 && (
    <div className="mb-4">
      <div className="mb-1.5 text-[10px] uppercase tracking-[0.16em] text-white/35">{label} · {moves.length}</div>
      <div className="flex flex-col gap-1">
        {moves.map(m => (
          <div key={m.id} className="rounded border border-white/10 bg-white/[0.03] px-2.5 py-1.5">
            <div className="flex items-baseline gap-2">
              <span className={`text-[12px] ${tone}`}>{m.name}</span>
              <span className="text-[9px] uppercase tracking-[0.14em] text-white/25">{m.tier}</span>
              {m.needs && <span className="text-[9px] text-amber-200/40">needs {m.needs}</span>}
            </div>
            <div className="text-[10px] leading-snug text-white/40">{m.effect}</div>
          </div>
        ))}
      </div>
    </div>
  )

  return (
    <div>
      <div className="mb-4 flex flex-wrap gap-1.5">
        {owned.map(id => {
          const r = RUNES.find(x => x.id === id)
          return (
            <span key={id} className="rounded px-2 py-1 text-[11px] uppercase tracking-[0.14em]"
                  style={{ color: r?.glow ?? '#fff', background: `${r?.glow ?? '#fff'}18` }}>
              {r?.name ?? id}{id === inv.birth && <span className="ml-1.5 text-[9px] text-white/35">birth</span>}
            </span>
          )
        })}
      </div>
      {known.length === 0 && learnable.length === 0 ? (
        <div className="rounded border border-white/10 bg-white/[0.03] px-3 py-2.5 text-[11px] leading-relaxed text-white/40">
          No move answers to this rune. The Schools do not teach it and scholars do not name it —
          a keeper born to it manifests, untrained. That is the rune, not a missing page.
        </div>
      ) : (
        <>
          {row('Known', known, 'text-amber-200/90')}
          {row('One rune away', learnable, 'text-white/70')}
          {lockedCount > 0 && (
            <div className="text-[10px] text-white/25">
              {lockedCount} more move{lockedCount === 1 ? '' : 's'} sit behind runes you do not hold.
            </div>
          )}
        </>
      )}
    </div>
  )
}

/**
 * The TOOLS tab — the four gathering families, what you hold in each, and how far your skill has come.
 *
 * ★ This is the surface `ToolArc` deliberately is not. That arc is read-only on purpose ("nothing
 * here is clickable, which is the point") because it lives over the world during play. The same
 * four sockets need somewhere they CAN be inspected without a HUD element growing a menu, and this
 * is it — same data, same order, no second source.
 */
function ToolsTab({ tools, skills }: {
  tools: React.RefObject<EquippedTools>
  skills: React.RefObject<SkillSet>
}) {
  return (
    <div className="flex flex-col gap-1.5">
      {TOOL_FAMILIES.map(family => {
        const held = getEquippedTool(tools.current!, family)
        const def = held ? getToolDef(held) : undefined
        const sk = skills.current![family]
        const need = xpForSkillLevel(sk.level)
        const pct = Math.min(1, sk.xp / Math.max(1, need))
        return (
          <div key={family} className="rounded border border-white/10 bg-white/[0.03] px-3 py-2">
            <div className="flex items-baseline gap-2">
              <span className="text-[12px] uppercase tracking-[0.14em] text-amber-200/80">{family}</span>
              <span className="ml-auto text-[10px] tabular-nums text-white/35">lv {sk.level}</span>
            </div>
            <div className="mt-1 flex items-baseline gap-2">
              {/* An empty hand is a real state, not a missing tool — bare hands mine, just slowly. */}
              <span className="text-[11px] text-white/60">{def?.name ?? 'bare hands'}</span>
              {def && <span className="text-[9px] uppercase tracking-[0.14em] text-white/25">tier {def.tier}</span>}
            </div>
            <div className="mt-1.5 h-1 overflow-hidden rounded bg-white/10">
              <div className="h-full bg-amber-300/50" style={{ width: `${(pct * 100).toFixed(1)}%` }} />
            </div>
            <div className="mt-1 text-[9px] tabular-nums text-white/25">{sk.xp} / {need} xp</div>
          </div>
        )
      })}
    </div>
  )
}

/**
 * The LOADOUT tab — which of your known moves sit on G / Z / X / C.
 *
 * ── WHAT WAS ACTUALLY MISSING (2026-08-12) ────────────────────────────────────────────────────
 * Not the chain. `cast.ts` has mapped LOADOUT SLOT → MOVE → ARCHETYPE since 2026-08-03 (63 asserts):
 * CAST_SLOTS, SLOT_KEYS, eligibleMoves, canSlot, castForMove, isBuilt. What was missing is that
 * nothing ever stored a CHOICE — `Shimmer3D` recomputed `defaultLoadout(owned)` on every load, so a
 * keeper received a loadout and could never pick one. `loadout.ts` is that half; this is its face.
 *
 * ★ SLOTS ARE TYPED, NOT FOUR HOLES. `CAST_SLOTS` is passive / tactical / tactical / ultimate,
 * mirroring the authoring target of one passive + two tacticals + one ultimate per rune. A held
 * stance behaves nothing like a signature, so a slot only offers moves of its own tier.
 *
 * ★ AN UNBUILT MOVE IS SHOWN AND SAYS SO. `cast.ts`'s honesty rule: a canon move the sim cannot run
 * is archetype 'unbuilt' WITH a reason, never a silent no-op. Hiding those would make the book look
 * smaller than canon; binding one without a word would read as "casting is broken". So they are
 * listed, dimmed, bindable, and carry their reason.
 */
function LoadoutTab() {
  const [owned] = useState(() => loadRuneInventory().owned)
  // The book is read ONCE per mount alongside the runes: both are the keeper's identity as of the
  // moment this panel opened, and a slot list that re-derived mid-interaction would change its
  // options under the cursor.
  const [book] = useState(() => keeperBook(owned))
  const [slots, setSlots] = useState<Loadout>(() => loadLoadout(owned, book))
  const [picking, setPicking] = useState<number | null>(null)

  const bind = (slot: number, moveId: string | null) => {
    const next = setSlot(owned, slots, slot, moveId, book)
    setSlots(next)
    saveLoadout(next)
    setPicking(null)
  }

  if (owned.length === 0) {
    return <TabEmpty>No runes, so no moves to bring. A keeper is born with their first.</TabEmpty>
  }

  return (
    <div className="flex flex-col gap-1.5">
      {CAST_SLOTS.map((kind, i) => {
        const bound = slots[i] ?? null
        const spec = bound ? castForMove(bound) : null
        const open = picking === i
        const options = eligibleMoves(owned, kind, book)
        return (
          <div key={i} className="rounded border border-white/10 bg-white/[0.03]">
            <button type="button" onPointerDown={() => setPicking(open ? null : i)}
                    className="flex w-full items-center gap-2.5 px-3 py-2 text-left">
              <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded border
                               border-white/20 text-[10px] font-bold text-white/60">
                {CAST_KEYS[i].toUpperCase()}
              </span>
              <span className="w-[68px] shrink-0 text-[9px] uppercase tracking-[0.14em] text-white/30">{kind}</span>
              <span className={`text-[12px] ${spec ? (isBuilt(bound) ? 'text-amber-200/90' : 'text-white/40') : 'text-white/25'}`}>
                {spec ? spec.label : '— empty —'}
              </span>
              {spec && !isBuilt(bound) && (
                <span className="text-[9px] uppercase tracking-[0.14em] text-amber-200/40">unbuilt</span>
              )}
              <span className="ml-auto text-[10px] text-white/25">{open ? '▴' : '▾'}</span>
            </button>
            {open && (
              <div className="border-t border-white/10 px-2 py-1.5">
                {options.length === 0 ? (
                  <div className="px-1 py-1 text-[10px] text-white/30">
                    Your runes open no {kind} yet.
                  </div>
                ) : (
                  <>
                    {options.map(m => {
                      const built = isBuilt(m.id)
                      return (
                        <button key={m.id} type="button" onPointerDown={() => bind(i, m.id)}
                                className="block w-full rounded px-2 py-1 text-left hover:bg-white/[0.06]">
                          <span className="flex items-baseline gap-2">
                            <span className={`text-[11px] ${built ? 'text-white/75' : 'text-white/35'}`}>{m.name}</span>
                            {bound === m.id && <span className="text-[9px] text-amber-200/60">bound</span>}
                            {!built && (
                              <span className="text-[9px] text-white/25">{castForMove(m.id).why}</span>
                            )}
                          </span>
                        </button>
                      )
                    })}
                    {bound && (
                      <button type="button" onPointerDown={() => bind(i, null)}
                              className="mt-0.5 block w-full rounded px-2 py-1 text-left text-[10px]
                                         text-white/30 hover:bg-white/[0.06]">
                        leave this slot empty
                      </button>
                    )}
                  </>
                )}
              </div>
            )}
          </div>
        )
      })}
      {/* ★ SAY WHERE THIS TAKES EFFECT. Casting runs in play3d, not in this world — `castForMove` is
          imported by exactly one component and it is not this one. A chooser that silently governs
          nothing here is the unwired dial this repo keeps paying for, so the panel states its own
          reach rather than letting a keeper infer it from a fight that never casts. */}
      <div className="mt-1 text-[10px] leading-relaxed text-white/25">
        Saved to your keeper. Casting itself does not run in this world yet — these binds take effect
        where the cast layer lives, until it is ported here (#294).
      </div>
    </div>
  )
}

function BagPanel({ inv, chest, tick, sel, dragFrom, setDragFrom, onMove, onSplit, onQuick, onClose,
                   tools, skills, party }: {
  inv: React.RefObject<Inventory>
  chest: OpenChest | null
  tick: number
  sel: number
  dragFrom: Lift | null
  setDragFrom: (r: Lift | null) => void
  onMove: (from: SlotRef, to: SlotRef) => void
  onSplit: (from: SlotRef, to: SlotRef, mode: 'half' | 'one') => void
  onQuick: (r: SlotRef) => void
  onClose: () => void
  tools: React.RefObject<EquippedTools>
  skills: React.RefObject<SkillSet>
  party: React.RefObject<Spirit[]>
}) {
  // Which screen is open resets to the satchel on every open, deliberately: `I` is muscle-memory
  // for "my bag", and a key that sometimes opens the grimoire because that is where you were last
  // is a key that has to be looked at before it is pressed.
  const [tab, setTab] = useState<KeeperTab>('satchel')
  const bag = inv.current?.slots ?? []
  const slotKey = (r: SlotRef) => `${r.g}${r.i}`

  /**
   * The press that has not been released yet. A REF, not state: it changes on every pointermove and
   * re-rendering the whole panel per mouse-pixel would drop frames on a 16-slot grid, and nothing on
   * screen depends on it until the drag actually starts (which does set state, once).
   */
  const drag = useRef<{
    from: SlotRef; mode: 'whole' | 'one'; x: number; y: number
    moved: boolean; visited: Set<string>
  } | null>(null)
  /** The slot under the pointer, or null when it is over none — kept by enter/leave on each cell. */
  const hover = useRef<SlotRef | null>(null)

  /**
   * The parent's callbacks, read through a ref by the window listeners below.
   *
   * ⚠ `onMove`/`onSplit` are inline arrows on the parent, so they are NEW every render — putting
   * them in the effect's deps would tear down and re-add a window listener on every inventory tick,
   * i.e. potentially mid-drag. One ref, one subscription, always the current functions.
   */
  const api = useRef({ onMove, onSplit, setDragFrom })
  api.current = { onMove, onSplit, setDragFrom }

  /**
   * ── ★ THE POINTER OWNS THE WHOLE INTERACTION (2026-08-11, Alex: "no drag to move yet i see") ───
   * Press, move, release — one state machine, rather than `click` and `contextmenu` handlers with
   * pointer handlers layered beside them. Two reasons, and the second is the one that would have
   * bitten:
   *
   * ★ `contextmenu` FIRES AT DIFFERENT TIMES ON DIFFERENT PLATFORMS — on mousedown under X11 and
   * Mac, on mouseup under Windows. A right-DRAG would therefore have fired the right-CLICK verb
   * before the drag began on some of Alex's machines and not others, which is a bug that reproduces
   * on one desk and not the next. Deriving both verbs from pointerdown/up instead makes the
   * platform's menu timing irrelevant; `contextmenu` now does nothing but `preventDefault`.
   *
   * ★ A drag ends over a DIFFERENT element than it began on, and `click` only fires on the common
   * ancestor of the two — so a drag between slots fires no click at all while a drag that happens to
   * end where it started does. Suppressing that inconsistency is more code than not relying on it.
   *
   * Keyboard still comes in through `onClick`, gated on `detail === 0` (a real pointer click always
   * carries a click count, an Enter/Space activation does not) — losing keyboard access to the bag
   * to gain a mouse gesture would be a bad trade.
   */
  useEffect(() => {
    const move = (e: PointerEvent) => {
      const d = drag.current
      if (!d || d.moved) return
      // Manhattan distance, not Euclidean: this is a "did the hand move" threshold, not a
      // measurement, and a square deadzone is the honest shape of that question.
      if (Math.abs(e.clientX - d.x) + Math.abs(e.clientY - d.y) < DRAG_SLOP) return
      d.moved = true
      api.current.setDragFrom({ ...d.from, mode: d.mode })
    }
    const up = () => {
      const d = drag.current
      drag.current = null
      if (!d) return
      // ★ A PRESS THAT NEVER MOVED IS A CLICK, and the click verbs live here too so that the two
      // gestures cannot disagree about what a right button means.
      if (!d.moved) { api.current.setDragFrom({ ...d.from, mode: d.mode === 'one' ? 'half' : 'whole' }); return }
      const to = hover.current
      // A sprinkle already dropped its items on the way across; releasing just ends it. A whole-stack
      // drag lands here, and releasing over nothing (outside the grid) cancels rather than guessing.
      if (d.mode === 'whole' && to && slotKey(to) !== slotKey(d.from)) api.current.onMove(d.from, to)
      api.current.setDragFrom(null)
    }
    // `pointercancel` matters on touch: a scroll or a system gesture steals the pointer and no
    // pointerup ever arrives, which would leave the panel permanently mid-drag.
    const cancel = () => { drag.current = null; api.current.setDragFrom(null) }
    window.addEventListener('pointermove', move)
    window.addEventListener('pointerup', up)
    window.addEventListener('pointercancel', cancel)
    return () => {
      window.removeEventListener('pointermove', move)
      window.removeEventListener('pointerup', up)
      window.removeEventListener('pointercancel', cancel)
    }
  }, [])

  const cell = (ref: SlotRef) => {
    const st = (ref.g === 'bag' ? bag : chest?.slots ?? [])[ref.i]
    const lifted = dragFrom?.g === ref.g && dragFrom.i === ref.i
    return (
      <button key={slotKey(ref)} type="button"
        /**
         * Press. With a lift already up this IS the place, and it happens on the way DOWN — a
         * placement that waited for the release would feel like the panel was thinking about it.
         * With nothing lifted it only arms a drag; whether that press was a click or a drag is not
         * knowable yet, and guessing here is what forces the two paths apart.
         */
        onPointerDown={(e) => {
          if (e.button !== 0 && e.button !== 2) return
          hover.current = ref
          // Shift short-circuits everything: a shift-press is a quick-move of the slot under it,
          // never a half-placement of whatever happened to be lifted.
          if (e.shiftKey && e.button === 0 && chest) { setDragFrom(null); onQuick(ref); return }
          if (dragFrom !== null) {
            if (lifted) { setDragFrom(null); return }              // press the lit slot to cancel
            if (e.button === 2) { onSplit(dragFrom, ref, 'one'); return }   // deal one, stay lifted
            if (dragFrom.mode === 'half') onSplit(dragFrom, ref, 'half')
            else { onMove(dragFrom, ref); setDragFrom(null) }
            return
          }
          if (!st) return                                          // nothing here to pick up
          drag.current = {
            from: ref, mode: e.button === 2 ? 'one' : 'whole',
            x: e.clientX, y: e.clientY, moved: false, visited: new Set([slotKey(ref)]),
          }
        }}
        /**
         * ★ THE SPRINKLE HAPPENS HERE, ON ENTRY, not on release — dealing one into each slot you
         * cross is the point of the gesture, so the items have to land as you pass. `visited` is
         * what makes it one-per-slot: without it a pointer wobbling inside a slot would pour the
         * whole stack into it, and the source slot is pre-seeded so a sprinkle never feeds itself.
         */
        onPointerEnter={() => {
          hover.current = ref
          const d = drag.current
          if (!d || !d.moved || d.mode !== 'one') return
          if (d.visited.has(slotKey(ref))) return
          d.visited.add(slotKey(ref))
          onSplit(d.from, ref, 'one')
        }}
        onPointerLeave={() => { if (slotKey(hover.current ?? ref) === slotKey(ref)) hover.current = null }}
        // Everything above is driven by the pointer; this exists so Enter/Space still work. A real
        // click carries a click count, a keyboard activation reports 0.
        onClick={(e) => {
          if (e.detail !== 0) return
          if (dragFrom === null) { if (st) setDragFrom({ ...ref, mode: 'whole' }) }
          else if (lifted) setDragFrom(null)
          else if (dragFrom.mode === 'half') onSplit(dragFrom, ref, 'half')
          else { onMove(dragFrom, ref); setDragFrom(null) }
        }}
        // The menu's only job now is to not appear. Its TIMING is why the verbs moved to the
        // pointer; see the state machine above.
        onContextMenu={(e) => e.preventDefault()}
        title={st ? `${itemLabel(st.itemId)} ×${st.count}` : 'empty'}
        // ⚠ `touch-none` is what lets a drag be a drag on a phone — without it the browser claims the
        // gesture as a scroll partway through and the pointer stream just stops.
        className={`relative w-12 h-12 rounded border-2 flex flex-col items-center justify-center
          text-[9px] font-mono transition-colors touch-none select-none
          ${lifted && dragFrom ? LIFT_LOOK[dragFrom.mode]
            : dragFrom !== null ? 'border-white/30 bg-black/50 hover:border-amber-200/70'
            : 'border-white/20 bg-black/40 hover:border-white/40'}`}>
        {st ? (
          <>
            <ItemChip itemId={st.itemId} size={26} />
            <span className="mt-0.5 tabular-nums text-white/80">{st.count}</span>
            {/* How many the lift will actually take, stated rather than left to be counted — "half
                of 7" is 4 here and 3 elsewhere, and a player should not have to find out by doing
                it. A whole lift needs no badge: the count under the icon already says it. */}
            {lifted && dragFrom && dragFrom.mode !== 'whole' && (
              <span className={`absolute -top-1.5 -right-1.5 rounded px-1
                                text-[9px] font-bold tabular-nums text-black ${LIFT_BADGE[dragFrom.mode]}`}>
                {dragFrom.mode === 'half' ? halfOf(st.count) : 1}
              </span>
            )}
          </>
        ) : <span className="text-white/15">·</span>}
      </button>
    )
  }
  /**
   * ── ★ THE HINT STILL RESERVES ITS OWN LARGEST BOX (2026-08-11; re-justified 2026-08-12) ───────
   * Originally: this panel was shrink-to-fit, so its WIDTH was the widest thing inside it — this
   * sentence, not the grid of slots. Swapping in a shorter hint resized the whole panel the instant
   * you lifted a stack, moving every slot out from under the cursor mid-action. A menu that changes
   * size while you are aiming at it is the interface flinching away from the click.
   *
   * `KeeperFrame` now fixes the width, so that original reason is gone — and the trick STAYS, for a
   * new one. The hint sits below the frame's fixed-height body, outside the scroll, so it is the one
   * piece of content that can still change the panel's size: a longer sentence wraps to a second
   * line and moves everything above it. Width was the old axis; height is the live one.
   *
   * So EVERY hint is always in the DOM, stacked in one grid cell; only the live one is visible. The
   * container measures the largest, permanently, and no swap can move anything. `invisible` (not
   * `hidden`) is the whole trick — it keeps the box.
   *
   * ★ Self-maintaining on purpose: a future hint cannot reintroduce the jump without also being in
   * this list, because the list IS the layout.
   */
  const hint = (
    <span className="grid text-[11px] text-white/40">
      {([
        [`drag a stack to move it · right-drag deals one per slot${chest ? ' · shift-click sends it across' : ''} · I closes`, dragFrom === null],
        ['click a slot to place · right-click deals one and keeps hold · click again to cancel', dragFrom?.mode === 'whole'],
        ['click a slot to place half · right-click deals one instead · click again to cancel', dragFrom?.mode === 'half'],
        ['release over a slot to leave one there · drag on to keep dealing', dragFrom?.mode === 'one'],
      ] as const).map(([text, live]) => (
        <span key={text} style={{ gridArea: '1 / 1' }}
              className={live ? '' : 'invisible'} aria-hidden={!live}>{text}</span>
      ))}
    </span>
  )

  const satchel = (
    <>
      {/* The chest's own grid, above the bag and separated by a rule — the same relationship the
          satchel and the hotbar already have, one level out. */}
      {chest && (
        <div className="mb-4 border-b border-white/10 pb-4">
          <div className="mb-1.5 text-[10px] uppercase tracking-[0.16em] text-white/35">
            in the chest · {chest.x} {chest.y} {chest.z}
          </div>
          <div className="grid gap-1.5" style={{ gridTemplateColumns: `repeat(${CHEST_COLS}, minmax(0, 1fr))` }}>
            {Array.from({ length: CHEST_SLOTS }, (_, k) => cell({ g: 'chest', i: k }))}
          </div>
        </div>
      )}
      {/* Satchel: slots 8-23, the 16 that are not the bar. */}
      <div className="grid grid-cols-8 gap-1.5">
        {Array.from({ length: 16 }, (_, k) => cell({ g: 'bag', i: k + 8 }))}
      </div>
      {/* The bar itself, set apart by a rule so its slots read as the SAME grid, not a copy. */}
      <div className="mt-4 border-t border-white/10 pt-3">
        <div className="mb-1.5 text-[10px] uppercase tracking-[0.16em] text-white/35">Hotbar · 1-8</div>
        <div className="grid grid-cols-8 gap-1.5">
          {Array.from({ length: 8 }, (_, k) => (
            <div key={k} className={sel === k ? 'ring-2 ring-amber-300/70 rounded' : ''}>{cell({ g: 'bag', i: k })}</div>
          ))}
        </div>
      </div>
    </>
  )

  /**
   * ★ A CHEST IS A MODE, NOT A TAB. Opening a chest is a focused two-container interaction; the
   * other four screens have nothing to do with it, and a rail sitting above an open chest invites a
   * click that would strand a lifted stack between containers. So the chest takes the frame's
   * `title` path, which replaces the rail entirely, and the bag stays the only thing on screen.
   */
  if (chest) {
    return (
      <KeeperFrame tab="satchel" setTab={() => {}} title="Chest" hint={hint} onClose={onClose}>
        {satchel}
      </KeeperFrame>
    )
  }

  return (
    <KeeperFrame tab={tab} setTab={setTab} onClose={onClose}
                 hint={tab === 'satchel' ? hint : undefined}>
      {tab === 'satchel' && satchel}
      {tab === 'runes' && <RunesTab />}
      {tab === 'grimoire' && <GrimoireTab party={party} />}
      {tab === 'tools' && <ToolsTab tools={tools} skills={skills} />}
      {tab === 'loadout' && <LoadoutTab />}
    </KeeperFrame>
  )
}

/**
 * The tool arc — four round sockets curving up-right off the hotbar's right end (Alex's whiteboard,
 * 2026-08-07; replaces the rectangular `ToolGauge` cards shipped hours earlier and rejected as
 * "three steps backwards"). Zero-size and `absolute` so it never affects the hotbar's own layout;
 * `left-full` anchors it to the `relative` hotbar wrapper's right edge regardless of bar width.
 *
 * The radius is a CSS custom property (`--tool-arc-r`, `clamp()`) rather than a JS media-query
 * state, so it shrinks continuously on narrow screens with no resize listener — `ToolSocket` reads
 * it back through `calc(var(--tool-arc-r) * <cos|sin>)`, where cos/sin are real `Math` output baked
 * in at render, not hand-eyeballed numbers.
 */
function ToolArc({ activeTool, tools, skills }: {
  activeTool: string | null
  tools: React.RefObject<EquippedTools>
  skills: React.RefObject<SkillSet>
}) {
  // Degrees off the horizontal. Alex's taste pass 2026-08-07: arc MIRRORED (fan opens up-and-
  // RIGHT, away from the bar, instead of curling back over it), gaps widened, whole cluster +25%.
  const ANGLES = [6, 34, 62, 90]
  return (
    <div
      className="absolute left-full bottom-0 ml-3 h-0 w-0 pointer-events-none"
      style={{ '--tool-arc-r': 'clamp(60px, 16vw, 105px)' } as React.CSSProperties}
    >
      {TOOL_FAMILIES.map((family, i) => (
        <ToolSocket key={family} family={family} angleDeg={ANGLES[i]}
          active={activeTool === family} tools={tools} skills={skills} />
      ))}
    </div>
  )
}

/**
 * A single round socket: family glyph, XP progress ring around the rim, level badge, 1-3 tier dots.
 * Read-only — nothing here is clickable, which is the point (see the TOOL ARC comment). Sized
 * 44px, shrinking to 38px under 640px (`max-[639px]:`) alongside the arc's own radius shrink, so
 * the whole cluster stays on-screen on a phone instead of clipping off the right edge.
 */
function ToolSocket({ family, angleDeg, active, tools, skills }: {
  family: 'forestry' | 'prospecting' | 'rinning' | 'farming'
  angleDeg: number
  active: boolean
  tools: React.RefObject<EquippedTools>
  skills: React.RefObject<SkillSet>
}) {
  const held = getEquippedTool(tools.current!, family)
  const def = held ? getToolDef(held) : undefined
  const tier = def?.tier ?? 0
  const basic = def?.basic ?? false
  const sk = skills.current![family]
  const xpPct = Math.min(1, sk.xp / Math.max(1, xpForSkillLevel(sk.level)))
  const rad = (angleDeg * Math.PI) / 180
  // Mirrored sweep: x = r·(1 − cos θ), so the fan steps RIGHT as it rises instead of curling
  // back over the bar (Alex taste pass 2026-08-07).
  const cosm = (1 - Math.cos(rad)).toFixed(4)
  const sin = Math.sin(rad).toFixed(4)
  const RING_R = 21
  const RING_C = 2 * Math.PI * RING_R
  return (
    <div
      className="absolute w-14 h-14 max-[639px]:w-[48px] max-[639px]:h-[48px] transition-opacity"
      style={{
        left: `calc(var(--tool-arc-r) * ${cosm})`,
        bottom: `calc(var(--tool-arc-r) * ${sin})`,
      }}
    >
      {/* ★ THE DIM GOES ON THE CONTENT, NEVER ON THE PLATE (2026-08-11). This was one
          `opacity: active ? 1 : 0.4` on the wrapper, which dimmed the socket's own backing along
          with everything in it: `bg-black/45` × 0.4 is an 18% film, so over a lit grass field the
          plate disappeared and four faint rings were left floating on the world. In the first
          headless world shot Alex could not tell what they were — "an odd cluster of translucent
          green shapes with number labels." The inactive state still has to read as inactive, but
          "text never sits raw on a scene" outranks it: the plate stays opaque and the CONTENT
          carries the state contrast. */}
      <div className={`relative w-full h-full rounded-full border
        ${active ? 'border-amber-300/80 bg-black/70 shadow-[0_0_8px_2px_rgba(252,211,77,0.4)]' : 'border-white/25 bg-black/60'}`}>
        <div className={`absolute inset-0 transition-opacity ${active ? '' : 'opacity-65'}`}>
        {/* XP ring, rotated so 0% starts at 12 o'clock */}
        <svg viewBox="0 0 48 48" className="absolute inset-0 w-full h-full -rotate-90">
          <circle cx="24" cy="24" r={RING_R} fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth="2" />
          <circle cx="24" cy="24" r={RING_R} fill="none" stroke={active ? '#6ee7b7' : 'rgba(110,231,183,0.55)'}
            strokeWidth="2" strokeLinecap="round" strokeDasharray={RING_C}
            strokeDashoffset={RING_C * (1 - xpPct)} />
        </svg>
        {/* Family glyph — placeholder line art, Alex repaints later. */}
        <svg viewBox="0 0 24 24" className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-[60%] w-4 h-4 text-white/85"
          fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
          <ToolGlyph family={family} />
        </svg>
        {/* Equipped tier as 1-3 filled dots; the never-breaking basic tool reads as ONE HOLLOW dot —
            it works, but it is not an upgrade. No tool at all (farming has no basic) is all hollow. */}
        <div className="absolute bottom-1 left-1/2 -translate-x-1/2 flex gap-0.5">
          {[0, 1, 2].map((i) => {
            const filled = !basic && i < tier
            const hollowBasic = basic && i === 0
            return (
              <span key={i} className={`w-1 h-1 rounded-full border ${
                filled ? 'bg-amber-200 border-amber-200' : hollowBasic ? 'border-white/60' : 'border-white/15'}`} />
            )
          })}
        </div>
        {/* Level badge, tabular-nums so it doesn't jitter as it climbs. */}
        <div className="absolute -bottom-1 -right-1 min-w-[15px] h-[15px] px-[3px] rounded-full bg-black/80 border border-white/25
          text-[9px] leading-[14px] text-center text-white/90 font-mono tabular-nums">
          {sk.level}
        </div>
        </div>
      </div>
    </div>
  )
}

/** Placeholder line-glyph per family — canon mapping (blades→forestry, spikes→prospecting,
 *  rinsticks→rinning, spades→farming) from `engine/tools.ts`, drawn as a simple angled stroke. */
function ToolGlyph({ family }: { family: 'forestry' | 'prospecting' | 'rinning' | 'farming' }) {
  switch (family) {
    case 'forestry': // blade — angled machete stroke
      return <>
        <path d="M5 19 L16 8" />
        <path d="M16 8 L20 4" />
        <path d="M5 19 L8.5 19" />
      </>
    case 'prospecting': // spike — pick shape
      return <>
        <path d="M12 3c-3.3 0-5.5 2.2-5.5 5 0 2 1.6 3.3 3 3.3" />
        <path d="M9.5 11.3 15 20" />
      </>
    case 'rinning': // rinstick — rod + line
      return <>
        <path d="M6 21 14 4" />
        <path d="M14 4c3.5 2 3.8 7.5 1.6 12" />
        <circle cx="15.6" cy="16" r="1" fill="currentColor" stroke="none" />
      </>
    case 'farming': // spade — handle + shovel
      return <>
        <path d="M12 3v11" />
        <path d="M8 14h8l-2 7h-4l-2-7Z" />
      </>
  }
}

// Ground cover is walked THROUGH, blocks no light, and stops no fence arm — it is scenery you can
// also pick up, not geometry. Everything downstream of `isSolid` (collision, the light field's
// opacity, piece connection) inherits that from this one line.
// ⚠ SAPLINGS JOIN GROUND COVER HERE (2026-08-13). A seedling drawn as a small cross must not be a
// full solid cell you bump into and cannot see — that is the invisible-wall failure one size down.
// It also stops a sapling blocking light, which matters more than it sounds: `blockedBy` refuses to
// grow a tree without open sky, and a sapling that shadowed ITSELF would never come up.
const SOLID_EXCEPT = new Set<number>([
  AIR, MAT.WATER, MAT.TUFT, MAT.TALL_GRASS, MAT.FLOWER,
  MAT.SAPLING_GOLDWOOD, MAT.SAPLING_SHIMMEROAK, MAT.SAPLING_STARWILLOW, MAT.SAPLING_DAWNWOOD,
])
// A slab is SOLID — it just occupies half the cell. Collision asks `solidProbe`, which reports
// CELL_HALF for it; everything else (light, fence arms, piece placement) wants "yes, solid".
const isSolid = (m: number) => !SOLID_EXCEPT.has(baseOf(m))

function World({ inv, toolTier, toolSkill, vitals, mana, selItem, selSlot, weaponDrawn, weaponIdx, onAmmo, onStats, onPerf, onSay, runeTick, onPos, onLook, onInvChange, worker, incoming, inflight, settings, build, pieceIdx, rot, tools, skills, onSkill, onLevel, onTool, tutorial, onQuestEvent, onNearGreg, onNearTable, cmdOut, mistLedger, onNearMist, sparring, pot, onOpenChest, onOpenStation, uiOpen }: {
  inv: React.RefObject<Inventory>
  toolTier: React.RefObject<number>
  toolSkill: React.RefObject<BlockSkill>
  selItem: string | null
  /** Which hotbar slot `selItem` came from — the drop verb needs the SLOT, not just the id. */
  selSlot: number
  /** Weapon out. Mining and placing are locked while true. Named `weaponDrawn`, not
   *  `drawn`: this component already has a `drawn` ref holding the rendered mesh map. */
  weaponDrawn: boolean
  /** Index into WEAPONS. Q cycles it; the parent owns it so the HUD can name the gun. */
  weaponIdx: number
  /** Rounds left, pushed up for the HUD. Called on fire and on reload completion. */
  onAmmo: (n: number) => void
  onStats: (s: string) => void
  /** One window of the frame meter, ~4x a second and only while `settings.showFps` is on. */
  onPerf: (p: PerfSample) => void
  /** Addressed to the PLAYER — held long enough to read. `onStats` is plumbing and gets clobbered
   *  every 10 frames by the biome line; see the SAY CHANNEL note on VoxelWorld. */
  onSay: (s: string) => void
  /** Bumped when the rune inventory changed under us — re-resolve the loadout, no reload. */
  runeTick: number
  /** `yaw` is a map-marker CANVAS ROTATION (`screenHeading`), not a world yaw. */
  onPos: (p: THREE.Vector3, yaw: number) => void
  onLook: (l: { name: string; progress: number; refused: boolean } | null) => void
  onInvChange: () => void
  worker: React.RefObject<Worker | null>
  incoming: React.RefObject<{ cx: number; cz: number; voxels: Uint16Array; oIdx?: Uint32Array; oMat?: Uint16Array }[]>
  inflight: React.RefObject<number>
  settings: VoxelSettings
  build: boolean
  pieceIdx: number
  rot: Rotation
  tools: React.RefObject<EquippedTools>
  skills: React.RefObject<SkillSet>
  onSkill: (s: { id: string; level: number; xp: number; next: number } | null) => void
  onLevel: (s: string | null) => void
  /** Which family is actively mining, or null — fires only on change (see the ref beside the
   *  mining block), so the gauges can glow without a per-frame re-render. */
  onTool: (family: string | null) => void
  /** Owned by the parent (like `inv`/`tools`) so a mutation here is visible there with no prop
   *  round-trip. World only READS `.stage` — every write to it happens in the parent
   *  (`advanceTutorial`/`closeDialogue`), which is also what owns `saveTutorial`. */
  tutorial: React.RefObject<TutorialState>
  /** The two tutorial facts World alone can see — a block breaking under the pick, a block landing
   *  under the cursor. Crafting is detected in the parent's `doCraft` instead. */
  onQuestEvent: (event: 'cut' | 'light') => void
  /** Fires only on change, same dedup shape as `onTool`. */
  onNearGreg: (near: boolean) => void
  /** The withdrawal ledger, by ref — the pass reads it, the spar's end writes it. */
  mistLedger: React.MutableRefObject<MistLedger>
  onNearMist: (r: Resident | null) => void
  /** The arena owns the screen while true; the world keeps streaming but stops reporting prompts. */
  sparring: boolean
  /** Near a placed crafting table — the parent turns this into recipes.ts's `Station`. */
  onNearTable: (near: boolean) => void
  /** The console's world-verbs, filled on mount — only World can move the walker safely. */
  pot: { clock: () => PotClock; save: () => void; gain: (s: Spirit) => void }
  /**
   * Right-clicking a chest hands the whole thing upward: its cell, the LIVE contents array, and the
   * one call that marks its column dirty. World does not open a panel of its own — the bag, the
   * bench and the chest are one surface in the parent, so they cannot disagree about what a move
   * means or which of them owns the cursor.
   */
  onOpenChest: (c: OpenChest) => void
  onOpenStation: (s: OpenStation) => void
  /**
   * Is a cursor surface up? A REF, not a boolean prop, on purpose: opening the bag must not
   * re-render the whole scene, and the only readers are a listener and the frame loop — both of
   * which want the LIVE value rather than the one captured at their last render.
   */
  uiOpen: React.RefObject<boolean>
  /** The keeper's two bars. Written here, polled by the HUD. */
  vitals: React.RefObject<Vitals>
  /** The cast pool. `regen` is per second, derived from the Mana skill. */
  mana: React.RefObject<{ cur: number; max: number; regen: number }>
  cmdOut: React.RefObject<{ tp: (x: number, z: number) => string; pos: () => { x: number; z: number } } | null>
}) {
  const { camera } = useThree()
  const group = useRef<THREE.Group>(null)
  const highlight = useRef<THREE.LineSegments>(null)
  // ★ THE TEXTURE ARRAY, WIRED INTO THE MAIN WORLD (texture lane handoff, 406d492).
  //
  // One material for the whole world and ONE tile array — both keyed to `tileSize` so changing it
  // rebuilds exactly one texture rather than one per chunk. `sampler2DArray` is what makes this free
  // for the mesher: each material is its own LAYER, so RepeatWrapping tiles across a merged quad
  // with no bleed. An atlas cannot, and its usual escape (one quad per block) throws away the entire
  // greedy win — 67,629 quads would go back to 244,685.
  //
  // The flat vertex-colour material stays available and is NOT dead code: it is the control in the
  // A/B, and it is the fallback if tile generation ever throws.
  const { gl } = useThree()
  const tiles = useMemo(() => {
    try { return makeTileArray(settings.tileSize, gl) } catch { return null }
  }, [settings.tileSize, gl])
  const flatMaterial = useMemo(() => createVoxelMaterial(), [])
  const textured = useMemo(() => (tiles ? createTexturedVoxelMaterial(tiles) : null), [tiles])
  const material = textured?.material ?? flatMaterial
  // The world's ONE transparent pass — see mesh-bridge.ts. Shared instance, same rule as above.
  const waterMaterial = useMemo(() => createWaterMaterial(tiles, layerOf(MAT.WATER, 0)), [tiles])

  /**
   * ── ★ THE CANOPY MATERIAL (2026-08-12) ────────────────────────────────────────────────────────
   * One extra compiled program for the whole world, which is what the per-chunk-material rule
   * actually permits — it forbids a program per CHUNK, not a second pass (see attrs.ts on water).
   *
   * `alphaTest` not `transparent`: a cutout writes depth and needs no sorting, so a canopy composes
   * correctly with itself from any angle. Marking leaves transparent instead would drag thousands
   * of quads into the blended pass and make the tree draw order-dependent — the exact bug water is
   * split out to avoid, re-created on a much bigger surface.
   *
   * `DoubleSide` is what lets the mesher emit ONE quad per plane instead of two: three flips the
   * normal for back faces, so a cross is lit from both sides for half the geometry.
   */
  const leafMaterial = useMemo(() => {
    const tex = new THREE.DataTexture(leafPixels(16), 16, 16)
    tex.magFilter = THREE.NearestFilter
    tex.minFilter = THREE.NearestFilter
    tex.colorSpace = THREE.SRGBColorSpace
    tex.needsUpdate = true
    return new THREE.MeshLambertMaterial({
      map: tex,
      vertexColors: true,        // species tint x canopy-depth shade, straight from the mesher
      alphaTest: 0.5,
      side: THREE.DoubleSide,
    })
  }, [])
  useEffect(() => () => { leafMaterial.map?.dispose(); leafMaterial.dispose() }, [leafMaterial])

  // ★ A VALUE WRITE, NOT A REBUILD. Both shading paths live in the one compiled program and are
  // selected by a uniform, so changing style costs nothing and creates no second shader program.
  useEffect(() => {
    applySettings(flatMaterial, settings)
    textured?.setCartoon({
      uCartoon: settings.style === 'cartoon' ? 1 : 0,
      uToon: settings.toon,
      uOutline: settings.outline,
      uFaceShading: settings.faceShading,
      uShadowLift: settings.shadowLift,
    })
  }, [flatMaterial, textured, settings])
  const scratch = useMemo(() => createMeshScratch(SECTION), [])
  const cols = useRef(new Map<string, Column>())
  const drawn = useRef(new Map<string, THREE.Mesh>())
  const breaking = useRef<BreakState | null>(null)
  // ★ THE GAUGE SIGNAL, DEDUPED. `onTool` is a `setState` on the parent — calling it every frame
  // while a swing lands would re-render the HUD 60x/sec for a value that changed once. This ref
  // holds the last value SENT (not the last value computed), so the callback only fires on change.
  const lastTool = useRef<string | null>(null)
  const drops = useRef<Drop[]>([])
  const dropMeshes = useRef(new Map<number, THREE.Mesh>())
  /**
   * ★ ONE GEOMETRY AND A MATERIAL CACHE FOR EVERY DROP — NOT ONE EACH.
   *
   * The first version built `new THREE.BoxGeometry` AND `new THREE.MeshLambertMaterial` per dropped
   * item. A material is a SHADER PROGRAM; a few hundred drops is a few hundred programs plus a few
   * hundred buffers, and Chrome responds by losing the WebGL context and then BLOCKING the page
   * from creating another one: "Web page caused context loss and was blocked", after which the
   * whole canvas is black and no amount of reloading helps until the tab is closed.
   *
   * This is the exact failure `mesh-bridge.ts` warns about for chunk meshes — "a material per chunk
   * is a shader program per chunk, and that is how a voxel renderer dies" — and I wrote that
   * warning and then did it anyway in the drop path. Geometry is shared outright; materials are
   * cached by colour, so the ceiling is the number of distinct block colours, not the number of
   * items on the floor.
   */
  const dropGeo = useMemo(() => new THREE.BoxGeometry(0.28, 0.28, 0.28), [])
  const dropMats = useRef(new Map<number, THREE.Material>())
  const highlightGeo = useMemo(() => new THREE.EdgesGeometry(new THREE.BoxGeometry(1.002, 1.002, 1.002)), [])
  const pieces = useMemo(() => createPieceRenderer(), [])
  // Greg — built once, positioned once. Static NPC, no per-frame update beyond the aim check
  // below (which reads GREG_X/GREG_Z/GREG_Y, not the mesh, so the mesh itself never moves).
  const greg = useMemo(() => {
    const g = createGregMesh()
    g.group.position.set(GREG_CX, GREG_Y, GREG_CZ)
    return g
  }, [])
  // Hot-spring steam (2026-08-08) — sleeps everywhere but the Springs; see steam.ts.
  const steam = useMemo(() => createSteamPoints(SEED), [])
  // Mist patches (2026-08-09) — the lying mist plus the presence standing in it; see mist-pass.ts.
  // Sleeps everywhere but inside a patch's reach, the same way steam sleeps outside the Springs.
  const mist = useMemo(() => createMistPass(SEED, mistLedger.current), [mistLedger])
  const lastNearMist = useRef<string | null>(null)
  /** The ledger the pass currently holds. `recordWithdrawal` returns a NEW object, so an identity
   *  compare is enough to notice a spar ended and hand the pass the updated one — without which
   *  the spirit you just sparred would keep standing there until the world reloaded. */
  const ledgerSeen = useRef<MistLedger | null>(null)
  // Ground cover (2026-08-08) — flora.ts selects, the live-voxel probe verifies, four draws total.
  const flora = useMemo(() => createFloraRenderer(), [])
  /** Set whenever loaded ground changes (adopt, edit, evict); the frame loop syncs once quiet. */
  const floraDirty = useRef(true)
  /** Next wall-clock ms at which planted pots are checked for coming due. */
  const potTick = useRef(0)
  /** Next wall-clock ms at which planted saplings are checked for coming up. */
  const saplingTick = useRef(0)
  /**
   * When each planted sapling went in — the one thing a material id cannot carry (see sapling.ts).
   *
   * ⚠ Lives HERE, in `World`, and not beside the pot clock in the outer component. The pot's clock
   * is passed down as a prop because the outer component owns the party a bloom hands a spirit to;
   * a sapling has no such consumer. Its only readers are the growth tick and the place branch, both
   * of which are in this scope — passing it through a prop would be plumbing that buys nothing.
   */
  const saplingClock = useRef<SaplingClock>({})
  const SAPLING_KEY = `voxel3d:saplings:${SEED}`
  const saveSaplings = useCallback(() => {
    try { localStorage.setItem(SAPLING_KEY, JSON.stringify(saplingClock.current)) } catch { /* full disk */ }
  }, [SAPLING_KEY])
  useEffect(() => {
    try { saplingClock.current = JSON.parse(localStorage.getItem(SAPLING_KEY) ?? '{}') } catch { saplingClock.current = {} }
  }, [SAPLING_KEY])
  const lastNearGreg = useRef(false)
  const lastNearTable = useRef(false)
  // The gate: built (sealed or open, matching whatever `tutorial.current.stage` says at the moment
  // its columns arrive) exactly once, then opened exactly once more if the quest completes later.
  const gateBuilt = useRef(false)
  const gateOpened = useRef(false)
  // Placements are grouped by the column that OWNS them (the one containing the piece origin) —
  // the same ownership rule trees and carvers use, so a piece straddling a border saves once.
  const placements = useRef<(Placement & { gen?: string })[]>([])
  /** Tombstones per column: gen-ids of generated pieces the player deconstructed. Saved. */
  const genRemovedByCol = useRef(new Map<string, string[]>())
  /**
   * ── ★ CHEST CONTENTS, PER COLUMN (2026-08-11) ────────────────────────────────────────────────
   * `colKey → { "x,y,z" → slots }`, saved inside that column's record so a chest's block and its
   * contents move as one (see chest.ts's header). Kept in memory across an evict for exactly the
   * reason edits are: the column is regenerable, what you put in the chest is not.
   */
  const chestsByCol = useRef(new Map<string, Record<string, Slots>>())
  /**
   * ── ★ STATION JOBS, PER COLUMN (2026-08-13, the workshop pass) ───────────────────────────────
   * Same shape and same reasoning as `chestsByCol` above: a job holds input the player already
   * paid, so it rides in the block's own record rather than a global sidecar. See save.ts.
   */
  const jobsByCol = useRef(new Map<string, Workshop>())
  const piecesByCol = useRef(new Map<string, Placement[]>())
  const colOf = useCallback((x: number, z: number) => key(Math.floor(x / SECTION), Math.floor(z / SECTION)), [])
  const dropGroup = useRef<THREE.Group>(null)
  const mouse = useRef({ left: false, right: false })
  // Weapon state. Refs, not state: these change per-frame and per-shot, and a re-render per round
  // fired would be a re-render of the whole world at 9 rounds/sec.
  const ammo = useRef(weaponAt(0).clip)
  const reloading = useRef(0)
  const ads = useRef(false)
  const recoil = useRef({ p: 0, y: 0 })
  const frame = useRef(0)
  /** The frame meter's open window: frames and seconds since the last publish, plus the worst
   *  single frame in it. A ref, not state — accumulating in state would re-render per frame. */
  const perfWin = useRef({ frames: 0, time: 0, worst: 0 })
  const requested = useRef(new Set<string>())
  // ★ Edits live here, keyed by column, and are the ONLY thing the world stores. Walking a thousand
  // columns costs zero bytes; a save grows with what you BUILD.
  const edits = useRef(new Map<string, ColumnEdits>())
  const dirtySaves = useRef(new Set<string>())
  /**
   * ── ★ THE STALE-SAVE WARNING FIRES ONCE PER GENERATOR VERSION, NOT ONCE PER PAGE LOAD ────────
   * Alex, 2026-08-13: *"when i refresh the page it keeps saying something about different
   * generator versions."* It did, and it always would have — this was a `useRef(false)`, so the
   * latch died with the page.
   *
   * ★ THE REASON IT NEVER STOPPED is subtler than the latch: `packEdits` stamps the CURRENT version,
   * but a column is only written when it is EDITED. So a column touched weeks ago at v14 stays v14
   * for ever, and every refresh finds it and warns again. The warning was structurally permanent
   * for anyone with old edits — which is everyone who has played.
   *
   * A warning that fires every single load is not a warning, it is furniture. The player reads it
   * once, learns it means nothing, and is then equally blind the day the generator really does move
   * their house. So the acknowledgement is PERSISTED against the version it was given for: told once
   * when the world changes under you, silent afterwards, and told again the next time it changes.
   */
  const staleWarned = useRef<boolean>(false)
  const settled = useRef(false)
  // The walker. Feet-based; the camera is derived from it every frame (feet + eased eye).
  const loco = useRef(createLoco(SPAWN_X + 0.5, columnHeight(SPAWN_X, SPAWN_Z, SEED) + 1, SPAWN_Z + 0.5))

  // ── the console's world-verbs ────────────────────────────────────────────────────────────────
  // tp re-arms the SAME hold-until-solid gate the spawn uses (settled ref) — the destination's
  // columns stream in around the new camera position, and physics waits for real ground instead
  // of dropping the walker through a world that has not generated yet.
  useEffect(() => {
    cmdOut.current = {
      tp: (x: number, z: number) => {
        const lc = loco.current
        const h = columnHeight(x, z, SEED)
        lc.px = x + 0.5; lc.py = h + 1; lc.pz = z + 0.5
        lc.vy = 0; lc.hvx = 0; lc.hvz = 0; lc.airborne = false; lc.stepSmooth = 0
        camera.position.set(lc.px, eyeY(lc), lc.pz)
        settled.current = false
        return `off to ${x}, ${z} (ground ${h}) — the land is catching up`
      },
      pos: () => ({ x: camera.position.x, z: camera.position.z }),
    }
    return () => { cmdOut.current = null }
  }, [cmdOut, camera])

  // ── ★ THE PLAYER PERSISTS (2026-08-08) — spawn where you left off, keep what you carried ────
  // Hydrate once at mount: position, facing, inventory, tools, skills. The settle gate holds
  // physics until real ground streams in under the restored spot — the same hold the spawn and
  // the console's tp already use. The Y is clamped to the CURRENT surface: worldgen is still
  // moving under saves this week (rivers, pads), and a keeper restored into ground would be
  // entombed. The cost is cave positions restoring to the surface — caves barely exist yet.
  useEffect(() => {
    let live = true
    void loadPlayer(SEED).then(p => {
      if (!p || !live) return
      if (p.inv) {
        inv.current = p.inv as Inventory
        // ── ★ A BAG OUTLIVES THE RULES IT WAS FILLED UNDER (2026-08-13) ────────────────────────
        // The building grammar retired `block_stone`, so a save from before it holds an item that
        // nothing places, nothing crafts and nothing names — junk the game cannot explain. Remap it
        // to its successor here, at the one point a save becomes live state.
        //
        // ⚠ REMAP, NEVER DELETE, and never a recipe: see `salvage.ts`'s header. Rock became rubble,
        // so the hour spent quarrying survives the ruling that renamed rock.
        const fixed = salvageItems(inv.current.slots)
        const msg = salvageMessage(fixed.changed)
        if (msg) {
          inv.current.slots = fixed.slots
          // Said out loud rather than done quietly: items changing in your bag while you were not
          // looking is exactly the kind of thing a player should be told, not left to discover.
          onSay(`your bag caught up: ${msg}`)
        }
      }
      // ensureBasicTools over the SAVED set: a future tool family added to the game arrives in
      // an old save as its basic tier instead of as undefined.
      if (p.tools) tools.current = ensureBasicTools(p.tools as EquippedTools)
      if (p.skills) skills.current = p.skills as SkillSet
      const lc = loco.current
      lc.px = p.x; lc.pz = p.z
      lc.py = Math.max(p.y, columnHeight(Math.floor(p.x), Math.floor(p.z), SEED) + 1)
      lc.vy = 0; lc.hvx = 0; lc.hvz = 0; lc.stepSmooth = 0
      camera.position.set(lc.px, eyeY(lc), lc.pz)
      camera.quaternion.setFromEuler(new THREE.Euler(p.rx, p.ry, 0, 'YXZ'))
      settled.current = false
      onInvChange()
    })
    return () => { live = false }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Autosave the keeper: every 5s, on tab-hide, and on unmount — same event pair the column
  // flush trusts (visibilitychange/pagehide; beforeunload is the one that lies on mobile).
  useEffect(() => {
    const eul = new THREE.Euler()
    const snap = (): PlayerSave => {
      eul.setFromQuaternion(camera.quaternion, 'YXZ')
      const lc = loco.current
      return { v: 1, x: lc.px, y: lc.py, z: lc.pz, rx: eul.x, ry: eul.y,
               inv: inv.current, tools: tools.current, skills: skills.current }
    }
    const save = () => { void savePlayer(SEED, snap()) }
    const t = setInterval(save, 5000)
    document.addEventListener('visibilitychange', save)
    window.addEventListener('pagehide', save)
    return () => {
      clearInterval(t); save()
      document.removeEventListener('visibilitychange', save)
      window.removeEventListener('pagehide', save)
    }
  }, [camera])
  // ★ Scratch vectors, allocated ONCE. Four `new THREE.Vector3()` per frame is 240 objects/sec of
  // pure garbage — not a GPU leak, but exactly the GC pressure the mesher and carver were both
  // rewritten to avoid. Same rule, applied to the frame loop instead of the hot inner loop.
  const vAim = useRef(new THREE.Vector3())
  const vFwd = useRef(new THREE.Vector3())
  const vRight = useRef(new THREE.Vector3())
  const vWish = useRef(new THREE.Vector3())
  const UP = useMemo(() => new THREE.Vector3(0, 1, 0), [])
  const keys = useRef<Record<string, boolean>>({})
  const fly = useRef(false)

  useEffect(() => {
    // ⚠ FLY MOVED F → V (2026-08-07). F is now draw/stow, matching play3d's holster key so the two
    // walkers do not disagree about what F means — and draw/stow is a player verb while fly is a
    // debug convenience, so the player verb wins the good key. Caught only because the new binding
    // would have silently toggled BOTH: pressing F would have drawn your weapon and launched you.
    // The INPUT guard mirrors onKey's: touch-typing a console command must not walk the player.
    /**
     * ── ★ A MENU SWALLOWS THE PRESS, NEVER THE RELEASE (2026-08-11, Alex) ────────────────────────
     * With a cursor surface up the world takes no new input: Shift stops crouching the player under
     * the bag, and a mousedown on a slot stops setting `mouse.left` — which the frame loop was
     * reading as "start mining", so clicking around your inventory quietly broke the block you were
     * facing. That one leaves damage behind, and nothing on screen says it happened.
     *
     * ★ BUT THE RELEASE ALWAYS GETS THROUGH, and that asymmetry is the whole fix. Gate keyup as well
     * and a key that was DOWN when the menu opened is stranded `true` forever — you open the bag
     * mid-sprint, close it, and the player walks into a wall with no key left to press that would
     * stop them, because the physical release already happened behind the gate. Down is a request
     * the world may refuse; up is a fact it has to record.
     *
     * The per-frame clear below handles the same case from the other side (held at open time, never
     * released), so the two together mean no input can survive a menu.
     */
    const kd = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement | null)?.tagName === 'INPUT') return
      // The INPUT guard above is about typing; this one is about menus. Both mirror `onKey`'s.
      if (uiOpen.current) return
      keys.current[e.code] = true; if (e.code === 'KeyV') fly.current = !fly.current
      // ★ The cast binds. `pendingCast` rather than calling straight through, because a cast that
      // spawns a projectile needs the scene GROUP, which only the frame loop holds — the same
      // reason play3d hands placed archetypes to its sim instead of resolving them in the handler.
      { const ci = CAST_CODES.indexOf(e.code); if (ci >= 0) pendingCast.current = ci }
      // ★ Q THROWS THE SELECTED STACK (Shift+Q for all of it). Deliberately NOT gated on the
      // weapon here: `weaponDrawn` is a prop and this listener is registered once, so testing it
      // in this closure would read whatever it was on mount forever. The frame loop below has the
      // live value and does the gate — `selItem` is already null while drawn, so it comes free.
      // ⚠ Q also cycles weapons in the parent's handler, but only WHILE DRAWN, and the two cases
      // cannot overlap for exactly that reason.
      if (e.code === 'KeyQ') pendingDrop.current = { all: e.shiftKey }
    }
    const ku = (e: KeyboardEvent) => { keys.current[e.code] = false }
    const md = (e: MouseEvent) => {
      if (uiOpen.current) return
      /**
       * ── ★ THE CLICK THAT GRABS THE CAMERA IS NOT A GAME VERB (2026-08-12, Alex) ───────────────
       * Alex: "when I try to grab the camera it mines whatever block is in front of me." Exactly
       * that. Clicking the canvas while unlocked means *give me the mouse* — but this handler set
       * `mouse.left` first and the frame loop read it as "start mining", so taking the camera back
       * after any Escape cost you the block you happened to be facing.
       *
       * It is the same bug as the bag's slot-click one directly above, one layer out: that gate
       * asked "is a cursor SURFACE open", and the pointer being free is the case it could not see —
       * there is no panel up, the world is simply not listening yet. The honest question is not
       * which UI is open but **whether the mouse belongs to the world at all**, and the pointer lock
       * is the only thing that actually answers it.
       *
       * ★ AND IT STAYS ASYMMETRIC, for the reason written above: only the PRESS is refused. `mu`
       * is deliberately ungated, so a button held across a lock change still records its release
       * and cannot strand `mouse.left` true — down is a request the world may refuse, up is a fact
       * it has to record.
       */
      if (!document.pointerLockElement) return
      if (e.button === 0) mouse.current.left = true; if (e.button === 2) mouse.current.right = true
    }
    const mu = (e: MouseEvent) => { if (e.button === 0) mouse.current.left = false; if (e.button === 2) mouse.current.right = false }
    const ctx = (e: Event) => e.preventDefault()
    window.addEventListener('keydown', kd); window.addEventListener('keyup', ku)
    window.addEventListener('mousedown', md); window.addEventListener('mouseup', mu)
    window.addEventListener('contextmenu', ctx)
    return () => {
      window.removeEventListener('keydown', kd); window.removeEventListener('keyup', ku)
      window.removeEventListener('mousedown', md); window.removeEventListener('mouseup', mu)
      window.removeEventListener('contextmenu', ctx)
    }
  }, [])

  useEffect(() => { camera.position.set(SPAWN_X + 0.5, columnHeight(SPAWN_X, SPAWN_Z, SEED) + 2.6, SPAWN_Z + 0.5) }, [camera])

  /** What is actually there. Unloaded reads as AIR — used for the raycast, so you can never target
   *  or mine a block that has not been generated. */
  // ★ EVERYTHING THIS COMPONENT ALLOCATES ON THE GPU IS RELEASED ON UNMOUNT. Without this, a
  // navigation away leaks every chunk geometry plus the shared material and drop resources — and a
  // page that leaks a full render's worth of buffers per visit is how the context gets lost in the
  // first place. The shared resources are disposed here and ONLY here, because disposing them
  // anywhere else would break every object still using them.
  /** Write every dirty column's blocks, pieces AND chest contents in one record each. */
  const flushSaves = useCallback(() => {
    for (const k of dirtySaves.current) {
      const [gx, gz] = k.split(',').map(Number)
      const e = edits.current.get(k) ?? new Map()
      // Empty chests are dropped from the RECORD but kept in memory: opening a chest and taking
      // everything out must stop costing storage, the same rule `saveColumn` applies to a column
      // whose blocks were all restored. The live grid stays in the map so the panel's array
      // identity survives — it just has nothing worth writing down.
      const rec = chestsByCol.current.get(k)
      let chests: Record<string, Slots> | undefined
      if (rec) {
        for (const [ck, g] of Object.entries(rec)) if (!isChestEmpty(g)) (chests ??= {})[ck] = g
      }
      // Station jobs, same rule as chests: a spent record is dropped rather than written, so a
      // bench you loaded once and emptied stops costing storage.
      const shopRec = jobsByCol.current.get(k)
      let jobs: Workshop | undefined
      if (shopRec) for (const [jk, j] of Object.entries(shopRec)) if (j.runs > 0) (jobs ??= {})[jk] = j
      void saveColumn(SEED, gx, gz, {
        edits: packEdits(e), pieces: piecesByCol.current.get(k) ?? [],
        genRemoved: genRemovedByCol.current.get(k), chests, jobs,
      })
    }
    dirtySaves.current.clear()
  }, [])

  // ★ THE LAST SWING BEFORE A REFRESH MUST SURVIVE. A once-a-second flush loses up to a second of
  // building on a close, which is precisely the moment a player remembers.
  useEffect(() => {
    const flush = () => flushSaves()
    // `visibilitychange` rather than `beforeunload`: mobile and modern Chrome may never fire the
    // latter, and this is the event that is actually guaranteed before a tab goes away.
    document.addEventListener('visibilitychange', flush)
    window.addEventListener('pagehide', flush)
    return () => {
      flush()
      document.removeEventListener('visibilitychange', flush)
      window.removeEventListener('pagehide', flush)
    }
  }, [flushSaves])

  useEffect(() => () => {
    for (const m of drawn.current.values()) m.geometry.dispose()
    drawn.current.clear()
    dropMeshes.current.clear()
    for (const m of dropMats.current.values()) m.dispose()
    dropMats.current.clear()
    dropGeo.dispose()
    highlightGeo.dispose()
    pieces.dispose()
    flatMaterial.dispose()
    textured?.material.dispose()
    waterMaterial.dispose()
    for (const gm of Object.values(hollowGeo)) gm.dispose()
    for (const mt of Object.values(hollowMat)) mt.dispose()
    tiles?.texture.dispose()
    greg.dispose()
    steam.dispose()
    mist.dispose()
    flora.dispose()
  }, [dropGeo, highlightGeo, flatMaterial, textured, tiles, pieces, greg, steam, mist, flora])

  // ★ A LOST WEBGL CONTEXT MUST SAY SO. Chrome blocks a page that loses its context repeatedly, and
  // the result is a black canvas with the HUD still drawn on top — indistinguishable from a
  // generation failure, which is exactly why I hunted the mesher first when it happened. The block
  // is sticky for the life of the tab: reloading does not clear it, closing the tab does.
  useEffect(() => {
    const cv = gl.domElement
    const lost = (e: Event) => { e.preventDefault(); onStats('WEBGL CONTEXT LOST — close this tab and open a new one') }
    const restored = () => onStats('webgl context restored')
    cv.addEventListener('webglcontextlost', lost)
    cv.addEventListener('webglcontextrestored', restored)
    return () => { cv.removeEventListener('webglcontextlost', lost); cv.removeEventListener('webglcontextrestored', restored) }
  }, [gl, onStats])

  const voxel = useCallback((wx: number, wy: number, wz: number): number => {
    if (wy < 0 || wy >= H) return AIR
    const cx = Math.floor(wx / SECTION), cz = Math.floor(wz / SECTION)
    const c = cols.current.get(key(cx, cz))
    if (!c) return AIR
    return c.get(wx - cx * SECTION, wy, wz - cz * SECTION)
  }, [])

  /**
   * ★ COLLISION TREATS UNGENERATED SPACE AS SOLID, AND THAT IS THE WHOLE FIX FOR FALLING OFF THE
   * MAP. Sprinting is 22 units/s and generation is bounded, so a player outruns the load radius
   * routinely. With unloaded reading as AIR the floor simply is not there yet and you drop through
   * the world — which is what "I found a gap and fell off the map" actually was.
   *
   * Unknown terrain must BLOCK, never swallow. The worst case is standing still for a moment at the
   * edge of the world; the alternative is falling out of it. Note this deliberately differs from
   * `voxel` above: the raycast must NOT see phantom solids, or you would mine invisible blocks at
   * the frontier.
   */
  const voxelSolid = useCallback((wx: number, wy: number, wz: number): number => {
    if (wy < 0) return MAT.BEDROCK
    if (wy >= H) return AIR
    const cx = Math.floor(wx / SECTION), cz = Math.floor(wz / SECTION)
    const c = cols.current.get(key(cx, cz))
    if (!c) return MAT.BEDROCK          // not generated yet ⇒ stand on it, do not fall through it
    return c.get(wx - cx * SECTION, wy, wz - cz * SECTION)
  }, [])

  /**
   * ── ★ THE LIVE GROUND LINE — what is actually underfoot, not what the generator planned ───────
   *
   * `columnHeight(x, z, SEED)` is a PURE GENERATOR QUERY: it does not know about mining, building,
   * or anything a player has ever done. Every consumer that asks it is asking about the world as
   * first imagined.
   *
   * ★ THAT IS A BUG WHEREVER SOMETHING HAS TO WALK, AND IT PREDATES THE CAST WORK. The Hollows'
   * ground probe was `columnHeight`, which means **no wall has ever stopped a Hollow** — not a
   * conjured one and not one the player spent an evening building. It glided through both, because
   * as far as it could see the ground was still the ground. I claimed in the 08-14 walker commit
   * that conjured terrain would stop a warden "for free once it writes real voxels"; that was
   * wrong, and this is the missing half.
   *
   * Returns the y of the topmost SOLID block near `fromY`, i.e. the same thing `columnHeight`
   * returns but true. Bounded to a window around the asker's own height on purpose — a walking body
   * only needs to know the step in front of it, and an unbounded column scan per body per frame is
   * a cost with no buyer. Falls back to the generator when the window is all air, so behaviour
   * degrades to exactly today's rather than dropping a body through the floor.
   */
  const groundTopNear = useCallback((x: number, z: number, fromY: number, span = 6): number => {
    const xi = Math.floor(x), zi = Math.floor(z)
    const top = Math.min(H - 1, Math.floor(fromY) + span)
    const bottom = Math.max(0, Math.floor(fromY) - span)
    for (let y = top; y >= bottom; y--) {
      if (voxel(xi, y, zi) !== AIR) return y
    }
    return columnHeight(xi, zi, SEED)
  }, [voxel])


  /**
   * ── ★ LEAVES WAITING TO FALL (2026-08-13) ─────────────────────────────────────────────────────
   * Alex: *"once the trunk is mined the leaves should come down over time."*
   *
   * A SIDECAR like the pot clock, not a column record like a chest's contents, and the difference
   * is which transaction the data has to be atomic with. A chest's items must arrive and leave with
   * its block or a badly-timed refresh destroys them. A pending leaf is the opposite: the block it
   * names is still perfectly ordinary world state, and the queue is only a note about the FUTURE.
   * Losing it costs one canopy that stays up, never an item.
   *
   * ⚠ It is keyed by SEED and holds absolute timestamps, so walking away and coming back an hour
   * later finds the whole canopy already due — which is the only reading of "over time" that
   * survives the game not running.
   */
  /**
   * A queued throw, set by the key handler and resolved in the frame loop.
   *
   * ★ SAME PATTERN AS `pendingCast`, and for the same reason: a toss needs the CAMERA's facing and
   * the live drops array, neither of which a `keydown` closure registered once on mount can see
   * without going stale. `all` carries Shift at the moment the key went down, because by the time
   * the frame runs the modifier may already be released.
   */
  const pendingDrop = useRef<null | { all: boolean }>(null)

  const decayQueue = useRef<PendingLeaf[]>([])
  /** Last wall-clock second the queue was written to storage. See the throttle in the decay tick. */
  const decaySavedAt = useRef(0)
  const DECAY_KEY = `voxel3d:leafdecay:${SEED}`
  const saveDecay = useCallback(() => {
    try { localStorage.setItem(DECAY_KEY, JSON.stringify(decayQueue.current)) } catch { /* full disk */ }
  }, [DECAY_KEY])
  useEffect(() => {
    try { decayQueue.current = JSON.parse(localStorage.getItem(DECAY_KEY) ?? '[]') } catch { decayQueue.current = [] }
  }, [DECAY_KEY])

  const remesh = useCallback((cx: number, cz: number) => {
    const g = group.current
    const c = cols.current.get(key(cx, cz))
    if (!g || !c) return
    const k = key(cx, cz)
    for (const [mk, m] of drawn.current) {
      if (!mk.startsWith(k + ':')) continue
      g.remove(m); m.geometry.dispose(); drawn.current.delete(mk)
    }
    // ── ★ ONE MESH PER COLUMN PER PASS (2026-08-13) ────────────────────────────────────────────
    // The three passes are collected across every section of the column and merged once, so a
    // column costs at most three draws instead of three per section. The reasoning, and the
    // frustum-granularity trade it buys, is on `concatAttrs` in attrs.ts.
    //
    // ⚠ The passes stay SEPARATE — merging them into one mesh would be a different change and a
    // wrong one. Water is a second pass because transparency must blend after opaque, and leaves
    // are a third because they need an alpha cutout the block program must not carry. Neither is
    // about draw-call count, so neither is fixed by counting draw calls.
    const solids: AttrPart[] = [], waters: AttrPart[] = [], leafParts: AttrPart[] = []
    for (const sm of meshColumn(c, {
      negX: cols.current.get(key(cx - 1, cz)) ?? null,
      posX: cols.current.get(key(cx + 1, cz)) ?? null,
      negZ: cols.current.get(key(cx, cz - 1)) ?? null,
      posZ: cols.current.get(key(cx, cz + 1)) ?? null,
    }, scratch)) {
      // Water splits into its own mesh so it can blend AFTER the opaque pass — see attrs.ts.
      const { solid, water, leaves } = buildAttrsSplit(sm.mesh, m => m === MAT.WATER, isLeafMat)
      if (solid) solids.push({ attrs: solid, dy: sm.wy })
      if (water) waters.push({ attrs: water, dy: sm.wy })
      if (leaves) leafParts.push({ attrs: leaves, dy: sm.wy })
    }

    // ⚠ THE MESH SITS AT THE COLUMN ORIGIN, y=0 — `concatAttrs` already lifted each section's
    // positions by its own `wy`. Positioning this at a section's `wy` as the old code did would
    // apply that offset twice and float the whole column.
    const emit = (parts: AttrPart[], mat: THREE.Material, suffix: string, order = 0) => {
      const merged = concatAttrs(parts)
      if (!merged) return
      const mesh = new THREE.Mesh(toGeometry(merged), mat)
      mesh.position.set(c.wx, 0, c.wz)
      if (order) mesh.renderOrder = order
      g.add(mesh)
      drawn.current.set(`${k}:${suffix}`, mesh)
    }
    emit(solids, material, 's')
    emit(waters, waterMaterial, 'w', 1)
    emit(leafParts, leafMaterial, 'l')
  }, [material, waterMaterial, leafMaterial, scratch])

  /**
   * ── ★ STREAMING MESHES THROUGH A BUDGETED QUEUE, NOT SYNCHRONOUSLY (2026-08-07) ────────────
   * The lag Alex hit was not framerate, it was the main thread WEDGED — reproduced as a ~45s
   * unresponsive renderer on a fresh load. The adopt path called `remesh` inline for every arriving
   * column PLUS its four neighbours: at ~47ms per meshColumn that is ~470ms per frame while
   * streaming, and the same stall re-fires in a row of columns every time you walk into new ground.
   * Worse, each column got meshed up to five times as its neighbours arrived one by one.
   *
   * The queue fixes both at once: entries dedup in the Set (a column queued by five neighbours
   * meshes ONCE, with more neighbours present — better output for a fifth of the work), and the
   * drain is time-budgeted per frame, nearest first, so streaming costs a bounded slice of each
   * frame instead of the whole frame. Mining does NOT go through here — `setVoxel` keeps its
   * synchronous remesh, because a swing that repairs the hole two frames later reads as broken.
   */
  const remeshQueue = useRef(new Set<string>())
  const queueRemesh = useCallback((cx: number, cz: number) => {
    if (cols.current.has(key(cx, cz))) remeshQueue.current.add(key(cx, cz))
  }, [])
  /** Mesh queued columns until the frame budget runs out. Always does at least one so the queue
   *  cannot starve on a slow machine whose every mesh overruns the budget. */
  const drainRemeshQueue = useCallback((pcx: number, pcz: number, budgetMs: number) => {
    const q = remeshQueue.current
    if (!q.size) return
    const keys = [...q]
    // Nearest to the player first — the far edge of the load radius can wait; the ground at your
    // feet cannot.
    keys.sort((a, b) => {
      const [ax, az] = a.split(',').map(Number)
      const [bx, bz] = b.split(',').map(Number)
      return ((ax - pcx) ** 2 + (az - pcz) ** 2) - ((bx - pcx) ** 2 + (bz - pcz) ** 2)
    })
    const end = performance.now() + budgetMs
    for (const k of keys) {
      q.delete(k)
      const [gx, gz] = k.split(',').map(Number)
      remesh(gx, gz)
      if (performance.now() > end) break
    }
  }, [remesh])

  /**
   * ── ★ A RUNTIME WRITE: real voxels that never enter the save ──────────────────────────────────
   *
   * The `applyGenPieces` path, generalised. Writes straight into sections, so it does NOT
   * `recordEdit`, does NOT touch `dirtySaves`, and does not run the chest/station/leaf-decay funnels
   * that `setVoxel` owns — none of which a conjured wall should ever trigger. It is an occupancy
   * with a lifetime, not a change to the world.
   *
   * ⚠ REMESHES ONCE PER TOUCHED COLUMN, not once per block. A Pillar Tomb is 9 cells × 4 tall = 36
   * writes; going through a per-block remesh would rebuild the same column three dozen times in one
   * frame, which is the shape of every "why did casting hitch" bug I would then have to find.
   */
  const runtimeWrite = useCallback((cells: readonly { x: number; y: number; z: number }[], mat: number) => {
    const touched = new Set<string>()
    for (const c of cells) {
      const cx = Math.floor(c.x / SECTION), cz = Math.floor(c.z / SECTION)
      const col = cols.current.get(key(cx, cz))
      if (!col) continue                                   // unloaded: nothing to write into
      const sy = (c.y / SECTION) | 0
      const s = col.sections[sy]
      if (!s) continue
      s.set(c.x - cx * SECTION, c.y - sy * SECTION, c.z - cz * SECTION, mat)
      touched.add(key(cx, cz))
    }
    for (const k of touched) {
      const col = cols.current.get(k)
      if (col) refreshUniform(col)
      const [cx, cz] = k.split(',').map(Number)
      queueRemesh(cx, cz)
    }
  }, [queueRemesh])

  /**
   * ── ★ GENERATED PIECES (the pieces pass, 2026-08-08) ─────────────────────────────────────────
   * Apply a column's hold dressing on adopt: recompute from the map, drop what the player's
   * tombstones killed, write the occupancy DIRECTLY into sections — never through `setVoxel`,
   * because regenerable content must not enter the save (the exact mirror of why player pieces
   * DO go through it). Re-adoption after an evict replaces this column's old gen entries, so a
   * walk-away-and-back can't double the parapets.
   */
  const applyGenPieces = useCallback((gx: number, gz: number, removed: string[]) => {
    const gen = holdGenPiecesForCol(gx, gz, SECTION, i => holdPadLevel(i, SEED))
    if (!gen.length) return
    const k = key(gx, gz)
    const skip = new Set(removed)
    const live: (GenPiece & Placement)[] = gen.filter(g => !skip.has(g.gen))
    const c = cols.current.get(k)
    if (c) {
      for (const g of live) {
        const def = pieceDef(g.pieceId)!
        for (const cell of cellsOf(g, def)) {
          if (!cell.solid) continue
          const lx = cell.x - gx * SECTION, lz = cell.z - gz * SECTION
          if (lx < 0 || lx >= SECTION || lz < 0 || lz >= SECTION) continue
          const sy = (cell.y / SECTION) | 0
          const s = c.sections[sy]
          if (s) s.set(lx, cell.y - sy * SECTION, lz, def.halfHeight ? STRUCTURE_HALF : STRUCTURE)
        }
      }
      refreshUniform(c)
      queueRemesh(gx, gz)
    }
    placements.current = [...placements.current.filter(p => !p.gen || colOf(p.x, p.z) !== k), ...live]
    pieces.sync(placements.current)
  }, [queueRemesh, colOf, pieces])

  /**
   * The contents of the chest at this cell, created on first open.
   *
   * ★ LAZY, so an untouched chest costs nothing — and `flushSaves` drops empty grids from the
   * record, so opening one and taking everything back out costs nothing again. The grid is returned
   * BY REFERENCE and the panel mutates it in place; that is deliberate (one array, one truth), and
   * it is why `touchChest` exists rather than a setter that could be forgotten.
   */
  const chestAt = useCallback((x: number, y: number, z: number): Slots => {
    const k = colOf(x, z)
    let rec = chestsByCol.current.get(k)
    if (!rec) { rec = {}; chestsByCol.current.set(k, rec) }
    const ck = chestKey(x, y, z)
    return (rec[ck] ??= createChest())
  }, [colOf])

  /**
   * ⚠ CALL THIS AFTER EVERY CHANGE TO A CHEST'S CONTENTS. Moving an item into a chest does not go
   * through `setVoxel`, so nothing marks the column dirty on its own — without this a full chest is
   * written only when some block near it happens to change, and a session that only sorted its
   * storage saves nothing at all.
   */
  const touchChest = useCallback((x: number, z: number) => { dirtySaves.current.add(colOf(x, z)) }, [colOf])

  /**
   * A station's standing job, or undefined for an idle bench.
   *
   * ⚠ READ-ONLY. Unlike `chestAt` this hands back a value rather than a live grid to mutate: a job
   * is replaced wholesale by `workshop.ts`'s pure functions (which return a new Workshop), so there
   * is nothing here to mutate in place and a caller that tried would be writing past the oracle.
   */
  const jobAt = useCallback((x: number, y: number, z: number): StationJob | undefined =>
    jobsByCol.current.get(colOf(x, z))?.[stationKey(x, y, z)], [colOf])

  /**
   * Put a station's job back, and mark the column so it is actually written down.
   *
   * ⚠ THE `dirtySaves` LINE IS THE WHOLE POINT — the same trap `touchChest` documents. Loading or
   * collecting a job never goes through `setVoxel`, so without this a bench is saved only when some
   * block near it happens to change, and a session spent running the workshop saves nothing.
   */
  const setJob = useCallback((x: number, y: number, z: number, shop: Workshop) => {
    const k = colOf(x, z)
    const rec = shop[stationKey(x, y, z)]
    let cur = jobsByCol.current.get(k)
    if (!cur) { cur = {}; jobsByCol.current.set(k, cur) }
    if (rec) cur[stationKey(x, y, z)] = rec
    else delete cur[stationKey(x, y, z)]
    dirtySaves.current.add(k)
  }, [colOf])

  /**
   * Write one voxel and repair the geometry.
   *
   * ★ THE NEIGHBOUR RE-MESH IS NOT OPTIONAL. Editing a voxel on a column's edge changes which faces
   * the NEIGHBOUR should draw — mine the last block of a column and, without this, the neighbour
   * keeps the wall it drew while that block still existed. It reads as an invisible pane you cannot
   * mine, sitting at exactly the seams a player walks along.
   *
   * `refreshUniform` matters for the same class of reason: the mesher's skip reads that table, and
   * a stale entry means dropped faces.
   */
  const setVoxel = useCallback((wx: number, wy: number, wz: number, mat: number) => {
    const cx = Math.floor(wx / SECTION), cz = Math.floor(wz / SECTION)
    const k = key(cx, cz)
    const c = cols.current.get(k)
    if (!c) return
    const lx = wx - cx * SECTION, lz = wz - cz * SECTION
    const s = (wy / SECTION) | 0

    // ★ Diff against what the GENERATOR would have put here, not against the current value — that
    // is what lets mining a block and putting it back return the save to empty instead of storing
    // a no-op forever. `materialAt` is pure, so the original is always recoverable without having
    // kept a pristine copy of the column around.
    // ★ `generatedAt`, NOT `materialAt` — it knows about ground cover. Ask materialAt here and
    // picking a flower compares AIR against AIR, stores no edit, and the flower is back on reload.
    const generated = generatedVoxel(c, lx, wy, lz, SEED)
    let e = edits.current.get(k)
    if (!e) { e = new Map(); edits.current.set(k, e) }
    recordEdit(e, editIndex(lx, wy, lz), mat, generated)
    dirtySaves.current.add(k)

    // ── ★ A CHEST'S RECORD DIES WITH ITS BLOCK ─────────────────────────────────────────────────
    // Here rather than in the mining branch because this is the funnel EVERY world write goes
    // through, so no future path (an explosion, a piece deconstruct, a console verb) can leave a
    // contents record stranded at a cell that is no longer a chest — which would hand the next
    // chest built on that spot somebody else's items, and grow the save with keys nothing can
    // reach. The guard on `prevMat !== mat` matters: a no-op write of CHEST over CHEST must not
    // empty a chest the player is standing in front of.
    const prevMat = c.sections[s].get(lx, wy - s * SECTION, lz)
    if (prevMat !== mat && (prevMat === MAT.CHEST || mat === MAT.CHEST)) {
      const rec = chestsByCol.current.get(k)
      if (rec) {
        delete rec[chestKey(wx, wy, wz)]
        if (!Object.keys(rec).length) chestsByCol.current.delete(k)
      }
    }
    // ★ AND A STATION'S JOB DIES WITH ITS BLOCK, for the identical reason — otherwise the next
    // bench built on this cell inherits somebody else's half-finished work. The mining branch has
    // already SALVAGED it into drops by the time this runs; this is the record cleanup, not the
    // payout. Same `prevMat !== mat` guard: re-writing CRAFT_TABLE over CRAFT_TABLE must not
    // silently void the job of a bench the player is standing at.
    if (prevMat !== mat && (stationOf(prevMat) || stationOf(mat))) {
      const rec = jobsByCol.current.get(k)
      if (rec) {
        delete rec[stationKey(wx, wy, wz)]
        if (!Object.keys(rec).length) jobsByCol.current.delete(k)
      }
    }

    c.sections[s].set(lx, wy - s * SECTION, lz, mat)
    refreshUniform(c)
    flora.invalidate(k)             // the ground changed — this column's tufts re-derive
    floraDirty.current = true
    remesh(cx, cz)
    if (lx === 0) remesh(cx - 1, cz)
    if (lx === SECTION - 1) remesh(cx + 1, cz)
    if (lz === 0) remesh(cx, cz - 1)
    if (lz === SECTION - 1) remesh(cx, cz + 1)
    // Any cached light field whose 3×3 box can see this column is stale now — placing a lantern
    // (or roofing a room) must change what the NEXT spawn scan reads, not what the last one read.
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++)
      lightCache.current.delete(key(cx + dx, cz + dz))
    // Fence connections are DERIVED from the world, so a terrain edit beside a fence makes or
    // breaks an arm — re-derive. O(placements) matrix writes; edits are player-paced, not 60Hz.
    pieces.sync(placements.current)

    // ── ★ A FELLED TRUNK LOSES ITS CANOPY ────────────────────────────────────────────────────
    // In this funnel for exactly the reason the chest record above is: every world write passes
    // through here, so a log that disappears down some future path (an explosion, a console verb)
    // drops its leaves too, rather than only the one that goes through the mining branch.
    //
    // ⚠ RUN IT AFTER the section write, never before — `orphanedLeaves` asks the world what is
    // still standing, and if the log being felled is still in the grid it counts as its own
    // support and nothing is ever orphaned.
    //
    // ⚠ `voxel` reads unloaded space as AIR, so in principle a tree straddling the edge of the
    // loaded world could look unsupported. It cannot in practice: you have to be standing next to
    // a trunk to chop it, and its own column plus neighbours are loaded by definition.
    if (isLogMat(prevMat) && mat === AIR) {
      const now = performance.now() / 1000
      const cells = orphanedLeaves(voxel, isLeafMat, isLogMat, wx, wy, wz, Math.random)
      if (cells.length) { decayQueue.current = enqueueLeaves(decayQueue.current, cells, now); saveDecay() }
    }
  }, [remesh, pieces, voxel, saveDecay])

  /** The locomotion core's world probe — a CELL CODE now, not a boolean (2026-08-08): water is
   *  a medium the walker swims, not a hole it wades. Ungenerated space still reads as solid via
   *  voxelSolid — the same stand-on-it-don't-fall-through-it rule the old walker had. */
  /**
   * Is this cell open to the sky?
   *
   * ⚠ A BOUNDED WALK, not a true column scan, and it is bounded for a reason worth stating: the
   * only caller is the sapling rule, which asks it a handful of times every few seconds. Scanning
   * to world height would be exact and pointless; 96 blocks is far above anything a player builds
   * or any terrain that overhangs, and a mountain 96 blocks above your garden is a roof by any
   * reasonable reading. Leaves count as cover — growing a tree under a canopy is the case the rule
   * exists to prevent.
   */
  const openToSky = useCallback((x: number, z: number, y: number): boolean => {
    for (let k = 1; k <= 96; k++) if (voxel(x, y + k, z) !== AIR) return false
    return true
  }, [voxel])

  const solidProbe = useCallback((x: number, y: number, z: number) => {
    const m = voxelSolid(x, y, z)
    if (m === MAT.WATER) return CELL_WATER
    if (m === STRUCTURE_HALF || isHalfMat(m)) return CELL_HALF
    if (!isSolid(m)) return CELL_EMPTY
    return CELL_SOLID
  }, [voxelSolid])

  // Fence arms ask the world what to grab — walls, hillsides, other pieces' occupancy. Slabs are
  // excluded: a rail into a half-cell's empty upper half reads as floating.
  useEffect(() => {
    pieces.setWorldSolid((x, y, z) => { const m = voxelSolid(x, y, z); return isSolid(m) && m !== STRUCTURE_HALF })
    return () => pieces.setWorldSolid(null)
  }, [pieces, voxelSolid])

  // ── ★ THE FIRING RIG ─────────────────────────────────────────────────────────────────────────
  // Real travelling projectiles, not hitscan. The table already defines projSpeed/projLife per
  // model (a Lance round is a fast fat bolt, a Spitter round is not), and throwing that away for
  // hitscan would flatten the three feels the tuning exists to separate. It also matters the moment
  // mobs land: a projectile can be led and dodged, a hitscan cannot.
  //
  // ★ ONE SHARED MATERIAL FOR ALL TRACERS. A material per projectile is a shader program per
  // projectile, which is precisely what got this page BLOCKED from WebGL on 08-06 (black screen,
  // HUD alive, no console error) and why render-audit.test.ts exists. Full-auto would have hit that
  // within a second of holding the trigger.
  // ⚠ `dmg` is carried ON the shot, not read from the held weapon at impact. It has to be: a cast
  // bolt is not the gun, and even for gun rounds the old read was subtly wrong — swapping weapons
  // mid-flight retro-changed what an already-travelling round would do.
  const shots = useRef<{ x: number; y: number; z: number; dx: number; dy: number; dz: number
                         speed: number; life: number; mesh: THREE.Mesh; dmg: number }[]>([])
  const tracerGeo = useMemo(() => new THREE.SphereGeometry(1, 6, 4), [])
  const tracerMat = useMemo(() => new THREE.MeshBasicMaterial({ color: 0xffd88a, toneMapped: false }), [])
  const impacts = useRef<{ mesh: THREE.Mesh; life: number }[]>([])

  // ── cast FIELDS (SYSTEM 1, ported from play3d 2026-08-14) ─────────────────────────────────────
  // ⚠ BLOCKOUT, same standing as the Hollow bodies: legible geometry, no locked look. A design-brief
  // + /picaso pass owns what a Firewall actually looks like.
  //
  // ★ ONE material for every field, and that is CANON rather than a render shortcut. `moves.md:5` —
  // *"Colour is never part of a move. Colour is the mage's own, their soul-frequency, applied when
  // they cast it."* So a Firewall and a Healing Grove cast by the same keeper are the SAME colour,
  // and hue can never be the thing that tells them apart. The tell has to be MOTION (the pulse rate
  // below), which is also the only differentiator the render-audit rule allows.
  const fields = useRef<Field[]>([])
  const fieldMeshes = useRef(new Map<number, THREE.Mesh>())

  // ── cast TERRAIN (SYSTEM 2, ported 2026-08-14) — REAL BLOCKS, not a parallel entity ────────────
  // The cells live in the pure module; what makes this the better half of the port is that the host
  // WRITES them. No render pool, no second collision path: a conjured wall is voxels, so it blocks,
  // meshes, occludes and can be stood on by the same code that does all of that for a hillside.
  const conjured = useRef<Conjured[]>([])
  /**
   * ★ EXACTLY WHICH CELLS EACH CAST WROTE, so expiry undoes its own work and nothing else.
   *
   * Not derivable from the `Conjured` cells: those are a footprint, and the host only writes the
   * subset that was actually AIR. Reverting the footprint instead of the record would blow a hole
   * through whatever the wall grew up against — including, on a ten-second timer, a chest.
   */
  const conjuredWrites = useRef(new Map<number, { x: number; y: number; z: number }[]>())
  // Open-ended so you can see your own feet inside a grove, unit-sized so one geometry serves every
  // radius by scale alone (render-audit: a geometry per field is how a voxel renderer dies).
  const fieldGeo = useMemo(() => new THREE.CylinderGeometry(1, 1, 1, 18, 1, true), [])
  const fieldMat = useMemo(() => new THREE.MeshBasicMaterial({
    color: 0xaef2ff, transparent: true, opacity: 0.17, side: THREE.DoubleSide,
    depthWrite: false, toneMapped: false,
  }), [])

  // ── the Hollows (body blockout — see hollows.ts for the canon) ────────────────────────────────
  // ONE shared geometry and material for every Hollow that will ever body (render-audit rule).
  // Guttering is expressed through per-mesh SCALE and a sink, never per-mesh material state.
  const hollows = useRef<{ st: HollowState; mesh: THREE.Mesh }[]>([])
  const hollowClock = useRef(0)

  // ── the light field, cached per column ────────────────────────────────────────────────────────
  // `light.ts` produces DATA and this is its one consumer: the spawn scan. Each cached field
  // covers its column plus a 16-block apron (a lantern at a column edge must protect the ground
  // next door — computeLight treats out-of-box as dark, so a bare column-sized box would let the
  // grey body one block across a border from a light). Fields are computed lazily when the cycle
  // scans a column, evicted with the column, and invalidated by any edit their box can see.
  const lightCache = useRef(new Map<string, LightField>())
  const lightFor = useCallback((cx: number, cz: number): LightField => {
    const k = key(cx, cz)
    const hit = lightCache.current.get(k)
    if (hit) return hit
    // Vertical slice: the column's own surface span, padded down for pockets and up past a
    // lantern's reach. Full-height would be 9× the cells for air that cannot matter — block
    // light decays 1/step, so nothing >15 above the highest surface can touch the ground.
    const col = cols.current.get(k)
    let lo = H - 1, hi = 0
    if (col) {
      for (let i = 0; i < SECTION * SECTION; i++) {
        const s = col.surface[i]
        if (s < lo) lo = s
        if (s > hi) hi = s
      }
    } else { lo = 0; hi = H - 1 }
    const y0 = Math.max(0, lo - 10)
    const bounds = { x0: cx * SECTION - SECTION, y0, z0: cz * SECTION - SECTION,
                     sx: SECTION * 3, sy: Math.min(H, hi + 16) - y0, sz: SECTION * 3 }
    const field = computeLight(bounds, {
      // Air, water and foliage pass light; everything else stops it. Matches light.ts's contract.
      opaque: (x, y, z) => {
        const m = voxel(x, y, z)
        return m !== AIR && m !== MAT.WATER && !LIGHT_PASSES.has(m)
      },
      emit: (x, y, z) => emitOf(voxel(x, y, z)),
      // ⚠ Generated surface, not live voxels: a player-built roof does not register as closing
      // the sky. That only mis-lights covered ground DURING THE DAY (at night the sky channel is
      // worth 0 regardless), and surface Hollows only body at night — so the approximation is
      // free until daytime interior spawning exists.
      openToSky: (x, z, y) => y > columnHeight(x, z, SEED),
    })
    lightCache.current.set(k, field)
    return field
  }, [voxel])
  // ── ★ THREE SILHOUETTES, ONE GEOMETRY EACH, SHARED ACROSS EVERY BODY OF THAT FORM ──────────
  // ⚠ BLOCKOUT, same standing as the single body it replaces: the locked look is owed a
  // design-brief + /picaso pass (hollows.ts says so in writing) and these are read-at-a-glance
  // placeholders, not art. What they DO have to do is be tellable apart in the dark at forty
  // metres, because a triangle the player cannot read is not a triangle. Squat and wide, thin and
  // tall, small and hovering.
  // Three geometries and three materials TOTAL — not per body. A material per Hollow is a shader
  // program per Hollow, which is the allocation that got this page blocked from WebGL on 08-06.
  const hollowGeo = useMemo(() => ({
    warden: new THREE.IcosahedronGeometry(0.95, 1),
    stalker: new THREE.ConeGeometry(0.38, 1.5, 6),
    caster: new THREE.OctahedronGeometry(0.62, 0),
  }), [])
  const hollowMat = useMemo(() => ({
    // A smear of grey that holds a silhouette: darker than any ground grey, never a face. The
    // caster reads a shade colder so the thing draining you from range is findable.
    warden: new THREE.MeshLambertMaterial({ color: 0x3f423d, transparent: true, opacity: 0.9 }),
    stalker: new THREE.MeshLambertMaterial({ color: 0x4a4d47, transparent: true, opacity: 0.82 }),
    caster: new THREE.MeshLambertMaterial({ color: 0x474f58, transparent: true, opacity: 0.78 }),
  }), [])
  const lastShot = useRef(0)
  const bloom = useRef(0)
  const semiLatch = useRef(false)   // semi-auto: one round per PRESS, not per frame held

  useEffect(() => () => {
    // Disposed together — the geometry and material are shared, so a leak here leaks once, but a
    // route change that leaves them alive leaks a GPU buffer per visit.
    tracerGeo.dispose(); tracerMat.dispose()
  }, [tracerGeo, tracerMat])

  // Swapping models refills to that model's clip. Carrying rounds across a swap would let a
  // Repeater's 12 become a Lance's 12 against a clip of 8, and the HUD would disagree with the sim.
  useEffect(() => {
    ammo.current = weaponAt(weaponIdx).clip
    reloading.current = 0
    bloom.current = 0
    onAmmo(ammo.current)
  }, [weaponIdx, onAmmo])

  // ── ★ THE CAST LAYER REACHES THIS WORLD (2026-08-12, #294) ──────────────────────────────────
  // The rules are in `engine/cast-dispatch.ts` and are SHARED with play3d. This is only the host
  // half: what this world can land, and where the outcome goes.
  const castCd = useRef<number[]>([0, 0, 0, 0])
  /** Slot pressed this frame, consumed by the frame loop. -1 = nothing. */
  const pendingCast = useRef<number>(-1)
  const stance = useRef<CastSpec | null>(null)
  const surge = useRef<{ until: number; mult: number } | null>(null)
  const infusion = useRef<{ until: number; mult: number } | null>(null)
  const loadout = useRef<(string | null)[]>(loadLoadout(loadRuneInventory().owned, keeperBook(loadRuneInventory().owned)))
  /**
   * The rune inventory changed (today only `/rune`; tomorrow the Passage). Re-resolve rather than
   * patch: `loadLoadout` re-validates every bind against what is now owned, so a dropped rune takes
   * its move out of the slot on the same pass that a developed one opens a new bind. Skips the
   * mount tick — the ref above already did that read.
   */
  const runeTickSeen = useRef(runeTick)
  useEffect(() => {
    if (runeTickSeen.current === runeTick) return
    runeTickSeen.current = runeTick
    loadout.current = loadLoadout(loadRuneInventory().owned, keeperBook(loadRuneInventory().owned))
  }, [runeTick])
  /**
   * ★ WHAT THIS WORLD CAN ACTUALLY LAND, DECLARED RATHER THAN IMPLIED.
   * Projectiles ride the shot pool that already exists, and every SELF archetype only touches
   * hp/mana/speed, which live here.
   *
   * **`field` joined the set 2026-08-14** — slice 2, exactly as `cast-dispatch.ts` predicted it
   * would ("slice 2 adds 'field' to the voxel host's set and deletes nothing here"). It cost a
   * height on `FieldDef`, a target adapter onto the Hollows, and a render pass. **11 casts lit up.**
   *
   * **`terrain` joined it the same day** — step 3, and the one that got BETTER in the move: play3d
   * consults cells beside its tilemap so a wall can only block, while here the cells are WRITTEN as
   * `MAT.CONJURED` voxels, which collide, mesh, occlude and **can be stood on**. 7 more casts.
   *
   * `statuses` still does NOT: `statuses.ts` keys off play3d's named `hunter`/`guard` targets, and
   * this world's bodies are Hollows. Declaring that makes Shackle say "not in this world yet"
   * instead of being a key that silently does nothing — see cast-dispatch's header.
   */
  const supports = useMemo<ReadonlySet<CastArchetype>>(
    () => new Set<CastArchetype>([...SELF_ARCHETYPES, 'projectile', 'field', 'terrain']), [])

  const castSlot = useCallback((slot: number, g: THREE.Group) => {
    const v = vitals.current, m = mana.current
    if (!v || !m) return
    const env: CastEnv = {
      now: performance.now(), hp: v.hp, hpMax: v.hpMax, mana: m.cur,
      cooldownUntil: castCd.current, stanceMoveId: stance.current?.moveId ?? null, supports,
    }
    const out = resolveCast(slot, loadout.current, env)
    if (out.kind === 'refused') { onSay(out.message); return }

    // One apply, no archetype branching — every effect field is neutral when it does not apply,
    // which is the entire point of the outcome being a description rather than an action.
    m.cur = Math.max(0, m.cur - out.manaCost)
    if (out.cooldownUntil !== null) castCd.current[slot] = out.cooldownUntil
    if (out.stanceChange) stance.current = out.stanceChange.to
    if (out.hpDelta) v.hp = Math.min(v.hpMax, v.hp + out.hpDelta)
    if (out.surge) surge.current = out.surge
    if (out.infusion) infusion.current = out.infusion

    if (out.placed && out.placed.archetype === 'field') {
      // The aim point is the SHARED rule (`castAimPoint`), not a second hand-rolled copy: camera
      // forward flattened onto the ground plane, walked `castRange` from the caster's feet. play3d
      // open-codes this because the helper did not exist yet; there is no reason for a third version.
      const f = new THREE.Vector3()
      camera.getWorldDirection(f)
      const p = loco.current
      const aim = castAimPoint(f.x, f.z, p.px, p.pz, out.placed.castRange)
      // ★ GROUND IT TO THE TERRAIN IT LANDS ON, not to the caster's eye or the caster's feet. Cast
      // downhill and an eye-anchored field would hang in the air with its fire above the target's
      // head; cast uphill and it would bury itself. `columnHeight` is the same query the walker and
      // the Hollow spawner use, so the field stands on exactly the surface everything else does.
      const gy = columnHeight(Math.floor(aim.x), Math.floor(aim.z), SEED) + 1
      fields.current = spawnField(fields.current, {
        moveId: out.placed.moveId, x: aim.x, y: gy, z: aim.z,
        radius: out.placed.areaSize, height: FIELD_HEIGHT, secs: out.placed.areaSecs,
        dps: out.placed.fieldDps, hps: out.placed.fieldHps, stopsShots: out.placed.fieldStopsShots,
      }, env.now)
    }
    if (out.placed && out.placed.archetype === 'terrain') {
      const f = new THREE.Vector3()
      camera.getWorldDirection(f)
      const p = loco.current
      const flat = Math.hypot(f.x, f.z) || 1
      const aim = castAimPoint(f.x, f.z, p.px, p.pz, out.placed.castRange)
      const cells = shapeCells(out.placed.shape, aim.x, aim.z, f.x / flat, f.z / flat, out.placed.areaSize)
      // ★ ONLY INTO AIR, and record precisely what was written. The rule is pure and asserted in
      // `conjuredWriteCells` — the host just supplies the two world probes.
      const wrote = conjuredWriteCells(
        cells, out.placed.shapeHeight,
        (cx, cz) => groundTopNear(cx, cz, p.py),
        (vx, vy, vz) => voxel(vx, vy, vz) === AIR,
        H,
      )
      runtimeWrite(wrote, MAT.CONJURED)
      const before = new Set(conjured.current.map((c) => c.id))
      conjured.current = conjure(conjured.current, out.placed.moveId, cells, out.placed.areaSecs, out.placed.shapeHeight, env.now)
      const added = conjured.current.find((c) => !before.has(c.id))
      if (added) conjuredWrites.current.set(added.id, wrote)
      // ⚠ `conjure` DROPS THE OLDEST at the cap, and a dropped wall must give its blocks back or the
      // world keeps them forever. The pure module has no idea the host wrote anything, so the host
      // has to notice the eviction — this is the same id-diff the field meshes do.
      const now = new Set(conjured.current.map((c) => c.id))
      for (const [id, cellsWritten] of conjuredWrites.current) {
        if (now.has(id)) continue
        runtimeWrite(cellsWritten, AIR)
        conjuredWrites.current.delete(id)
      }
    }
    if (out.placed && out.placed.archetype === 'projectile') {
      // Rides the SAME pool and the same segment sweep as a gun round, so a bolt cannot tunnel
      // through a wall or miss a Hollow the gun would have hit. Only the numbers differ.
      const f = new THREE.Vector3()
      camera.getWorldDirection(f)
      const mesh = new THREE.Mesh(tracerGeo, tracerMat)
      mesh.scale.setScalar(0.1)
      mesh.position.copy(camera.position)
      g.add(mesh)
      shots.current.push({
        x: camera.position.x, y: camera.position.y, z: camera.position.z,
        dx: f.x, dy: f.y, dz: f.z,
        speed: out.placed.projSpeed, life: out.placed.projLife, mesh, dmg: out.placed.damage,
      })
    }
    if (out.message) onSay(out.message)
  }, [camera, tracerGeo, tracerMat, supports, vitals, mana, onSay])

  const fire = useCallback((w: WeaponDef, g: THREE.Group) => {
    const f = new THREE.Vector3()
    camera.getWorldDirection(f)
    const [dx, dy, dz] = coneDirection(f.x, f.y, f.z, spreadDeg(w, bloom.current, ads.current), Math.random(), Math.random())
    const mesh = new THREE.Mesh(tracerGeo, tracerMat)
    mesh.scale.setScalar(w.headR)
    // Spawned at the camera, not at a muzzle offset: this world has no viewmodel yet, and a
    // convergence fudge with nothing to converge FROM would just put rounds where the eye is not.
    mesh.position.copy(camera.position)
    g.add(mesh)
    shots.current.push({ x: camera.position.x, y: camera.position.y, z: camera.position.z,
                         dx, dy, dz, speed: w.projSpeed, life: w.projLife, mesh, dmg: w.damage })
    ammo.current = Math.max(0, ammo.current - 1)
    bloom.current = bloomAfterShot(w, bloom.current)
    const kick = recoilKick(w, Math.random)
    recoil.current.p += kick.pitch; recoil.current.y += kick.yaw
    lastShot.current = 0
    onAmmo(ammo.current)
  }, [camera, tracerGeo, tracerMat, onAmmo])

  useFrame((state, dtRaw) => {
    const dt = Math.min(dtRaw, 0.05)

    // ── ★ THE FRAME METER ────────────────────────────────────────────────────────────────────────
    // ⚠ SAMPLES `dtRaw`, NEVER `dt`. The clamp above is a gameplay guard — it stops a long frame
    // teleporting the player — and it floors at 0.05s, which is 20fps. Measuring the clamped value
    // would silently erase every hitch worse than 20fps, i.e. exactly the ones worth finding.
    //
    // ⚠ AND IT PUBLISHES ON A TIMER, NOT PER FRAME. A `setState` every frame re-renders the whole
    // HUD every frame, which costs enough to move the number — an instrument that changes what it
    // measures. Four windows a second is readable and effectively free.
    if (settings.showFps) {
      const w = perfWin.current
      w.frames++
      w.time += dtRaw
      if (dtRaw > w.worst) w.worst = dtRaw
      if (w.time >= 0.25) {
        onPerf({
          fps: Math.round(w.frames / w.time),
          ms: (w.time / w.frames) * 1000,
          worst: w.worst * 1000,
        })
        w.frames = 0; w.time = 0; w.worst = 0
      }
    }

    /**
     * ★ While a menu is up the world holds NO input at all. The listeners above already refuse new
     * presses; this clears what was held at the moment the menu opened — open the bag mid-sprint
     * and the sprint must not be waiting for you when you close it.
     *
     * Done every frame rather than once on the open EDGE because there is no edge to hang it on
     * here (`uiOpen` is a ref, deliberately, so opening a menu does not re-render the scene), and a
     * state that is re-derived every frame cannot drift out of sync with the thing it mirrors. It
     * costs one object literal per frame.
     */
    if (uiOpen.current) {
      keys.current = {}
      mouse.current.left = false; mouse.current.right = false
    }
    waterMaterial.tick(state.clock.elapsedTime)
    const g = group.current
    if (!g) return
    const p = camera.position
    steam.tick(p.x, p.y, p.z, dt, state.clock.elapsedTime)
    if (ledgerSeen.current !== mistLedger.current) { ledgerSeen.current = mistLedger.current; mist.setLedger(mistLedger.current) }
    mist.tick(p.x, p.y, p.z, dt, state.clock.elapsedTime)
    // ⚠ The presence PROMPT is not decided here any more — it needs this frame's aim, which does
    // not exist until the reticle raycast below. See "the three aimed verbs".
    flora.tick(state.clock.elapsedTime)
    const cx = Math.floor(p.x / SECTION), cz = Math.floor(p.z / SECTION)

    // ── ★ WEAPON TICK ────────────────────────────────────────────────────────────────────────
    // Runs before the mine/place block below, and that block is already gated on !weaponDrawn — so
    // the two verbs can never both consume the same click. That is the whole draw lock in one line.
    {
      const w = weaponAt(weaponIdx)
      lastShot.current += dt
      // ── the cast, consumed once per frame where the scene group is in hand ──────────────────
      // ⚠ Casting is deliberately NOT gated on `weaponDrawn`. A rune is not a gun and does not need
      // stowing to use — gating it behind the weapon would make the cast layer an accessory to the
      // thing canon says cannot answer half the world.
      if (pendingCast.current >= 0) { const slot = pendingCast.current; pendingCast.current = -1; castSlot(slot, g) }
      // Mana regen, and a held stance PAUSES it — canon's own cost for a passive (runes.md economy).
      {
        const m = mana.current
        if (m && !stance.current) m.cur = Math.min(m.max, m.cur + m.regen * dt)
        const nowMs = performance.now()
        if (surge.current && nowMs >= surge.current.until) surge.current = null
        if (infusion.current && nowMs >= infusion.current.until) infusion.current = null
      }
      ads.current = weaponDrawn && mouse.current.right
      // ADS zoom is lerped, never snapped: an instant FOV change reads as a teleport.
      const wantFov = ads.current ? ADS_FOV : 75
      const cam = camera as THREE.PerspectiveCamera
      if (Math.abs(cam.fov - wantFov) > 0.01) { cam.fov += (wantFov - cam.fov) * Math.min(1, dt * 12); cam.updateProjectionMatrix() }

      if (reloading.current > 0) {
        reloading.current -= dt
        if (reloading.current <= 0) { ammo.current = w.clip; onAmmo(ammo.current) }
      }
      if (!weaponDrawn) { bloom.current = bloomAfterRest(w, bloom.current, dt); semiLatch.current = false }
      else {
        if (mouse.current.left) {
          // Full-auto keeps firing while held; semi-auto needs the button to come back up first.
          const mayPress = w.auto || !semiLatch.current
          if (mayPress && canFire(w, lastShot.current, ammo.current, reloading.current)) { fire(w, g); semiLatch.current = true }
          else if (ammo.current <= 0 && reloading.current <= 0) reloading.current = w.reloadTime
        } else {
          semiLatch.current = false
          bloom.current = bloomAfterRest(w, bloom.current, dt)
        }
      }

      // Recoil is DRAINED into the camera here rather than written at fire time, so a burst climbs
      // smoothly instead of snapping once per round.
      if (recoil.current.p !== 0 || recoil.current.y !== 0) {
        camera.rotation.x += recoil.current.p * Math.min(1, dt * 18)
        camera.rotation.y += recoil.current.y * Math.min(1, dt * 18)
        const k = 1 - Math.min(1, dt * 18)
        recoil.current.p *= k; recoil.current.y *= k
      }

      // ── cast TERRAIN: hand the blocks back when the wall's time is up ───────────────────────
      // Cheap when nothing is up (the common case), and the revert is driven by the RECORD rather
      // than by re-deriving the footprint — see `conjuredWrites`.
      if (conjured.current.length > 0) {
        const nowMs = performance.now()
        const next = expireConjured(conjured.current, nowMs)
        if (next !== conjured.current) {
          const live = new Set(next.map((c) => c.id))
          for (const [id, cellsWritten] of conjuredWrites.current) {
            if (live.has(id)) continue
            runtimeWrite(cellsWritten, AIR)
            conjuredWrites.current.delete(id)
          }
          conjured.current = next
        }
      }

      // ── cast FIELDS: tick, bite, mend, render ──────────────────────────────────────────────
      // Runs BEFORE the projectile sweep so a Firewall spawned this frame is already cover this
      // frame, and so `blocksShotAtVolume` below never reads a field the tick has just expired.
      //
      // ⚠ USES `performance.now()`, NOT `state.clock.elapsedTime`. A field's `until`/`nextTick` were
      // stamped by `castSlot` off `performance.now()` (the same clock the cooldowns use). Mixing the
      // two clocks here would make every field either immortal or stillborn depending on how long
      // the tab had been open — and the render would look perfectly fine either way.
      if (fields.current.length > 0) {
        const nowMs = performance.now()
        const ticked = tickFields(fields.current, nowMs)
        fields.current = ticked.fields
        const lc = loco.current
        for (const fd of ticked.fired) {
          // Enemies inside take the bite. Same guard as the projectile path: a Hollow already at
          // hp<=0 is mid-disperse, and re-hitting it would double-drop its shard.
          if (fd.dps > 0) {
            for (const hw of hollows.current) {
              const st = hw.st
              if (st.hp <= 0 || st.gutter >= 1) continue
              if (!containsVolume(fd, st.x, st.y, st.z)) continue
              st.hp -= fd.dps
              if (st.hp <= 0) {
                // Dispersed by a field rather than a round — the loop must close identically, or
                // "kill it with fire" would quietly pay less than shooting it.
                drops.current.push(spawnDrop('raw_mana_shard', 1, Math.floor(st.x), Math.floor(st.y), Math.floor(st.z)))
              }
            }
          }
          // And the keeper standing in a grove is mended. Clamped to max: a heal that overshoots is
          // how a vitals bar starts reading above full.
          // `py` is the FEET (locomotion.ts), which is the body point that means 'standing in it'.
          if (fd.hps > 0 && containsVolume(fd, lc.px, lc.py, lc.pz)) {
            const v = vitals.current
            if (v) v.hp = Math.min(v.hpMax, v.hp + fd.hps)
          }
        }
        // ── the bodies. One mesh per live field, keyed by id, adopted and retired by diff.
        const live = new Set<number>()
        for (const fd of fields.current) {
          live.add(fd.id)
          let mesh = fieldMeshes.current.get(fd.id)
          if (!mesh) {
            mesh = new THREE.Mesh(fieldGeo, fieldMat)
            g.add(mesh)
            fieldMeshes.current.set(fd.id, mesh)
          }
          // A mend breathes slowly; a bite flickers. Motion is the ONLY tell available — canon puts
          // colour on the caster's soul, not the move, so two fields of one keeper share a hue.
          const rate = fd.hps > 0 ? 1.4 : 7.5
          const amp = fd.hps > 0 ? 0.05 : 0.02
          const pulse = 1 + Math.sin(nowMs * 0.001 * rate + fd.id) * amp
          mesh.scale.set(fd.radius * pulse, fd.height, fd.radius * pulse)
          // CylinderGeometry is centred on its own origin, so the slab's midpoint is half its height
          // above the ground line it was stamped with.
          mesh.position.set(fd.x, fd.y + fd.height / 2, fd.z)
        }
        for (const [id, mesh] of fieldMeshes.current) {
          if (live.has(id)) continue
          g.remove(mesh)
          fieldMeshes.current.delete(id)
        }
      }

      // ── projectiles ────────────────────────────────────────────────────────────────────────
      // Each round raycasts the SEGMENT it travelled this frame, never just its endpoint. At 54
      // units/sec a Lance round covers ~0.9 units per frame, so endpoint sampling would tunnel
      // straight through any wall thinner than that — the classic fast-projectile bug.
      for (let i = shots.current.length - 1; i >= 0; i--) {
        const sh = shots.current[i]
        const step = sh.speed * dt
        // ── ★ COVER EATS THE ROUND FIRST. Canon calls Firewall cover, so it stops shots — and it
        // stops YOURS too, symmetrically. That is the point: a wall of flame you can shoot through
        // is a damage puddle, and one that only blocks THEM is a free win. Same reasoning as Cordon
        // trapping the caster who stands in his own ring.
        //
        // ⚠ Tested at the round's CURRENT point, not swept. A field is metres across and a round
        // covers ~1 unit per frame, so a bolt cannot skip one — unlike the block raycast, which must
        // sweep because a wall is one voxel thin. Sweeping this too would cost a per-field segment
        // test every frame for no reachable bug.
        if (blocksShotAtVolume(fields.current, sh.x, sh.y, sh.z)) {
          g.remove(sh.mesh); shots.current.splice(i, 1)
          continue
        }
        // ── Hollows absorb rounds next: a Hollow between the muzzle and a wall takes the hit.
        // Same segment the block raycast walks, so nothing can tunnel through a body either.
        let absorbed = false
        for (const hw of hollows.current) {
          const st = hw.st
          if (st.hp <= 0 || st.gutter >= 1) continue
          if (segmentDist(sh.x, sh.y, sh.z, sh.dx, sh.dy, sh.dz, step, st.x, st.y, st.z) < formOf(st).radius) {
            st.hp -= sh.dmg
            const m = new THREE.Mesh(tracerGeo, tracerMat)
            m.scale.setScalar(0.16)
            m.position.set(st.x, st.y, st.z)
            g.add(m); impacts.current.push({ mesh: m, life: 0.25 })
            if (st.hp <= 0) {
              // Dispersed — frequency returns to a place that had none, and a little of it
              // condenses. Compacted mana in, mana shard out: the loop closes.
              drops.current.push(spawnDrop('raw_mana_shard', 1, Math.floor(st.x), Math.floor(st.y), Math.floor(st.z)))
            }
            g.remove(sh.mesh); shots.current.splice(i, 1)
            absorbed = true
            break
          }
        }
        if (absorbed) continue
        const hit = raycast(sh.x, sh.y, sh.z, sh.dx, sh.dy, sh.dz, step, voxelSolid)
        sh.life -= dt
        if (hit) {
          // Impact marker at the face, small and short-lived — the read is "I hit that block".
          const m = new THREE.Mesh(tracerGeo, tracerMat)
          m.scale.setScalar(0.12)
          m.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5)
          g.add(m); impacts.current.push({ mesh: m, life: 0.25 })
          g.remove(sh.mesh); shots.current.splice(i, 1)
          continue
        }
        sh.x += sh.dx * step; sh.y += sh.dy * step; sh.z += sh.dz * step
        sh.mesh.position.set(sh.x, sh.y, sh.z)
        if (sh.life <= 0) { g.remove(sh.mesh); shots.current.splice(i, 1) }
      }
      for (let i = impacts.current.length - 1; i >= 0; i--) {
        const im = impacts.current[i]
        im.life -= dt
        im.mesh.scale.setScalar(0.12 * Math.max(0, im.life / 0.25))
        if (im.life <= 0) { g.remove(im.mesh); impacts.current.splice(i, 1) }
      }
    }

    // ── ★ THE NIGHT TIDE'S PAYOFF — the Hollows' SPAWN CYCLE, MINECRAFT'S SHAPE ──────────────
    // Reworked 2026-08-07 eve after Alex night-walked without meeting one: the first cut scanned
    // ONE random column per 1.6s (a trickle); MC attempts EVERY eligible chunk every tick, and
    // the CAP is the governor, not scan luck (see hollows.ts for the ported numbers). Each sweep
    // walks all loaded columns — one random anchor each, pack of 1–4 on a triangular walk — and
    // the whole thing stays spatially opt-in: eligibility is the ruling as code (drained + dark
    // + dry), block light is an absolute veto (*tended light holds grey off*), and the tide now
    // comes in at DEEP DUSK per MC 1.18's internal-sky rule, not only at pitch black.
    {
      const now = state.clock.elapsedTime
      const day = dayFactor(dayProgress())
      hollowClock.current -= dt
      const cap = hollowCap(cols.current.size)
      const spawnHollow = (sx: number, sh: number, sz: number) => {
        const form = pickForm(Math.random())
        const mesh = new THREE.Mesh(hollowGeo[form], hollowMat[form])
        mesh.scale.set(0.01, 0.01, 0.01)          // rises from nothing — the forming IS the tell
        mesh.position.set(sx, sh + 1 + HOLLOW_HOVER, sz)
        g.add(mesh)
        hollows.current.push({
          st: { x: sx, y: sh + 1 + HOLLOW_HOVER, z: sz, form, hp: HOLLOW_FORMS[form].hp,
                gutter: 0, phase: Math.random() * 6.28 },
          mesh,
        })
      }
      // The despawn line IS the load edge — it derives from viewRadius now, so a wider view means
      // a wider night. hollows.ts's DESPAWN_DIST constant documented the r=6 baseline (96).
      const despawn = settings.viewRadius * SECTION
      // hollowNight is a cheap pre-gate, not the rule: an open surface spot's sky is 15, so
      // spawnDark can only pass once 15·day ≤ 7 anyway. The sweep is skipped, never the ruling.
      if (hollowNight(day) && hollows.current.length < cap && hollowClock.current <= 0) {
        hollowClock.current = SPAWN_CYCLE_S
        const keys = [...cols.current.keys()]
        // Light fields are computed lazily, at most 2 per sweep — a column whose field is not
        // ready yet is SKIPPED, not guessed at (no-spawn is the safe direction; the lantern's
        // veto must never be bypassed by a cache miss). The whole load fills within seconds.
        let lightBudget = 2
        // Random start offset so the same early-loaded columns do not win every night.
        const start = Math.floor(Math.random() * Math.max(1, keys.length))
        for (let i = 0; i < keys.length && hollows.current.length < cap; i++) {
          const [scx, scz] = keys[(start + i) % keys.length].split(',').map(Number)
          const ccx = scx * SECTION + SECTION / 2, ccz = scz * SECTION + SECTION / 2
          // A column entirely beyond despawn range would breed instant despawns — skip it.
          if (Math.hypot(ccx - p.x, ccz - p.z) > despawn + SECTION / 2) continue
          const kk = key(scx, scz)
          if (!lightCache.current.has(kk)) { if (lightBudget <= 0) continue; lightBudget-- }
          const lf = lightFor(scx, scz)
          // MC's structure: ONE random anchor per column per sweep. Coverage comes from sweeping
          // every column, not from hammering one.
          const wx = scx * SECTION + Math.floor(Math.random() * SECTION)
          const wz = scz * SECTION + Math.floor(Math.random() * SECTION)
          const sh = columnHeight(wx, wz, SEED)
          const dp = Math.hypot(wx + 0.5 - p.x, wz + 0.5 - p.z)
          if (dp < PLAYER_EXCLUSION || dp > despawn) continue
          if (!hollowEligible(wx + 0.5, wz + 0.5, SEED, lf.get(wx, sh + 1, wz), day, sh, DEFAULT_DEPTH.seaLevel)) continue
          // The pack: the anchor bodies, then up to 3 mates on a triangular walk — each on its
          // OWN re-validated ground, because a pack mate is not exempt from the ruling (an
          // anchor at a lit greyfield edge must not smear its pack onto tended ground).
          const k = Math.min(packSize(Math.random()), cap - hollows.current.length)
          spawnHollow(wx + 0.5, sh, wz + 0.5)
          for (const off of packWalk(k, Math.random)) {
            const mx = wx + 0.5 + off.dx, mz = wz + 0.5 + off.dz
            const mh = columnHeight(Math.floor(mx), Math.floor(mz), SEED)
            const mdp = Math.hypot(mx - p.x, mz - p.z)
            if (mdp < PLAYER_EXCLUSION || mdp > despawn) continue
            if (!hollowEligible(mx, mz, SEED, lf.get(Math.floor(mx), mh + 1, Math.floor(mz)), day, mh, DEFAULT_DEPTH.seaLevel)) continue
            spawnHollow(mx, mh, mz)
          }
        }
      }
      for (let i = hollows.current.length - 1; i >= 0; i--) {
        const hw = hollows.current[i]
        const st = hw.st
        // Dawn wins on the SAME clock the spawn gate reads (15·day = effective open-sky light);
        // GUTTER_SKY > NIGHT_SKY_MAX gives the dusk boundary hysteresis instead of a flap.
        if (15 * day >= GUTTER_SKY || st.hp <= 0) st.gutter = Math.min(1, st.gutter + dt * (st.hp <= 0 ? 2.2 : 0.7))
        // ★ THE LIVE GROUND, NOT THE GENERATOR'S (2026-08-14). This was `columnHeight`, which knows
        // nothing about mining, building or casting — so **no wall had ever stopped a Hollow**, and
        // my own walker commit claimed conjured terrain would stop a warden "for free". It would
        // not have: the walker's step-up rule was reading a world where the wall does not exist.
        // Now a Stonewall, a Cordon and a shed the player built all read as ground to climb, and the
        // two-high rule does the rest. `st.y` scopes the scan to the body's own height.
        hollowStep(st, dt, p.x, p.z, (x, z) => groundTopNear(x, z, st.y), now)
        // ── ★ THE TOUCH LANDS (2026-08-11) — before this, a Hollow that caught you glided
        // THROUGH you and nothing happened. Every system upstream (the two-channel light field,
        // the spawn cycle, the pack walk, the lantern's safe room) exists to make the dark cost
        // something, and the cost was never wired. Refreshed, never stacked: four in a pack must
        // read as one sustained drain, not a timer you can never outlive.
        if (hollowTouching(st, p.x, p.z)) {
          // `loco.current`, not `lc` — the frame callback's `lc` alias is declared further down,
          // in the movement block. Same ref either way.
          const keeper = loco.current
          const first = keeper.drainT <= 0
          // The form sets how long its drain holds — the warden is the one you cannot shrug off.
          keeper.drainT = Math.max(keeper.drainT, formOf(st).drain)
          if (first) onSay('the grey takes hold — you are slowed')
        }
        const s = Math.max(0.01, (1 - st.gutter))
        const pulse = 1 + Math.sin(now * 2.3 + st.phase) * 0.07
        hw.mesh.scale.x += (s * pulse - hw.mesh.scale.x) * Math.min(1, dt * 4)
        hw.mesh.scale.z += (s * pulse - hw.mesh.scale.z) * Math.min(1, dt * 4)
        hw.mesh.scale.y += (1.55 * s * (1 + Math.sin(now * 1.9 + st.phase) * 0.05) - hw.mesh.scale.y) * Math.min(1, dt * 4)
        hw.mesh.position.set(st.x, st.y - st.gutter * 0.9, st.z)
        const ddx = st.x - p.x, ddz = st.z - p.z
        if (st.gutter >= 1 || ddx * ddx + ddz * ddz > despawn * despawn) {
          g.remove(hw.mesh); hollows.current.splice(i, 1)
        }
      }
    }

    // ── adopt whatever the worker finished ───────────────────────────────────────────────────
    // Wrapping packed voxels into a Column is a view, not a copy: the sections point straight into
    // the transferred buffer, so adopting a generated column costs nothing.
    const t0 = performance.now()
    let adopted = 0
    while (incoming.current!.length && adopted < 2) {
      const { cx: gx, cz: gz, voxels, oIdx, oMat } = incoming.current!.shift()!
      const col = new Column(gx * SECTION, gz * SECTION)
      const per = SECTION * SECTION * SECTION
      for (let i = 0; i < col.sections.length; i++) col.sections[i].data.set(voxels.subarray(i * per, (i + 1) * per))
      // ★ THE WORKER SENDS VOXELS, NOT THE COLUMN — so everything DERIVED from the height field
      // has to be rebuilt here, and `slump` is derived (2026-08-11). Rebuilding only `surface`
      // left every worker-generated column with an all-zero slump mask: terrain slump would have
      // passed its whole oracle and done nothing in the actual game, because the worker is the
      // normal path and the main-thread generator is the fallback. `slumpMask` returns both from
      // one ring sample, which is also what keeps the two ways into a Column agreeing.
      const derived = slumpMask(gx * SECTION, gz * SECTION, SECTION, SEED, (x, z) => columnHeight(x, z, SEED))
      col.surface.set(derived.surface)
      col.slump.set(derived.mask)
      // Stage overrides come FROM the worker — they are a product of generation (carving, ore,
      // trees, ruins) and cannot be recovered here. Without them the save's diff compares a chopped
      // trunk against AIR, stores nothing, and the tree is standing again next time you load.
      if (oIdx && oMat) {
        const m2 = new Map<number, number>()
        for (let i = 0; i < oIdx.length; i++) m2.set(oIdx[i], oMat[i])
        col.overrides = m2
      }
      // ★ Apply any stored edits OVER freshly generated terrain — the diff is the save.
      // Edits arrive asynchronously from IndexedDB, so a column may mesh once procedurally and then
      // again once its edits land. That is deliberate: blocking the world on a database read would
      // stall streaming for the common case, which is a column with no edits at all.
      const ek = key(gx, gz)
      applyEdits(col, edits.current.get(ek))
      refreshUniform(col)
      col.stage = Stage.Ready
      cols.current.set(ek, col)
      floraDirty.current = true
      queueRemesh(gx, gz)
      if (!edits.current.has(ek)) {
        loadColumn(SEED, gx, gz).then(saved => {
          if (!saved) { edits.current.set(ek, new Map()); applyGenPieces(gx, gz, []); return }
          if (isStale(saved.edits) && !staleWarned.current) {
            staleWarned.current = true
            // ⚠ Wrapped: a wiped or blocked localStorage must not take the warning down with it.
            // Failing closed here would mean the one load that genuinely needed the message is the
            // one that throws.
            let seen: string | null = null
            try { seen = localStorage.getItem(GEN_WARN_KEY) } catch { /* private mode */ }
            if (seen !== String(GENERATOR_VERSION)) {
              try { localStorage.setItem(GEN_WARN_KEY, String(GENERATOR_VERSION)) } catch { /* ignore */ }
              onSay('⚠ the world generator changed — saved edits from an older build may not line up')
            }
          }
          const m = unpackEdits(saved.edits)
          edits.current.set(ek, m)
          const c = cols.current.get(ek)
          if (c && m.size) { applyEdits(c, m); refreshUniform(c); queueRemesh(gx, gz); flora.invalidate(ek); floraDirty.current = true }
          // Pieces come back with their blocks. Occupancy is NOT re-written here — it is already in
          // the block diff, because placing a piece wrote STRUCTURE through `setVoxel`, which is a
          // recorded edit. Writing it twice would be harmless but would double the save.
          if (saved.pieces?.length) {
            piecesByCol.current.set(ek, saved.pieces)
            placements.current = [...placements.current, ...saved.pieces]
            pieces.sync(placements.current)
          }
          if (saved.genRemoved?.length) genRemovedByCol.current.set(ek, [...saved.genRemoved])
          // Chest contents come back with their blocks, which is the whole reason they live in this
          // record. ⚠ Never clobber a grid already in the map: this load is async, and a chest the
          // player has ALREADY opened and filled in the seconds since the column meshed would
          // otherwise be overwritten by the version on disk.
          if (saved.chests) {
            const have = chestsByCol.current.get(ek) ?? {}
            for (const [ck, g] of Object.entries(saved.chests)) if (!have[ck]) have[ck] = g as Slots
            chestsByCol.current.set(ek, have)
          }
          // Station jobs, same async-clobber guard as chests: a bench the player has ALREADY
          // loaded in the seconds since the column meshed must not be overwritten by the version
          // on disk, or his logs go back into a job he already replaced.
          if (saved.jobs) {
            const have = jobsByCol.current.get(ek) ?? {}
            for (const [jk, j] of Object.entries(saved.jobs)) if (!have[jk]) have[jk] = j as StationJob
            jobsByCol.current.set(ek, have)
          }
          applyGenPieces(gx, gz, saved.genRemoved ?? [])
        })
      }
      for (const [ddx, ddz] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const)
        queueRemesh(gx + ddx, gz + ddz)
      adopted++
    }

    // ── request what is missing, nearest first ───────────────────────────────────────────────
    const R = settings.viewRadius
    const want: [number, number, number][] = []
    for (let dz = -R; dz <= R; dz++) for (let dx = -R; dx <= R; dx++) {
      const d = dx * dx + dz * dz
      if (d > R * R) continue
      const kk = key(cx + dx, cz + dz)
      if (!cols.current.has(kk) && !requested.current.has(kk)) want.push([d, cx + dx, cz + dz])
    }
    want.sort((a, b) => a[0] - b[0])
    const w = worker.current
    for (const [, gx, gz] of want) {
      if (w) {
        if (inflight.current! >= 4) break
        requested.current.add(key(gx, gz))
        inflight.current!++
        w.postMessage({ type: 'request', cx: gx, cz: gz })
      } else {
        // No worker (construction failed): generate here so the world still exists.
        if (performance.now() - t0 > 10) break
        requested.current.add(key(gx, gz))
        cols.current.set(key(gx, gz), makeColumn(gx * SECTION, gz * SECTION, SEED))
        queueRemesh(gx, gz)
        for (const [ddx, ddz] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const)
          queueRemesh(gx + ddx, gz + ddz)
      }
    }

    // Mesh what arrived, nearest first, inside a frame budget. 12ms leaves a 60Hz frame most of its
    // time for everything else while still filling a fresh load radius in a few seconds.
    drainRemeshQueue(cx, cz, 12)

    const nowMs = Date.now()
    // ── pots come due ────────────────────────────────────────────────────────────────────────
    // Swept from the CLOCK, not by scanning the world: the clock already knows every planted pot's
    // position, so a garden of them costs a handful of map reads instead of a search. A pot outside
    // the load radius is skipped, not lost — `setVoxel` needs its column, and the clock keeps the
    // stamp until it can be flipped.
    if (potTick.current < nowMs) {
      potTick.current = nowMs + 3000
      for (const q of potsDue(pot.clock(), nowMs)) {
        if (voxel(q.x, q.y, q.z) !== MAT.POT_SEEDED) continue
        setVoxel(q.x, q.y, q.z, MAT.POT_BLOOM)
      }
    }

    // ── ★ SAPLINGS COME UP ───────────────────────────────────────────────────────────────────
    // Swept from the CLOCK, like the pots, and for the same reason: the clock already knows every
    // planted sapling's position, so a plantation costs a few map reads instead of a world search.
    //
    // ⚠ EVERY RULE IS RE-ASKED HERE rather than cached from planting time. That is sapling.ts's
    // central point: the world moves between planting and growing, so a shed built over a sapling
    // has to stop it — and a blocked sapling WAITS. Nothing below deletes an entry except a tree
    // actually appearing, or the block being gone.
    if (saplingTick.current < nowMs) {
      saplingTick.current = nowMs + 3000
      for (const k of Object.keys(saplingClock.current)) {
        const [sx, sy, sz] = k.split(',').map(Number)
        const mat = voxel(sx, sy, sz)
        // Dug up, broken, or its column is not loaded. A missing block with a live column means the
        // player removed it, so the stamp goes; an unloaded column reads as AIR too, so the guard
        // is the column, not the material.
        const col = cols.current.get(key(Math.floor(sx / SECTION), Math.floor(sz / SECTION)))
        if (!col) continue
        const sp = saplingSpecies(mat)
        if (!sp) { delete saplingClock.current[k]; saveSaplings(); continue }
        if (blockedBy(saplingClock.current, voxel, openToSky, sp, sx, sy, sz, nowMs) !== null) continue

        // ★ THE TREE IS GROWN BY THE GENERATOR ITSELF (`growTreeCells`), never by a second
        // tree-drawing routine here. A planted goldwood is byte-identical to a wild one because it
        // IS one — same walk, same crown, same lump seeds.
        //
        // ⚠ Height is hashed from POSITION, not rolled now: the clearance check reserved for the
        // species' tallest, and a fresh random roll could still surprise a ceiling that had been
        // approved. Position also means the same sapling always becomes the same tree.
        const start: TreeStart = {
          x: sx, z: sz, species: sp,
          height: plantedHeight(sp, sx, sz),
          seed: (sx * 73856093) ^ (sz * 19349663),
        }
        delete saplingClock.current[k]
        saveSaplings()
        // The sapling's own cell is where the trunk's base goes, so clear it first — `growTreeCells`
        // writes a log there and a stale sapling underneath would survive as a hidden block.
        setVoxel(sx, sy, sz, AIR)
        for (const c of growTreeCells(start, sy - 1)) setVoxel(c.x, c.y, c.z, c.mat)
        onSay(`a ${sp.id} has grown`)
      }
    }

    // ── flora sync: once the streaming burst is quiet, rebuild the ground cover ──────────────
    // Deferred behind `incoming` so a fresh load radius pays for flora ONCE at the end, not per
    // adopted column. The probe walks from the generated surface to the ACTUAL one (edits move
    // it), then demands topsoil with air above — which is what keeps tufts off roads, crust,
    // grey dither, placed blocks and dug holes without flora.ts knowing materials exist.
    if (floraDirty.current && incoming.current!.length === 0) {
      floraDirty.current = false
      const list: { key: string; x0: number; z0: number }[] = []
      for (const kk of cols.current.keys()) {
        const [gx, gz] = kk.split(',').map(Number)
        list.push({ key: kk, x0: gx * SECTION, z0: gz * SECTION })
      }
      flora.sync(list, SEED, (fx, fz) => {
        const fcx = Math.floor(fx / SECTION), fcz = Math.floor(fz / SECTION)
        const c = cols.current.get(key(fcx, fcz))
        if (!c) return null
        let y = c.heightAt(fx - fcx * SECTION, fz - fcz * SECTION)
        let guard = 8
        // Walk to the ACTUAL ground (edits move it). Ground cover reads as air to this walk — it
        // is what we are looking FOR, so stopping on it would report the plant as the ground.
        const clear = (m: number) => m === AIR || isPlant(m)
        while (guard-- > 0 && !clear(voxel(fx, y + 1, fz))) y++
        while (guard-- > 0 && y > 1 && voxel(fx, y, fz) === AIR) y--
        if (voxel(fx, y, fz) !== MAT.TOPSOIL) return null
        const m = voxel(fx, y + 1, fz)
        if (!isPlant(m)) return null
        // A tuft on a slumped lip grows from the half-height top, not from where a full block
        // would have been — otherwise 19% of the garden's ground cover hovers half a voxel up.
        // Fractional by design: the spot's y is only ever used to place a root.
        const gy = isHalfCell(c, fx - fcx * SECTION, y, fz - fcz * SECTION) ? y - 0.5 : y
        const kind = m === MAT.TUFT ? FLORA.TUFT : m === MAT.TALL_GRASS ? FLORA.TALL : FLORA.FLOWER
        return { y: gy, kind, variant: plantVariant(fx, fz, SEED, kind) }
      })
    }

    // Until the spawn column exists every lookup returns AIR, so gravity would drop the player
    // through a world that has not generated yet. Hold until there is ground beneath.
    if (!settled.current) {
      // Probes the column UNDER THE PLAYER (was hardcoded to spawn) — at boot they are the same
      // spot, and generalizing is what lets the console's tp reuse this gate at any destination.
      if (isSolid(voxel(Math.floor(p.x), Math.floor(p.y) - 3, Math.floor(p.z)))) settled.current = true   // real ground, not the phantom floor
      else { onPos(p, 0); onStats(`${cols.current.size} columns · generating…`); return }
    }

    // ── the gate ──────────────────────────────────────────────────────────────────────────────
    // Built once its footprint's columns are all loaded (see GATE_COLS's header for why "all", not
    // just the centre one) — sealed or already open depending on what the save says at that moment,
    // so a returning keeper who finished the tutorial elsewhere never sees it reseal. Opened exactly
    // once more if the quest completes later in this same session.
    if (!gateBuilt.current && GATE_COLS.every(ck => cols.current.has(ck))) {
      const baseY = columnHeight(GATE_X, GATE_Z, SEED)
      const done = tutorial.current.stage === 'done'
      for (const c of gateCells(baseY)) {
        const mat = c.doorway ? (done ? AIR : MAT.STONE) : MAT.STONE
        if (voxel(c.x, c.y, c.z) !== mat) setVoxel(c.x, c.y, c.z, mat)
      }
      gateBuilt.current = true
      gateOpened.current = done
    } else if (gateBuilt.current && !gateOpened.current && tutorial.current.stage === 'done') {
      const baseY = columnHeight(GATE_X, GATE_Z, SEED)
      for (const c of gateCells(baseY)) if (c.doorway) setVoxel(c.x, c.y, c.z, AIR)
      gateOpened.current = true
    }

    // ── movement — play3d's locomotion on voxel collision (see locomotion.ts) ────────────────
    // The camera is DERIVED (feet + eased eye), never the physics primitive: the eye dips through
    // a slide without the collision box following it into the floor.
    const k = keys.current
    const aim = vAim.current
    camera.getWorldDirection(aim)
    const fwd = vFwd.current.copy(aim); fwd.y = 0; fwd.normalize()
    const right = vRight.current.crossVectors(fwd, UP)
    const wish = vWish.current.set(0, 0, 0)
    if (k.KeyW) wish.add(fwd)
    if (k.KeyS) wish.sub(fwd)
    if (k.KeyD) wish.add(right)
    if (k.KeyA) wish.sub(right)
    if (wish.lengthSq() > 0) wish.normalize()

    const lc = loco.current
    if (fly.current) {
      const speed = (k.ShiftLeft ? 44 : 20)
      wish.multiplyScalar(speed)
      if (k.Space) wish.y += speed
      if (k.ControlLeft) wish.y -= speed
      p.addScaledVector(wish, dt)
      // Keep the walker under the camera so dropping out of fly resumes physics where you are.
      // stepSmooth first: py is derived FROM the camera here, so an unpaid step debt would
      // subtract itself out of the body's feet and sink the walker half a slab into the floor.
      lc.stepSmooth = 0
      lc.px = p.x; lc.py = p.y - lc.eye; lc.pz = p.z
      lc.vy = 0; lc.airborne = true; lc.hvx = 0; lc.hvz = 0
    } else {
      tickLocomotion(lc, {
        mvX: wish.x, mvZ: wish.z,
        fwdX: fwd.x, fwdZ: fwd.z, rightX: right.x, rightZ: right.z,
        jumpKey: !!k.Space,
        // Shift is CROUCH/SLIDE now, exactly as in play3d — its life as a sprint key here is what
        // made the slide-jump muscle memory read as "a dash of some sort". Run speed is automatic.
        crouchKey: !!k.ShiftLeft || !!k.ShiftRight,
        dt,
      }, solidProbe)
      p.set(lc.px, eyeY(lc), lc.pz)
      if (lc.py < -20) {
        const feet = columnHeight(SPAWN_X, SPAWN_Z, SEED) + 1
        lc.px = SPAWN_X + 0.5; lc.py = feet; lc.pz = SPAWN_Z + 0.5; lc.vy = 0; lc.hvx = 0; lc.hvz = 0; lc.stepSmooth = 0
        p.set(lc.px, eyeY(lc), lc.pz)
        settled.current = false
      }
    }

    // ── what are we looking at ───────────────────────────────────────────────────────────────
    const hit = raycast(p.x, p.y, p.z, aim.x, aim.y, aim.z, REACH, voxel)
    const hl = highlight.current
    if (hl) {
      hl.visible = !!hit
      if (hit) hl.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5)
    }

    // ── ★ THE THREE AIMED VERBS (2026-08-13, Alex: "only work when on the item/person you are
    //    currently looking at or highlighting") ───────────────────────────────────────────────
    // Greg, the bench and a presence in the mist were all proximity-only — a radius, a box scan and
    // a nearest-within-6. Blocks were never wrong (chest/pot/place read the reticle), so the world
    // was answering two different questions depending on whether the thing you pointed at happened
    // to be made of voxels. All three now ask `aim.ts` the same one.
    //
    // ★ THEY SIT HERE, BELOW THE RAYCAST, AND THAT IS THE POINT. `hit` is this frame's crosshair,
    // measured on this frame's `aim`, after movement. Greg's check used to run in the streaming
    // section ~70 lines up — before the player had moved — and a second ray cast for the entities
    // would let the wireframe and the prompt disagree about what is in front of you.
    // `hit.distance` is the occluder: no talking through the gate wall.
    const blockDist = hit ? hit.distance : Infinity
    {
      const near = aimedAt(p.x, p.y, p.z, aim.x, aim.y, aim.z, GREG_BOX, GREG_TALK_RANGE, blockDist)
      if (near !== lastNearGreg.current) { lastNearGreg.current = near; onNearGreg(near) }
    }
    {
      // The bench is a BLOCK, so it needs no box of its own — "the cell the reticle is on is a
      // crafting table" is the whole test, and it is the same read `rightClickIntent` already does
      // for a chest. This also retires a ±4×6×9 voxel scan that ran twice a second forever.
      const found = !!hit && voxel(hit.x, hit.y, hit.z) === MAT.CRAFT_TABLE
      if (found !== lastNearTable.current) { lastNearTable.current = found; onNearTable(found) }
    }
    {
      // Aim AND range: `aimed` says the crosshair is on a silhouette, `nearest` says you walked to
      // it. A presence is legible from across the patch on purpose (the consent design), so without
      // the range half you could call out a spar from the far side of the fog.
      const r = sparring ? null : (mist.nearest() && mist.aimed(p.x, p.y, p.z, aim.x, aim.y, aim.z, SPAR_RANGE, blockDist))
      const id = r ? `${r.patch.x},${r.patch.z},${r.species}` : null
      if (id !== lastNearMist.current) { lastNearMist.current = id; onNearMist(r ?? null) }
    }

    // ── build mode: ghost, place, deconstruct ────────────────────────────────────────────────
    if (build) {
      const def = pieceDef(PIECES[pieceIdx].id)!
      // ★ AUTO-FACING (2026-08-08, Alex's ask): pieces orient from where you LOOK, live — turn to
      // face a different wall and the ghost turns with you. `rot` (the R key) is a persistent
      // manual quarter-turn ON TOP of that, not the whole job. The mapping is anchored to the
      // stair: authored rising toward −Z at rot 0, instanced at −rot·π/2 about Y, so rot 1 rises
      // toward +X — and "rises AWAY from the player" (walkable the way you're going, doors facing
      // you) works out to rot = 2 − round(yaw / 90°), mod 4. Quantized from the same `aim` the
      // raycast uses, so the ghost and the crosshair can never disagree about "forward".
      const yawRot = (2 - Math.round(Math.atan2(aim.x, aim.z) / (Math.PI / 2)) + 8) % 4
      const face = ((yawRot + rot) % 4) as Rotation
      // ★ ONE PREVIEW, NOT TWO (Alex, 2026-08-08: "it would preview a block away from the
      // highlighted block"). The wireframe marks the cell your crosshair HITS; the ghost sits in
      // the empty cell you place AGAINST — one apart by design, but showing both reads as the
      // ghost being offset. In build mode the ghost IS the preview, so the wireframe only stays
      // up when it means something of its own: aiming at a placed piece, where it marks what LMB
      // deconstructs (an O(1) occupancy read, not a placement scan).
      if (hl) {
        const hm = hit ? voxel(hit.x, hit.y, hit.z) : AIR
        hl.visible = hm === STRUCTURE || hm === STRUCTURE_HALF
      }
      // The ghost sits in the EMPTY cell before what you are looking at — the same `px,py,pz` that
      // block placement uses, so both verbs agree about where "in front of" is.
      const target: Placement | null = hit ? { pieceId: def.id, x: hit.px, y: hit.py, z: hit.pz, rot: face } : null
      const fits = !!target && canPlace(target, def, (x, y, z) => voxel(x, y, z))
      const afford = canAfford(def, id => countItem(inv.current!, id))
      if (target) pieces.setGhost(def.id, target.x, target.y, target.z, face, fits && afford)
      else pieces.hideGhost()

      if (target && mouse.current.right && fits && afford) {
        for (const c of def.cost) removeItems(inv.current!, c.itemId, c.count)
        // ★ OCCUPANCY INTO THE VOXEL GRID — this is what makes collision free. Only the SOLID cells
        // are written, so a doorway stays walkable and a stair can be climbed.
        for (const c of cellsOf(target, def)) if (c.solid) setVoxel(c.x, c.y, c.z, def.halfHeight ? STRUCTURE_HALF : STRUCTURE)
        placements.current.push(target)
        const ok = colOf(target.x, target.z)
        piecesByCol.current.set(ok, [...(piecesByCol.current.get(ok) ?? []), target])
        dirtySaves.current.add(ok)
        pieces.sync(placements.current)
        onInvChange()
        mouse.current.right = false
      }

      // Deconstruct: aim at ANY cell the piece occupies, not just its origin.
      if (hit && mouse.current.left) {
        const found = placementAt(placements.current, hit.x, hit.y, hit.z)
        if (found) {
          const fdef = pieceDef(found.pieceId)!
          for (const c of cellsOf(found, fdef)) if (c.solid) setVoxel(c.x, c.y, c.z, AIR)
          // Full refund while the loop is unproven — consequence-free experimenting is what you want
          // while judging feel. A dial, not a ruling.
          for (const c of fdef.cost) give(inv.current!, c.itemId, c.count)
          placements.current = placements.current.filter(p => p !== found)
          const fk = colOf(found.x, found.z)
          const genId = (found as Placement & { gen?: string }).gen
          if (genId) {
            // A generated piece: what persists is its ABSENCE. The occupancy edit self-erases
            // (setVoxel's diff against generated AIR is a no-op), so the tombstone is the record.
            genRemovedByCol.current.set(fk, [...(genRemovedByCol.current.get(fk) ?? []), genId])
          } else {
            piecesByCol.current.set(fk, (piecesByCol.current.get(fk) ?? []).filter(p => p !== found))
          }
          dirtySaves.current.add(fk)
          pieces.sync(placements.current)
          onInvChange()
          mouse.current.left = false
        }
      }

      onLook(hit ? { name: `${def.name}${!afford ? ' — need materials' : fits ? '' : ' — blocked'}`, progress: 0, refused: !fits || !afford } : null)
      onPos(p, screenHeading(aim.x, aim.z))
      if (++frame.current % 10 === 0) {
        const info = gl.info
        onStats(`${cols.current.size} col · ${placements.current.length} pieces · geo ${info.memory.geometries} prog ${info.programs?.length ?? 0} · BUILD`)
      }
      return
    }
    pieces.hideGhost()

    // ── mine ─────────────────────────────────────────────────────────────────────────────────
    // ★ THE TOOL IS CHOSEN BY THE BLOCK, NOT BY A HOTKEY. Every block declares its skill, and the
    // matching equipped tool supplies the tier and speed — so a spike cuts rock and a blade cuts
    // wood without the player switching anything. That is the tile game's model, unchanged; it just
    // never had a world where both mattered on the same swing.
    if (hit && mouse.current.left && !weaponDrawn) {
      const hitDef = blockDef(hit.material)
      // ★ TOOLS ARE NOT SOMETHING YOU SELECT — THE BLOCK CHOOSES (Alex, 2026-08-07, late).
      // This briefly went the other way ("the tool in hand wins, auto-pick is the fallback") the
      // same day, on the theory that a selected tool should mean something. Playtest reversed it:
      // tools left the hotbar entirely and became GAUGES, so there is no hand left to hold one in.
      // Back to pure auto-pick, now honouring `fastSkill` too — a spade auto-raises on soil the
      // same way a spike auto-raises on stone, instead of fastSkill only mattering when held.
      // The registry's gate semantics (`breakSeconds`, `canBreak`) are untouched: this only decides
      // WHICH family gets asked, never whether the ask succeeds.
      const wantSkill: BlockSkill = hitDef?.skill ?? hitDef?.fastSkill ?? null
      const equipped = wantSkill ? getEquippedTool(tools.current!, wantSkill as never) : undefined
      const eDef = equipped ? getToolDef(equipped) : undefined
      /**
       * ── ★ AN EMPTY HAND MUST NOT CLAIM THE TOOL'S SKILL (2026-08-12, Alex: mining is "way too
       * fast without upgraded tools") ─────────────────────────────────────────────────────────
       * This passed `wantSkill` to `breakSeconds` whether or not a tool was actually equipped, and
       * on an UNGATED block that is the whole discount: `breakSeconds` reads `toolSkill ===
       * fastSkill` as "holding the right family" and returns `hardness * 0.55`. So bare hands dug
       * soil, sand, grass and path at the full spade rate from the first second of the game.
       *
       * ★ THE TELL IS WHAT IT DID TO THE SPADE, not to the dirt. `tools.ts` calls the spade "a SPEED
       * tier on top" of hands, and the first tool a new keeper should reach for — but hands were
       * already collecting that tier, so a Goldwood Spade bought a 0.9 speedBonus and nothing else:
       * **10% instead of ~50%.** The upgrade was invisible, which is exactly the complaint. A
       * mechanic can be perfectly implemented in the registry and still be dead because a caller
       * hands it the wrong argument.
       *
       * Gated blocks are unaffected: `ensureBasicTools` guarantees a worn blade, spike and rinstick,
       * so those three families always have a tool and `wantSkill` still reaches the gate. Farming
       * is the only family with no basic tool, which is precisely the case this restores — and it
       * is deliberate, since hands must always be able to dig or a fresh keeper is stranded.
       */
      toolSkill.current = eDef ? wantSkill : null
      toolTier.current = eDef?.tier ?? 0
      // The GAUGE still names the family the block wants, tool or not — it answers "what is this
      // block asking for", which is the one thing that explains an empty hand being slow.
      if (lastTool.current !== wantSkill) { lastTool.current = wantSkill; onTool(wantSkill) }
      const r = tickBreak(breaking.current, hit, dt, toolTier.current!, toolSkill.current!, eDef?.speedBonus ?? 1)
      breaking.current = r.state
      if (r.broken) {
        // ── ★ THE FELL VERB — a tree is ONE object (Alex, 2026-08-13) ────────────────────────
        // *"lets make the trees one object that drops rng loot when felled logs included."* A swing
        // that lands on any log takes the WHOLE trunk, pays once, and is done — rather than the
        // player mining a tree the way they mine a wall.
        //
        // ⚠ RESOLVED FIRST, because the XP award below needs it. Felling pays `fellXP`, which is
        // the per-block award times the trunk's voxel count — i.e. exactly what chopping it cell by
        // cell paid yesterday. Awarding the per-block amount ONCE for a whole tree would have cut
        // forestry progression by ~90% and looked like nothing at all.
        //
        // ⚠ FALLS BACK TO THE ORDINARY BLOCK PATH if the tree cannot be resolved. A log with no
        // owner is not impossible — a save from before this existed, a generator retune — and the
        // honest failure is "you got one log", never "the swing did nothing".
        const felled = isLogMat(hit.material)
          ? treeOwning(SEED, SECTION, hit.x, hit.y, hit.z, (tx, tz) => {
              const tcx = Math.floor(tx / SECTION), tcz = Math.floor(tz / SECTION)
              const c = cols.current.get(key(tcx, tcz))
              return c ? c.heightAt(tx - tcx * SECTION, tz - tcz * SECTION) : null
            })
          : null

        // ★ XP GOES TO THE BLOCK'S SKILL. Mining ore trains Prospecting, felling a tree trains
        // Forestry — the two halves of gathering finally exist in the same world, which is the whole
        // reason this port was worth doing before combat or NPCs.
        if (wantSkill && skills.current![wantSkill as keyof SkillSet]) {
          const sk = skills.current![wantSkill as keyof SkillSet]
          // XP scales with hardness, so the deep tiers train faster than topsoil — the ladder the
          // registry already encodes, reused rather than restated.
          const res = addSkillXP(sk, felled ? fellXP(felled.start)
            : Math.max(4, Math.round((hitDef?.hardness ?? 1) * 12)))
          if (res.leveled) {
            onLevel(`${wantSkill} ${res.newLevel}${getMilestone(res.newLevel) ? ' — ' + getMilestone(res.newLevel) : ''}`)
          }
          onSkill({ id: wantSkill, level: sk.level, xp: sk.xp, next: xpForSkillLevel(sk.level) })
        }
        // ── ★ THE FELL VERB — a tree is ONE object (Alex, 2026-08-13) ────────────────────────
        // *"lets make the trees one object that drops rng loot when felled logs included."* So a
        // swing that lands on any log takes the WHOLE trunk, pays the node's payout once, and is
        // done — rather than the player mining a tree the way they mine a wall.
        //
        // ★ IT PAYS EXACTLY WHAT CHOPPING CELL BY CELL PAID (`fellTree` → one log per trunk voxel,
        // asserted in tree-node.test.ts). The building grammar is priced against the old yield, so
        // a node that paid less would leave every recipe working and every build unaffordable.
        //
        // ⚠ FALLS BACK TO THE ORDINARY BLOCK DROP if the tree cannot be resolved. A log with no
        // owner is not impossible — a player-placed log one day, a generator retune, a save from
        // before this existed — and the honest failure there is "you got one log", never "the swing
        // did nothing". Silence would read as broken input.
        // ★ The block bursts into an ENTITY on the floor, it does not teleport into the satchel.
        // Straight-to-inventory works and feels like nothing happened; seeing the shard fall is
        // what tells the player the swing landed and what the vein actually yielded.
        if (felled) {
          const { drops: paid } = fellTree(felled.start, Math.random)
          // Dropped at the BASE, not at the cell that was hit. You fell a tree from its foot and
          // the pile belongs where you are standing — a payout raining from a limb you cut at head
          // height lands in the canopy and reads as lost.
          const base = felled.cells[0]
          for (const d of paid) drops.current.push(spawnDrop(d.itemId, d.count, base.x, base.y, base.z))
          const extra = paid.length - 1
          onSay(extra > 0
            ? `the ${felled.start.species.id} comes down — ${paid[0].count} logs and ${extra} more`
            : `the ${felled.start.species.id} comes down — ${paid[0].count} logs`)
        } else {
          for (const d of dropsFor(hit.material)) drops.current.push(spawnDrop(d.itemId, d.count, hit.x, hit.y, hit.z))
        }
        // ★ A BROKEN CHEST SPILLS WHAT IT HELD — before `setVoxel`, which is what drops the record.
        // It spills rather than refusing to break: the pile is visible, `tickDrops`' capacity gate
        // already leaves what will not fit lying on the ground, and a container you cannot pick up
        // without emptying it by hand first is a trap, not a rule.
        if (hit.material === MAT.CHEST) {
          const held = spillChest(chestAt(hit.x, hit.y, hit.z))
          for (const d of held) drops.current.push(spawnDrop(d.itemId, d.count, hit.x, hit.y, hit.z))
          if (held.length) onSay(`the chest spills — ${held.reduce((n, d) => n + d.count, 0)} items on the ground`)
        }
        // ★ AND A BROKEN BENCH HANDS BACK ITS JOB — finished runs at the milled rate, unstarted
        // runs as the input you paid. Same placement and same argument as the chest above: before
        // `setVoxel`, which is what drops the record. A station you cannot pick up without emptying
        // it by hand first is a trap, and silently eating a stack of logs for a mis-swung pickaxe
        // is worse than either.
        const brokeStation = stationOf(hit.material)
        if (brokeStation) {
          const k = colOf(hit.x, hit.z)
          const shop = jobsByCol.current.get(k)
          if (shop?.[stationKey(hit.x, hit.y, hit.z)]) {
            // ⚠ AT ITS OWN STATION — rate AND yield. Salvaging a sawmill's job against the bench's
            // 12s would refund runs it had already finished, and paying a cutter's job at the
            // bench's yield would quietly shave the bonus off work it had genuinely done. Both are
            // properties of the block you just broke, which is why the whole def travels.
            const brokeDef = STATIONS[brokeStation]
            const { drops: owed } = salvageStation(shop, stationKey(hit.x, hit.y, hit.z), Date.now(), brokeDef)
            for (const d of owed) drops.current.push(spawnDrop(d.itemId, d.count, hit.x, hit.y, hit.z))
            if (owed.length) onSay(`${brokeDef.name.toLowerCase()} gives up its work — ${owed.reduce((n: number, d: { count: number }) => n + d.count, 0)} items on the ground`)
          }
        }
        if (felled) {
          // ⚠ TOP DOWN. Every write funnels through `setVoxel`, which asks `orphanedLeaves` what
          // the removal stranded — and that question is only correct against the world as it then
          // is. Taking the base out first would strand the whole canopy on the first call and then
          // re-scan it on every remaining cell; from the top, each step orphans the little that
          // step actually released, and `enqueueLeaves` keeps the earliest time either way.
          for (const c of [...felled.cells].sort((a, b) => b.y - a.y)) setVoxel(c.x, c.y, c.z, AIR)
        } else {
          setVoxel(hit.x, hit.y, hit.z, AIR)
        }
        // ★ Tutorial 'cut' step — any log, not one species (see LOG_MATERIALS's header).
        if (LOG_MATERIALS.has(hit.material)) onQuestEvent('cut')
        breaking.current = null
      }
    } else {
      if (!mouse.current.left) breaking.current = null
      // Not mining this frame (nothing under the reticle, LMB up, or weapon drawn) — clear the
      // gauge glow. Same dedup guard as above, so releasing LMB repeatedly does not spam `onTool`.
      if (lastTool.current !== null) { lastTool.current = null; onTool(null) }
    }

    // ── use, or place ────────────────────────────────────────────────────────────────────────
    // ⚠ NOT gated on `selItem` — USING a block is not placing one (2026-08-11). This branch once
    // required something in hand, so the very first thing a player does with a chest failed: you
    // place your only chest, the slot empties, `selItem` goes null, and the right-click that should
    // open it fell through the whole block. Empty-handed is the NORMAL way to open a container.
    // `rightClickIntent` (interact.ts) now owns that decision so an oracle can hold it; placing
    // still needs an item and says so on its own branch.
    if (hit && mouse.current.right && !weaponDrawn) {
      const potMat = voxel(hit.x, hit.y, hit.z)
      const intent = rightClickIntent(potMat, selItem,
        selItem === 'mana_seed' && countItem(inv.current!, selItem) > 0)
      // ── ★ THE CHEST OPENS ON RIGHT-CLICK, and is answered FIRST ────────────────────────────
      // A chest is a thing you USE, and the block in your hand must not be dropped onto it by the
      // same click that opens it. Handing the whole panel upward (rather than opening one down
      // here) keeps every cursor surface in one place — the bag, the bench and the chest are the
      // same panel, so they cannot disagree about what a move means.
      if (intent === 'open') {
        // `touch` is bound to THIS chest's column rather than handed up as a coordinate the caller
        // has to remember — the one call that must not be forgotten cannot then be made wrong.
        onOpenChest({
          x: hit.x, y: hit.y, z: hit.z,
          slots: chestAt(hit.x, hit.y, hit.z),
          touch: () => touchChest(hit.x, hit.z),
        })
        mouse.current.right = false
      } else if (intent === 'work') {
        // Same shape as the chest above and for the same reason: the bench hands its POSITION and a
        // bound `touch` upward, never a copy of the job. The panel edits through `workshop.ts`'s
        // pure functions, so the only thing the host owes it is where the bench is.
        // The KIND travels with the position: the panel must never re-derive which station this
        // is from anything but the block that was actually aimed at.
        const kind = stationOf(potMat)
        if (kind) onOpenStation({
          x: hit.x, y: hit.y, z: hit.z, kind,
          job: jobAt(hit.x, hit.y, hit.z),
          commit: (shop: Workshop) => setJob(hit.x, hit.y, hit.z, shop),
        })
        mouse.current.right = false
      } else if (intent === 'plant') {
        removeItems(inv.current!, 'mana_seed', 1)
        setVoxel(hit.x, hit.y, hit.z, MAT.POT_SEEDED)
        pot.clock()[potKey(hit.x, hit.y, hit.z)] = Date.now()
        pot.save()
        onInvChange()
        onSay('✦ the seed is in the soil — give it a few minutes')
        mouse.current.right = false
      } else if (intent === 'peek') {
        const p01 = potProgress(pot.clock(), hit.x, hit.y, hit.z, Date.now())
        onSay(`the seed is still closed — ${Math.floor(p01 * 100)}%`)
        mouse.current.right = false
      } else if (intent === 'harvest') {
        // ★ No prompt and no pick: canon has the spirit choose the keeper, so this only announces.
        const born = bloomSpirit()
        pot.gain(born)
        delete pot.clock()[potKey(hit.x, hit.y, hit.z)]
        pot.save()
        setVoxel(hit.x, hit.y, hit.z, MAT.POT)
        onSay(`✦ a young ${speciesDisplayName(born.species)} chose you!`)
        mouse.current.right = false
      } else if (intent === 'place') {
      // Placing — and ONLY placing — needs something in your hand, which `place` already asserts.
      const held = selItem!
      const mat = materialForItem(held)
      // Refuse to place inside your own body — the classic way to entomb yourself.
      const inPlayer = Math.floor(p.x) === hit.px && Math.floor(p.z) === hit.pz
        && (Math.floor(p.y) === hit.py || Math.floor(p.y - 1.62) === hit.py)
      // ── ★ SLABS: WHICH HALF, AND WHEN TWO BECOME ONE (2026-08-11) ──────────────────────────
      // Merging first, because it targets the cell you AIMED AT rather than the empty one beside
      // it: a slab meeting its opposite half is a whole block. Deliberately forgiving about which
      // face you clicked — the intent is unambiguous, and being strict here just makes players
      // fight the reticle. Same base material only; a stone slab does not complete a soil one.
      const aimed = voxel(hit.x, hit.y, hit.z)
      // `materialForItem` always yields a BOTTOM slab, so "opposite halves" needs no test — a slab
      // in hand always completes a slab in the world, whichever half that one occupies.
      const merging = mat !== undefined && isHalfMat(mat) && isHalfMat(aimed) && baseOf(aimed) === baseOf(mat)
      if (merging && countItem(inv.current!, held) > 0) {
        removeItems(inv.current!, held, 1)
        setVoxel(hit.x, hit.y, hit.z, baseOf(aimed))
        onInvChange()
        mouse.current.right = false
      } else if (mat !== undefined && isSaplingMat(mat)
                 && !canPlant(voxel, openToSky, hit.px, hit.py, hit.pz)) {
        // ── ★ A SAPLING REFUSES BAD GROUND, AND SAYS SO ──────────────────────────────────────
        // `canPlant` is the generator's own rule (topsoil, open sky) — refusing silently would read
        // as a broken right-click, which is exactly how the cast refusals were being lost before
        // `onSay` existed. Clearance is NOT checked here on purpose: you may plant somewhere
        // cramped and the sapling waits. See sapling.ts.
        onSay(voxel(hit.px, hit.py - 1, hit.pz) === MAT.TOPSOIL
          ? 'it needs open sky to grow'
          : 'a sapling only takes in soil')
        mouse.current.right = false
      } else if (mat !== undefined && !inPlayer && countItem(inv.current!, held) > 0 && voxel(hit.px, hit.py, hit.pz) === AIR) {
        removeItems(inv.current!, held, 1)
        // A slab takes the half you pointed at. The ray's own hit point decides it: land in the
        // upper half of the target cell and the slab goes up there, so a slab staircase is built
        // by aiming, not by a modifier key.
        let put = mat
        if (isHalfMat(mat)) {
          // The face you clicked already answers it, and only a SIDE hit is ambiguous:
          //   · clicked a block's top face  → the slab rests on it        → bottom half
          //   · clicked a block's underside → the slab hangs beneath it   → top half
          //   · clicked a side face         → the aim point's own height decides
          if (hit.py > hit.y) put = mat
          else if (hit.py < hit.y) put = mat | TOP_BIT
          else {
            const hy = p.y + aim.y * hit.distance
            put = (hy - Math.floor(hy)) >= 0.5 ? (mat | TOP_BIT) : mat
          }
        }
        setVoxel(hit.px, hit.py, hit.pz, put)
        // The material is the state; the clock holds the one thing it cannot — WHEN.
        if (isSaplingMat(put)) {
          saplingClock.current[saplingKey(hit.px, hit.py, hit.pz)] = Date.now()
          saveSaplings()
          onSay('planted — it needs room overhead to come up')
        }
        // ★ Tutorial 'light' step — placing IS the objective, not just holding a lantern.
        if (mat === MAT.MANA_LANTERN) onQuestEvent('light')
        onInvChange()
        mouse.current.right = false   // one block per click, not a firehose
      }
      }
    }

    // ── ★ THROWING SOMETHING AWAY ────────────────────────────────────────────────────────────
    // Alex asked for it the same day the building grammar retired `block_stone`: a bag with no way
    // out is a bag that fills with the last balance change forever.
    //
    // The gate is `selItem`, which the parent already nulls while the weapon is drawn — so the
    // draw-lock that governs every other verb governs this one without a second rule to keep in
    // sync. The slot is re-checked against `selItem` before anything leaves it: a frame can pass
    // between the key and here, and dropping whatever happens to be in the slot NOW would throw the
    // wrong stack if the player scrolled in that gap.
    if (pendingDrop.current) {
      const req = pendingDrop.current
      pendingDrop.current = null
      const slot = inv.current?.slots[selSlot]
      if (selItem && slot && slot.itemId === selItem && slot.count > 0) {
        const itemId = slot.itemId
        const n = req.all ? slot.count : 1
        slot.count -= n
        if (slot.count <= 0) inv.current!.slots[selSlot] = null
        camera.getWorldDirection(vAim.current)
        // Chest height, not eye height: an item that leaves from your eyes reads as spat out.
        drops.current.push(tossDrop(itemId, n, p.x, p.y - 0.45, p.z, vAim.current.x, vAim.current.z))
        onInvChange()
        onSay(`dropped ${n} ${blockDef(materialForItem(itemId) ?? -1)?.name ?? itemId}`)
      }
    }

    // ── ★ THE CANOPY COMES DOWN ──────────────────────────────────────────────────────────────
    // Guarded on a non-empty queue, so a player who has never felled a tree pays one length check
    // per frame — this runs inside the 60Hz loop and the empty case is the case.
    //
    // ⚠ A DUE LEAF WHOSE COLUMN IS NOT LOADED STAYS QUEUED rather than being dropped: `setVoxel`
    // returns silently when the column is missing, so consuming the entry anyway would mean felling
    // a tree, walking out of view while it decayed, and coming back to a canopy that is now
    // permanent — the exact bug this feature exists to remove, hidden behind the fix for it.
    if (decayQueue.current.length) {
      const now = performance.now() / 1000
      const due = dueLeaves(decayQueue.current, now)
      if (due.length) {
        // ── ★ ONE LEAF PER FRAME, AND THIS IS THE WHOLE REASON THE CAP EXISTS ──────────────────
        // `setVoxel` remeshes its column inline — correct for a player mining a block per click,
        // ruinous here. A felled goldwood orphans ~100 leaves at once (measured against the real
        // generator, seed 1337), and dropping them all in the frame they came due would be ~100
        // column remeshes in one frame against a budget of 16.7ms and a warm mesh cost of ~3.4ms
        // per column. That is the slump regression's exact shape: a feature that is fine per-block
        // and catastrophic per-canopy.
        //
        // Draining at one per frame bounds the cost to what mining already costs, and 60 leaves a
        // second still reads as a shower rather than a queue — the tree clears in under two
        // seconds. ⚠ Do NOT "optimise" this by raising the cap; raise it only after measuring the
        // remesh, or by giving decay a batched write path that remeshes each column once.
        //
        // Oldest-due first, so a canopy unravels in the order `orphanedLeaves` staggered it in
        // rather than in whatever order the queue happens to hold.
        due.sort((a, b) => a.at - b.at)
        const fell: PendingLeaf[] = []
        for (const d of due) {
          const cx = Math.floor(d.x / SECTION), cz = Math.floor(d.z / SECTION)
          if (!cols.current.has(key(cx, cz))) continue
          // Leaves drop nothing (registry), so this is a removal and not a loot event — no
          // spawnDrop, and felling a wood cannot be farmed for items.
          if (isLeafMat(voxel(d.x, d.y, d.z))) {
            setVoxel(d.x, d.y, d.z, AIR)
            fell.push(d)
            break                      // ← the cap. One remesh per frame, same as a pick swing.
          }
          // A cell that is no longer a leaf costs nothing to retire, so those do NOT spend the
          // frame's single slot — otherwise a queue full of already-mined cells would take one
          // frame each to notice and the real leaves behind them would crawl.
          fell.push(d)
        }
        if (fell.length) {
          decayQueue.current = withoutLeaves(decayQueue.current, fell)
          // ⚠ THROTTLED, because this drains at 60Hz and `localStorage.setItem` is SYNCHRONOUS —
          // re-serialising the whole queue every frame would put a JSON write of the entire
          // remaining canopy in the frame budget, next to the remesh it already costs. Saved on a
          // 2s tick, and always the moment the queue empties so the finished state is the one on
          // disk. The worst case a crash can cost is two seconds of leaves that fall again later,
          // which is the same outcome as never having decayed them.
          if (!decayQueue.current.length || now - decaySavedAt.current > 2) {
            decaySavedAt.current = now
            saveDecay()
          }
        }
      }
    }

    // ── dropped items ────────────────────────────────────────────────────────────────────────
    // Physics resolves against the voxel grid (not a heightfield), so a shard mined in a cave rests
    // on the cave floor rather than on the surface hundreds of blocks above it.
    if (drops.current.length) {
      const res = tickDrops(drops.current, dt, p.x, p.y - 0.8, p.z,
        (x, y, z) => isSolid(voxelSolid(x, y, z)), undefined,
        // ★ A FULL BAG REFUSES THE PICKUP so the item stays on the ground and stays yours. Before
        // this the drop was consumed and the leftover discarded — walking over a stack you had no
        // room for destroyed it, with nothing on screen to say so.
        (itemId) => roomFor(inv.current!, itemId))
      if (res.picked.length) {
        // ⚠ A FULL BAG MUST SAY SO. `give` returns what did not fit, and every caller here used to
        // discard that — which is how mining past a full inventory destroyed the drop in silence.
        // With 99-stacks that is now 24 × 99 before it can happen, but "rare" is not "never", and a
        // player losing a stack they walked over deserves to be told rather than to wonder.
        // ⏭ The right end state is refusing the PICKUP so the drop stays on the ground; that needs
        // a capacity check inside `tickDrops`, which is the next inventory slice.
        for (const it of res.picked) {
          const left = give(inv.current!, it.itemId, it.count)
          if (left > 0) onSay(`bag full — ${left}× ${itemLabel(it.itemId)} did not fit`)
        }
        onInvChange()
      }
    }
    const dg = dropGroup.current
    if (dg) {
      const live = new Set<number>()
      for (const d of drops.current) {
        live.add(d.id)
        let m = dropMeshes.current.get(d.id)
        if (!m) {
          const mat = materialForItem(d.itemId)
          const colour = mat !== undefined ? (MATERIAL_COLOR[mat] ?? 0xcccccc) : 0xffd479
          let dm = dropMats.current.get(colour)
          if (!dm) {
            dm = new THREE.MeshLambertMaterial({ color: colour, emissive: colour, emissiveIntensity: 0.25 })
            dropMats.current.set(colour, dm)
          }
          m = new THREE.Mesh(dropGeo, dm)
          dg.add(m)
          dropMeshes.current.set(d.id, m)
        }
        // Bob and spin so a shard on a grey cave floor is findable rather than camouflaged.
        m.position.set(d.x, d.y + (d.resting ? 0.06 * Math.sin(d.age * 3) : 0), d.z)
        m.rotation.y = d.age * 1.6
      }
      for (const [id, m] of dropMeshes.current) {
        if (live.has(id)) continue
        // Geometry and material are SHARED — disposing them here would destroy every other drop's
        // rendering. Only the Mesh wrapper is thrown away.
        dg.remove(m)
        dropMeshes.current.delete(id)
      }
    }

    // ── HUD ──────────────────────────────────────────────────────────────────────────────────
    const def = hit ? blockDef(hit.material) : undefined
    onLook(hit && def
      ? {
          name: def.name,
          progress: breaking.current ? breaking.current.progress / breaking.current.required : 0,
          refused: mouse.current.left && !breaking.current && def.hardness !== Infinity,
        }
      : null)
    onPos(p, screenHeading(aim.x, aim.z))
    if (++frame.current % 10 === 0) {
      // ★ GPU RESOURCE COUNTS IN THE HUD. A leak used to announce itself by Chrome blocking the
      // context and the screen going black with no explanation. `programs` is the number that
      // matters — it should be a small constant (one shared chunk material plus one per distinct
      // drop colour). If it climbs while you play, something is allocating materials per object.
      const info = gl.info
      let built = 0
      for (const e of edits.current.values()) built += e.size
      // The place label leads — it is the line's one piece of GAME, the rest is plumbing. Pure
      // function of position, so reading it costs a couple of noise samples every 10th frame.
      const bh = columnHeight(Math.floor(p.x), Math.floor(p.z), SEED)
      // ★ `draws` IS THE PERF NUMBER; `mesh` IS NOT, AND CONFUSING THE TWO COST A SESSION.
      // `drawn.current.size` counts meshes we BUILT — every one of them, including the ones behind
      // the camera. `info.render.calls` counts what the GPU was actually asked to draw THIS FRAME,
      // after frustum culling. The gap between them is what culling is worth, and a perf claim made
      // from the first number is a claim about work that may never happen. Both are here on purpose:
      // `mesh` tracks the geometry budget (and leaks), `draws` tracks the frame.
      onStats(`${biomeAt(Math.floor(p.x), Math.floor(p.z), SEED, bh, DEFAULT_DEPTH.seaLevel)} · `
        + `${cols.current.size} col · ${drawn.current.size} mesh · ${info.render.calls} draws · `
        + `${(info.render.triangles / 1000).toFixed(0)}k tris · ${drops.current.length} drops · `
        + `geo ${info.memory.geometries} prog ${info.programs?.length ?? 0} · `
        + `${built} edits saved · ${worker.current ? 'worker' : 'main'}`)
    }

    // ── flush edits ──────────────────────────────────────────────────────────────────────────
    // ★ Debounced, not per-block. Mining is a stream of edits and an IndexedDB write per broken
    // block would put a transaction on every swing. Once a second is imperceptible to a player and
    // invisible to the frame budget.
    if (frame.current % 60 === 0 && dirtySaves.current.size) {
      flushSaves()
    }

    // ── evict ────────────────────────────────────────────────────────────────────────────────
    if (frame.current % 120 === 0) {
      const keep = new Set<string>()
      const R = settings.viewRadius
      for (let dz = -R; dz <= R; dz++) for (let dx = -R; dx <= R; dx++) keep.add(key(cx + dx, cz + dz))
      for (const [mk, m] of drawn.current) {
        // Keys are `cx,cz:<pass>` — `s`, `w` or `l`. Split on the ':' to get back the column key
        // the keep-set is built from; the column part holds a comma, never a colon.
        if (keep.has(mk.slice(0, mk.indexOf(':')))) continue
        g.remove(m); m.geometry.dispose(); drawn.current.delete(mk)
      }
      for (const kk of [...cols.current.keys()]) if (!keep.has(kk)) { cols.current.delete(kk); floraDirty.current = true }
      for (const kk of [...requested.current]) if (!keep.has(kk)) requested.current.delete(kk)
      for (const kk of [...lightCache.current.keys()]) if (!keep.has(kk)) lightCache.current.delete(kk)
      // The worker mirrors this eviction, or its column cache grows by every chunk ever visited.
      worker.current?.postMessage({ type: 'evict', keep: [...keep] })
      // ⚠ EDITS ARE NOT EVICTED WITH THEIR COLUMN. Walking away from a house and back must not lose
      // it — the column is regenerable, the edits are not. Any still-unsaved ones are flushed first,
      // because dropping the column while its diff sits in `dirtySaves` is exactly how a build
      // vanishes on a walk.
      flushSaves()
    }
  })

  return (
    <>
      <group ref={group} />
      <group ref={dropGroup} />
      <primitive object={pieces.group} />
      <primitive object={greg.group} />
      <primitive object={steam.points} />
      <primitive object={mist.points} />
      <primitive object={mist.residents} />
      <primitive object={flora.group} />
      {/* ⚠ Memoised. Inline `args={[new THREE.BoxGeometry(...)]}` builds a fresh geometry on EVERY
          React render and leaks the previous one — same family as the per-drop material that got
          the page's WebGL context blocked. */}
      <lineSegments ref={highlight} visible={false} geometry={highlightGeo}>
        <lineBasicMaterial color="#000000" transparent opacity={0.55} />
      </lineSegments>
    </>
  )
}

/**
 * Greg's dialogue box (E). Same plate styling as `CraftPanel` below — one dark plate, one border,
 * font-mono at the same size — so the two overlays read as the same UI system rather than two.
 *
 * ★ NO CHOICES. This is phase 1 (mechanics, placeholder dialogue): one line, one dismiss. A branching
 * conversation tree is a cozy-voice-pass concern, not a wiring one.
 */
const CHAT_KIND_CLASS = { you: 'text-white/85', out: 'text-white/60', err: 'text-rose-300/90' } as const

/**
 * The chat console — MC's chat model, sized to ours.
 *
 * CLOSED: the last few lines float bottom-left and fade out (the HUD feed; MC holds ~3s, ours a
 * touch longer). OPEN (T / Enter / '/'): full scrollback, a suggestion strip above the input
 * (Tab applies the highlighted one; typing narrows), ArrowUp/Down history, Enter sends and
 * closes on an empty line, Esc closes. A leading '/' makes it a command; else it's chat.
 * The INPUT tag is the shield: both window-level key handlers drop input-targeted events, so
 * touch-typing 'w' here never walks the player.
 */
function ChatConsole({ open, seed, log, ctx, onSubmit, onClose }: {
  open: boolean
  seed: string
  log: { id: number; text: string; kind: 'you' | 'out' | 'err'; at: number }[]
  ctx: ConsoleCtx
  onSubmit: (line: string) => void
  onClose: () => void
}) {
  const [line, setLine] = useState(seed)
  const hist = useRef<string[]>([])
  const histAt = useRef(-1)
  const scrollRef = useRef<HTMLDivElement>(null)
  // Re-seed on each open ('/' arrives pre-slashed); the component stays mounted for the feed.
  useEffect(() => { if (open) { setLine(seed); histAt.current = -1 } }, [open, seed])
  useEffect(() => { const el = scrollRef.current; if (el) el.scrollTop = el.scrollHeight }, [log, open])

  const sug = suggestionsFor(line, ctx)
  const submit = () => {
    const l = line.trim()
    if (!l) { onClose(); return }
    hist.current.unshift(l)
    onSubmit(l)
    setLine('')
  }

  if (!open) {
    // The HUD feed: only lines young enough to still matter; each fades via CSS once mounted.
    const cutoff = Date.now() - 10_000
    const recent = log.filter(m => m.at > cutoff).slice(-8)
    if (recent.length === 0) return null
    return (
      <div className="absolute left-3 bottom-3 w-[460px] font-mono text-[11px] pointer-events-none">
        <style>{`@keyframes shimmerchatfade { to { opacity: 0 } }`}</style>
        {recent.map(m => (
          <div key={m.id} className={`px-2 py-0.5 bg-black/45 rounded-sm whitespace-pre-wrap ${CHAT_KIND_CLASS[m.kind]}`}
               style={{ animation: 'shimmerchatfade 1s ease 6s forwards' }}>
            {m.text}
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className="absolute left-3 bottom-3 w-[460px] font-mono text-[11px] pointer-events-auto">
      {log.length > 0 && (
        <div ref={scrollRef} className="mb-1 px-2 py-1.5 bg-black/70 border border-white/10 rounded max-h-52 overflow-y-auto">
          {log.map(m => (
            <div key={m.id} className={`whitespace-pre-wrap ${CHAT_KIND_CLASS[m.kind]}`}>{m.text}</div>
          ))}
        </div>
      )}
      {sug.options.length > 0 && (
        <div className="mb-1 px-2 py-1 bg-black/80 border border-white/10 rounded text-sky-200/80">
          {sug.options.map((o, i) => (
            <span key={o}>{i > 0 && <span className="text-white/25"> · </span>}{i === 0 ? <span className="text-sky-100">{o}</span> : o}</span>
          ))}
          <span className="text-white/30 float-right">tab</span>
        </div>
      )}
      <div className="flex items-center gap-1.5 px-2 py-1.5 bg-black/80 border border-white/15 rounded">
        <span className="text-amber-200/80">›</span>
        <input
          autoFocus value={line} onChange={e => setLine(e.target.value)}
          onKeyDown={e => {
            e.stopPropagation()
            if (e.key === 'Enter') submit()
            else if (e.key === 'Escape') onClose()
            else if (e.key === 'Tab') { e.preventDefault(); if (sug.options.length) setLine(sug.apply(sug.options[0])) }
            else if (e.key === 'ArrowUp') { const h = hist.current; if (h.length) { histAt.current = Math.min(h.length - 1, histAt.current + 1); setLine(h[histAt.current]) } e.preventDefault() }
            else if (e.key === 'ArrowDown') { const h = hist.current; histAt.current = Math.max(-1, histAt.current - 1); setLine(histAt.current === -1 ? '' : h[histAt.current]); e.preventDefault() }
          }}
          placeholder="chat — or / for commands"
          className="flex-1 bg-transparent outline-none text-white/90 placeholder:text-white/25"
        />
        <span className="text-white/30">esc</span>
      </div>
    </div>
  )
}

function GregDialogue({ stage, onClose }: { stage: TutorialStage; onClose: () => void }) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-black/50 pointer-events-auto" onClick={onClose}>
      <div className="w-[420px] bg-[#0e1018]/95 border border-white/12 rounded-lg p-4 font-mono text-[11px]"
           onClick={(e) => e.stopPropagation()}>
        <div className="flex items-baseline justify-between mb-3">
          <span className="text-white/95 font-semibold tracking-[.18em] uppercase">Gregory</span>
          <button onClick={onClose} className="text-white/40 hover:text-white/80">esc</button>
        </div>
        <div className="text-white/85 leading-relaxed whitespace-pre-line">{GREG_LINE[stage]}</div>
        <div className="mt-3 text-white/40 text-[10px] uppercase tracking-[.14em]">E / esc — close</div>
      </div>
    </div>
  )
}

/**
 * The crafting surface (C).
 *
 * ★ IT LISTS WHAT YOU CANNOT AFFORD, AND THAT IS THE POINT. C used to silently auto-craft the best
 * tool you could pay for, which is why nobody noticed the entire forestry ladder was uncraftable:
 * you pressed a key, nothing happened, and the game never said whether that meant "no materials",
 * "already have it", or "this is impossible". A greyed row with its costs showing turns a dead key
 * into a goal.
 *
 * Two sections, one surface. Refining comes from the pure-core table (`voxel/recipes.ts`); tools
 * keep their own canon table (`engine/tools.ts`, blades→forestry / spikes→prospecting) and are
 * shown here rather than given a second window.
 *
 * `tick` is the re-render handle: the inventory is a ref that crafting mutates in place, so this
 * panel has no other way to know its counts changed.
 */
function CraftPanel({ have, tools, tick, station, onCraft, onCraftTool, onClose }: {
  have: (itemId: string) => number
  tools: React.RefObject<EquippedTools>
  tick: number
  /** 'crafting_table' when standing near a placed one — station-gated recipes light up. */
  station: Station
  onCraft: (id: string) => void
  onCraftTool: (id: string) => void
  onClose: () => void
}) {
  const label = (id: string) => id.replace(/_/g, ' ')
  const Cost = ({ items }: { items: { itemId: string; count: number }[] }) => (
    <span className="text-white/45">
      {items.map((c, i) => (
        <span key={c.itemId} className={have(c.itemId) >= c.count ? 'text-emerald-300/70' : 'text-rose-300/60'}>
          {i > 0 && <span className="text-white/25"> · </span>}
          {label(c.itemId)} {have(c.itemId)}/{c.count}
        </span>
      ))}
    </span>
  )

  // The next unearned tier per skill. Showing all nine at once buries the one you are working
  // toward; showing only what you can afford is what hid the bug in the first place.
  const nextTools = (['forestry', 'prospecting'] as const).flatMap((skillId) => {
    const held = getEquippedTool(tools.current!, skillId)
    const heldTier = held ? (getToolDef(held)?.tier ?? 0) : 0
    const next = Object.values(TOOL_DEFS)
      .filter(d => !d.basic && d.skillId === skillId && d.tier > heldTier)
      .sort((a, b) => a.tier - b.tier)[0]
    return next ? [next] : []
  })

  const rows = RECIPES.filter(r => r.input.every(i => have(i.itemId) > 0 || canCraftRecipe(r.id, have, station)))

  return (
    <div className="absolute inset-0 grid place-items-center bg-black/50 pointer-events-auto" onClick={onClose}>
      <div className="w-[440px] max-h-[80vh] overflow-y-auto bg-[#0e1018]/95 border border-white/12 rounded-lg p-4 font-mono text-[11px]"
           onClick={(e) => e.stopPropagation()}>
        <div className="flex items-baseline justify-between mb-3">
          <span className="text-white/95 font-semibold tracking-[.18em] uppercase">Crafting
            {station === 'crafting_table' && <span className="ml-2 text-amber-200/70 normal-case tracking-normal font-normal">at table</span>}
          </span>
          <button onClick={onClose} className="text-white/40 hover:text-white/80">esc</button>
        </div>

        <div className="text-white/40 tracking-[.14em] uppercase text-[9px] mb-1.5">Refine</div>
        {rows.length === 0 && <div className="text-white/35 mb-3">nothing to refine — go cut a tree</div>}
        {rows.map((r: RecipeDef) => {
          const can = canCraftRecipe(r.id, have, station)
          // A row locked by WHERE you are must say so — greyed-with-costs-green reads as a bug.
          const needsTable = r.station === 'crafting_table' && station !== 'crafting_table'
          return (
            <button key={r.id} disabled={!can} onClick={() => onCraft(r.id)}
                    className={`w-full text-left mb-1 px-2 py-1.5 rounded border transition-colors ${
                      can ? 'border-white/15 hover:border-amber-200/50 hover:bg-white/5 text-white/90'
                          : 'border-white/5 text-white/30 cursor-not-allowed'}`}>
              <div className="flex justify-between gap-3">
                <span>{r.name}</span>
                {/* Both numbers, always — the same honesty the bench panel owes. A player who
                    refines in the field should be able to see what a station would have given him
                    at the moment he decides, not discover it later.
                    ★ AND IT NAMES THE STATION NOW, because with three of them "milled" stopped
                    being an answer: the mill's bonus is not the cutter's, and a bare "3× milled"
                    beside a stone row would send a player to whichever bench he owns to find the
                    number is 2. `payingStations` is empty for assembly rows, which stay silent. */}
                {(() => {
                  const pays = payingStations(r)
                  const at = pays[0]
                  return (
                    <span className="text-amber-200/70 tabular-nums">{r.output.count}× {label(r.output.itemId)}
                      {at && <span className="text-white/30"> · {milledYield(r, at)}× at {at.name.toLowerCase()}</span>}
                    </span>
                  )
                })()}
              </div>
              <div className="mt-0.5 text-[10px]">
                <Cost items={r.input} />
                {needsTable && <span className="text-sky-300/60"> · at a crafting table</span>}
              </div>
            </button>
          )
        })}

        <div className="text-white/40 tracking-[.14em] uppercase text-[9px] mt-4 mb-1.5">Tools
          {station !== 'crafting_table' && <span className="ml-2 text-sky-300/60 normal-case tracking-normal">bench work — stand at a crafting table</span>}
        </div>
        {nextTools.length === 0 && <div className="text-white/35">every tier earned</div>}
        {nextTools.map((d) => {
          // Counted through `have` rather than `canCraftTool`, which wants a whole Inventory (and a
          // BankState) — the panel only ever needs counts, and faking an Inventory to ask a
          // yes/no question is how a display drifts from the thing that actually spends.
          // `onCraftTool` still calls the real `canCraftTool` before spending; this only greys a row.
          // Tools are bench work: away from a table the whole section shows as goals, not buttons.
          const can = station === 'crafting_table' && d.recipe.every(i => have(i.itemId) >= i.count)
          return (
            <button key={d.id} disabled={!can} onClick={() => onCraftTool(d.id)}
                    className={`w-full text-left mb-1 px-2 py-1.5 rounded border transition-colors ${
                      can ? 'border-white/15 hover:border-amber-200/50 hover:bg-white/5 text-white/90'
                          : 'border-white/5 text-white/30 cursor-not-allowed'}`}>
              <div className="flex justify-between gap-3">
                <span>{d.name}</span>
                <span className="text-white/45">tier {d.tier} {d.skillId}</span>
              </div>
              <div className="mt-0.5 text-[10px]"><Cost items={d.recipe} /></div>
            </button>
          )
        })}
      </div>
    </div>
  )
}

/**
 * The bench's standing job — load it, walk away, come back to the pile.
 *
 * ★ THE PANEL OWNS NO STATE ABOUT THE JOB. Every number on screen is derived on render from the
 * job the host handed in plus `Date.now()`, exactly as `workshop.ts` intends: nothing is simulated,
 * so a panel opened on a bench that has been running for two hours is already correct, and one left
 * open cannot drift away from what the world thinks. The 500ms `tick` below only forces a repaint —
 * it never advances anything.
 *
 * ⚠ THE STATION IS NOT A GATE. Everything here is also craftable instantly by hand anywhere (see
 * `recipes.ts`), so this panel prints BOTH yields on every row. A player who refines in the field
 * is making an informed trade, not walking into a penalty he finds out about later.
 */
/**
 * Why a specialist's list is short, in the player's words. Keyed by `StationDef.accepts`, so a
 * fourth station gets its line by declaring a speciality rather than by someone remembering to add
 * a branch to the panel.
 */
const SPECIALITY_NOTE: Record<Exclude<StationDef['accepts'], 'any'>, string> = {
  wood: 'a sawmill takes timber, nothing else — stone and fittings are bench work',
  stone: 'a stonecutter takes masonry, nothing else — it is slower than the bench and wastes less',
}

function StationPanel({ st, have, inv, onChange, onSay, onClose }: {
  st: OpenStation
  have: (itemId: string) => number
  inv: React.RefObject<Inventory>
  onChange: () => void
  onSay: (t: string) => void
  onClose: () => void
}) {
  // Repaint handle only — see the header. 500ms is well under the 12s run so the bar never visibly
  // jumps, and costs nothing next to the frame loop already running behind this panel.
  const [, setBeat] = useState(0)
  useEffect(() => {
    const h = setInterval(() => setBeat(b => b + 1), 500)
    return () => clearInterval(h)
  }, [])

  const def = STATIONS[st.kind]
  const runMs = def.runMs
  const key = stationKey(st.x, st.y, st.z)
  // The job is read from the ref-backed record every render rather than captured once: `commit`
  // writes through the host, and a captured copy would leave the panel showing the job the player
  // just replaced.
  const [job, setJob] = useState<StationJob | undefined>(st.job)
  const now = Date.now()
  const label = (id: string) => id.replace(/_/g, ' ')

  const ready = job ? runsReady(job, now, runMs) : 0
  const r = job ? RECIPES.find(x => x.id === job.recipeId) : undefined

  const doCollect = () => {
    if (!job || !r || ready <= 0) return
    const { shop, payout } = collectStation({ [key]: job }, key, now, def)
    if (!payout) return
    give(inv.current!, payout.itemId, payout.count)
    st.commit(shop)
    setJob(shop[key])
    onChange()
    onSay(`${def.name.toLowerCase()} hands you ${payout.count}× ${label(payout.itemId)}`)
  }

  // ⚠ `rec`, NOT `def` — the outer `def` is this panel's STATION and every sibling closure reads it
  // for the rate and the yield. A local RecipeDef called `def` shadowed it here, which was harmless
  // while nothing in this function wanted the station and is a payout bug waiting for the day one
  // does. Two different `def`s in one component is a trap, not a naming preference.
  const doLoad = (recipeId: string, runs: number) => {
    if (runs <= 0) return
    const rec = RECIPES.find(x => x.id === recipeId)
    if (!rec) return
    // ⚠ SPEND FIRST, AND ONLY IF `loadJob` ACCEPTED. `loadJob` refuses to overwrite a live job, so
    // taking the input before asking would eat a bagful on a click the pure core then declined.
    const shop = loadStationJob({}, key, recipeId, runs, now)
    if (!shop[key]) return
    for (const c of jobCost(rec, runs)) removeItems(inv.current!, c.itemId, c.count)
    st.commit(shop)
    setJob(shop[key])
    onChange()
    onSay(`${def.name.toLowerCase()} sets to work — ${runs}× ${rec.name.toLowerCase()}`)
  }

  const busy = !!job && job.runs > 0
  const rows = stationRecipes(st.kind)

  return (
    <div className="absolute inset-0 grid place-items-center bg-black/50 pointer-events-auto" onClick={onClose}>
      <div className="w-[460px] max-h-[80vh] overflow-y-auto bg-[#0e1018]/95 border border-white/12 rounded-lg p-4 font-mono text-[11px]"
           onClick={(e) => e.stopPropagation()}>
        <div className="flex items-baseline justify-between mb-3">
          <span className="text-white/95 font-semibold tracking-[.18em] uppercase">{def.name}</span>
          <button onClick={onClose} className="text-white/40 hover:text-white/80">esc</button>
        </div>

        {busy && r ? (
          <div className="mb-4 rounded border border-amber-200/25 bg-amber-100/[0.03] px-3 py-2.5">
            <div className="flex justify-between items-baseline">
              <span className="text-amber-100/90">{r.name}</span>
              <span className="text-white/45 tabular-nums">{job!.runs} left</span>
            </div>
            {/* The bar is the CURRENT run, not the whole job: a job of 30 moves a whole-job bar so
                slowly it reads as broken, while a per-run bar visibly ticks and says the bench is
                alive. The count beside it carries the long story. */}
            <div className="mt-2 h-1 rounded bg-white/10 overflow-hidden">
              <div className="h-full bg-amber-200/60 transition-[width] duration-500"
                   style={{ width: `${Math.round(runProgress(job!, now, runMs) * 100)}%` }} />
            </div>
            <div className="mt-2 flex justify-between items-center">
              <span className="text-white/40 tabular-nums">
                {ready > 0 ? `${ready * milledYield(r, def)}× ${label(r.output.itemId)} waiting` : `${Math.ceil((runMs - (now - job!.since) % runMs) / 1000)}s to the next`}
              </span>
              <button disabled={ready <= 0} onClick={doCollect}
                      className={`px-2.5 py-1 rounded border transition-colors ${
                        ready > 0 ? 'border-amber-200/50 text-amber-100/90 hover:bg-amber-200/10'
                                  : 'border-white/5 text-white/25 cursor-not-allowed'}`}>
                take
              </button>
            </div>
          </div>
        ) : (
          <div className="mb-4 text-white/35">
            {def.name.toLowerCase()} is idle — give it something to work on
            {/* ★ THE SPECIALITY LINE IS DERIVED FROM `accepts`, not written per station. A hand-kept
                `st.kind === 'sawmill' && …` shipped station three with no explanation of why its
                list is short, which reads as a bug in the panel rather than as the design. */}
            {def.accepts !== 'any' && <span className="block mt-1 text-white/25">{SPECIALITY_NOTE[def.accepts]}</span>}
          </div>
        )}

        <div className="text-white/40 tracking-[.14em] uppercase text-[9px] mb-1.5">
          Set to work {busy && <span className="ml-2 text-sky-300/60 normal-case tracking-normal">finish the current job first</span>}
        </div>
        {rows.map((rec) => {
          const n = maxRuns(rec, have)
          const can = !busy && n > 0
          const bonus = milledYield(rec, def) > rec.output.count
          return (
            <button key={rec.id} disabled={!can} onClick={() => doLoad(rec.id, n)}
                    className={`w-full text-left mb-1 px-2 py-1.5 rounded border transition-colors ${
                      can ? 'border-white/15 hover:border-amber-200/50 hover:bg-white/5 text-white/90'
                          : 'border-white/5 text-white/30 cursor-not-allowed'}`}>
              <div className="flex justify-between gap-3">
                <span>{rec.name}</span>
                <span className="tabular-nums">
                  <span className={bonus ? 'text-amber-200/80' : 'text-white/45'}>{milledYield(rec, def)}×</span>
                  {bonus && <span className="text-white/25"> (by hand {rec.output.count}×)</span>}
                </span>
              </div>
              <div className="mt-0.5 text-[10px] text-white/40">
                {n > 0 ? `${n} run${n === 1 ? '' : 's'} from your bag` : `no ${label(rec.input[0].itemId)}`}
                {n >= MAX_RUNS && <span className="text-white/25"> · {def.name.toLowerCase()} holds no more</span>}
              </div>
            </button>
          )
        })}
      </div>
    </div>
  )
}

function SettingsPanel({ s, update, onClose }: {
  s: VoxelSettings
  update: (p: Partial<VoxelSettings>) => void
  onClose: () => void
}) {
  const Slider = ({ label, k }: { label: string; k: 'toon' | 'outline' | 'faceShading' | 'shadowLift' }) => (
    <label className="flex items-center gap-2 text-[11px] font-mono text-white/70">
      <span className="w-24 shrink-0">{label}</span>
      <input
        type="range" min={0} max={1} step={0.05} value={s[k]}
        onChange={e => update({ [k]: Number(e.target.value) } as Partial<VoxelSettings>)}
        className="flex-1 accent-amber-300"
      />
      <span className="w-8 text-right tabular-nums text-white/50">{s[k].toFixed(2)}</span>
    </label>
  )

  return (
    <div className="absolute top-3 right-3 w-72 bg-black/80 border border-white/15 rounded p-3 space-y-2.5">
      <div className="flex items-center justify-between">
        <span className="text-[11px] font-mono font-semibold tracking-wider text-white/90 uppercase">Render</span>
        <button onClick={onClose} className="text-white/40 hover:text-white/80 text-xs font-mono">esc / O</button>
      </div>

      <div className="flex gap-1.5">
        {(['natural', 'cartoon'] as RenderStyle[]).map(v => (
          <button
            key={v}
            onClick={() => update(withStyle(s, v))}
            className={`flex-1 py-1.5 rounded text-[11px] font-mono uppercase tracking-wider border
              ${s.style === v ? 'border-amber-300 text-amber-200 bg-amber-300/10' : 'border-white/15 text-white/50'}`}
          >{v}</button>
        ))}
      </div>

      {/* Each lever is exposed so the look can be judged by moving ONE at a time on the real world.
          A preset is a starting point; the call is Alex's. */}
      <Slider label="banding" k="toon" />
      <Slider label="outline" k="outline" />
      <Slider label="face light" k="faceShading" />
      <Slider label="shadow lift" k="shadowLift" />

      <div className="text-[11px] font-mono font-semibold tracking-wider text-white/90 uppercase pt-1">World</div>
      {/* Cost is QUADRATIC in this number (columns, meshes, light fields all scale with r²) —
          which is why it is a stepped slider with tested bounds, not a free number. */}
      <label className="flex items-center gap-2 text-[11px] font-mono text-white/70">
        <span className="w-24 shrink-0">view radius</span>
        <input
          type="range" min={VIEW_RADIUS_MIN} max={VIEW_RADIUS_MAX} step={1} value={s.viewRadius}
          onChange={e => update({ viewRadius: Number(e.target.value) })}
          className="flex-1 accent-amber-300"
        />
        <span className="w-14 text-right tabular-nums text-white/50">{s.viewRadius * 16} blk</span>
      </label>

      {/* ── ★ ITS OWN SECTION, because it is the one setting that changes nothing about the world ──
          Everything above is a look or a budget; this is an instrument. Keeping it out of Render
          also keeps it out of PRESETS, so flipping natural↔cartoon mid-measurement cannot switch
          off the meter you are measuring with. */}
      <div className="text-[11px] font-mono font-semibold tracking-wider text-white/90 uppercase pt-1">Debug</div>
      <label className="flex items-center gap-2 text-[11px] font-mono text-white/70 cursor-pointer">
        <input
          type="checkbox" checked={s.showFps}
          onChange={e => update({ showFps: e.target.checked })}
          className="accent-amber-300"
        />
        <span>frame meter</span>
        <span className="ml-auto text-white/35">fps · ms · worst</span>
      </label>

      <p className="text-[10px] leading-relaxed text-white/35 font-mono pt-1">
        Both shading paths live in one shader program and are picked by a uniform, so switching
        costs nothing. Settings persist.
      </p>
    </div>
  )
}
